function set_put(string $key, string $value): void
{
    DB::exec('INSERT INTO settings(key, value) VALUES(?, ?) '
        . 'ON CONFLICT(key) DO UPDATE SET value=excluded.value', [$key, $value]);
}

function set_get(string $key, ?string $default = null): string
{
    $row = DB::one('SELECT value FROM settings WHERE key=?', [$key]);
    if ($row === null) {
        return $default ?? (SETTING_DEFAULTS[$key] ?? '');
    }
    return (string) $row['value'];
}

function set_int(string $key, int $default = 0): int
{
    $value = set_get($key, (string) $default);
    return $value === '' ? $default : (int) $value;
}

function set_bool(string $key, bool $default = false): bool
{
    $value = set_get($key, $default ? '1' : '0');
    return $value === '1';
}

function settings_bootstrap(): void
{
    // درخواست کاربر: پنل‌های وصل‌شدهٔ قبلی یک‌بار پاک شوند تا با API Key دوباره وصل شود
    if (DB::one("SELECT key FROM settings WHERE key='panel_reset_3410'") === null) {
        $connected = (int) DB::val('SELECT COUNT(*) FROM pg_panels', [], 0);
        if ($connected > 0) {
            DB::exec('DELETE FROM pg_panels');
            DB::exec('UPDATE products SET panel_id=NULL');
            log_line('info', 'removed ' . $connected . ' connected panel(s); reconnect with an API key');
        }
        set_put('panel_reset_3410', '1');
    }
    if (function_exists('pay_settings_bootstrap')) {
        pay_settings_bootstrap();
    }
    foreach (SETTING_DEFAULTS as $key => $value) {
        if (DB::one('SELECT key FROM settings WHERE key=?', [$key]) === null) {
            set_put($key, $value);
        }
    }
}

/* 5) Telegram client */

/**
 * POST JSON با ext-curl یا (اگر نصب نبود) با باینری curl.
 * خروجی: [بدنه یا null, متن خطا]
 */
function http_post_json(string $url, array $payload, int $timeout = 60): array
{
    $json = json_encode($payload, JSON_UNESCAPED_UNICODE);
    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_POST           => true,
            CURLOPT_POSTFIELDS     => $json,
            CURLOPT_HTTPHEADER     => ['Content-Type: application/json'],
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT        => $timeout,
        ]);
        $body = curl_exec($ch);
        $error = curl_error($ch);
        curl_close($ch);
        return $body === false ? [null, $error] : [(string) $body, ''];
    }
    $binary = curl_binary();
    if ($binary === '') {
        return [null, 'neither ext-curl nor the curl binary is available'];
    }
    $tmp = tempnam(sys_get_temp_dir(), 'panel-post-');
    file_put_contents($tmp, $json);
    $cmd = escapeshellcmd($binary) . ' -sS --max-time ' . (int) $timeout
        . ' -X POST -H ' . escapeshellarg('Content-Type: application/json')
        . ' --data-binary ' . escapeshellarg('@' . $tmp)
        . ' ' . escapeshellarg($url) . ' 2>&1';
    $body = shell_exec($cmd);
    @unlink($tmp);
    if ($body === null || $body === '') {
        return [null, 'curl binary returned nothing'];
    }
    return [(string) $body, ''];
}

function curl_binary(): string
{
    static $path = null;
    if ($path === null) {
        $path = '';
        foreach (['/usr/bin/curl', '/usr/local/bin/curl', '/bin/curl'] as $candidate) {
            if (is_executable($candidate)) {
                $path = $candidate;
                break;
            }
        }
        if ($path === '' && trim((string) shell_exec('command -v curl 2>/dev/null')) !== '') {
            $path = trim((string) shell_exec('command -v curl'));
        }
    }
    return $path;
}

/**
 * ایموجی‌های استاندارد یونیکد که روی هر اکانتی (عادی و پریمیوم) درست
 * نمایش داده می‌شوند. اگر جایی از ایموجی سفارشی (custom emoji) استفاده شد،
 * این لایه آن را به همین یونیکدها برمی‌گرداند تا دکمه هرگز خطای ۴۰۰ ندهد.
 */
const PLAIN_EMOJI_FALLBACK = [
    '⚙️', '🔌', '📊', '💳', '👥', '📢', '📦', '👤', '💰', '🛡',
    '🧾', '📈', '🔍', '🎁', '🎫', '💾', '♻️', '🪪', '☎️', '🔙',
];

/** متن را از تگ‌های ایموجی سفارشی پاک می‌کند و متن سادهٔ آن را می‌گذارد */
function tg_plain_text(string $text): string
{
    /* <tg-emoji emoji-id="…">😀</tg-emoji> → 😀 */
    $clean = preg_replace('~<tg-emoji[^>]*>(.*?)</tg-emoji>~su', '$1', $text);
    return is_string($clean) ? $clean : $text;
}

/** یک دکمه را از ایموجی سفارشی خالی می‌کند */
function tg_plain_button(array $button): array
{
    if (isset($button['icon_custom_emoji_id'])) {
        unset($button['icon_custom_emoji_id']);
    }
    if (isset($button['text'])) {
        $button['text'] = tg_plain_text((string) $button['text']);
    }
    foreach (['copy_text', 'switch_inline_query_chosen_chat'] as $key) {
        if (isset($button[$key]) && is_array($button[$key])) {
            $button[$key] = $button[$key];
        }
    }
    return $button;
}

/** کیبورد کامل را به شکل سازگار با همهٔ اکانت‌ها برمی‌گرداند */
function tg_plain_kb(?array $kb): ?array
{
    if ($kb === null) {
        return null;
    }
    $out = [];
    foreach ($kb as $row) {
        $cleanRow = [];
        foreach ((array) $row as $button) {
            $cleanRow[] = tg_plain_button((array) $button);
        }
        if ($cleanRow) {
            $out[] = $cleanRow;
        }
    }
    return $out;
}

/** آیا خطای تلگرام مربوط به ایموجی سفارشی / نبود پریمیوم است؟ */
function tg_custom_emoji_error(string $description): bool
{
    $needle = mb_strtolower($description);
    foreach (['custom_emoji', 'custom emoji', 'emoji_id', 'premium', 'button_text_invalid',
              "can't parse entities", 'unsupported'] as $hint) {
        if (str_contains($needle, $hint)) {
            return true;
        }
    }
    return false;
}

final class Tg
{
    public static bool $dry = false;
    public static array $answered = [];
    public static ?string $pendingAnswer = null;
    public static int $photoSeq = 500;
    public static array $outbox = [];
    /** جلوگیری از حلقهٔ بی‌پایان وقتی تلگرام حتی با ایموجی استاندارد هم خطا می‌دهد */
    public static bool $plainRetry = false;
    /** برای تست: پاسخ ساختگی getChat در حالت خشک */
    public static ?array $chatStub = null;
    /** برای تست: پاسخ ساختگی getChatMember در حالت خشک (true/false/null) */
    public static ?bool $memberStub = null;
    /** برای تست: پاسخ ساختگی getMe (username) در حالت خشک */
    public static ?array $meStub = null;
    private static int $topicSeq = 100;
    private static int $updateOffset = 0;

    public static function call(string $method, array $params = []): ?array
    {
        if (self::$dry) {
            self::$outbox[] = [$method, $params];
            return ['ok' => true, 'result' => ['message_id' => count(self::$outbox)]];
        }
        $token = bot_token();
        if ($token === '') {
            log_line('error', 'PANEL_BOT_TOKEN is empty');
            return null;
        }
        $url = "https://api.telegram.org/bot{$token}/{$method}";
        [$body, $error] = http_post_json($url, $params);
        if ($body === null) {
            log_line('warning', "telegram $method failed: $error");
            return null;
        }
        $json = json_decode((string) $body, true);
        if (!is_array($json) || ($json['ok'] ?? false) !== true) {
            $description = is_array($json) ? (string) ($json['description'] ?? 'unknown error')
                : 'bad json';
            /* اگر خطا مربوط به ایموجی سفارشی/پریمیوم باشد، همان درخواست یک‌بار
               با ایموجی‌های استاندارد تکرار می‌شود تا دکمه‌ها هرگز از کار نیفتند */
            if (tg_custom_emoji_error($description) && empty(self::$plainRetry)) {
                self::$plainRetry = true;
                try {
                    $plain = $params;
                    if (isset($plain['text'])) {
                        $plain['text'] = tg_plain_text((string) $plain['text']);
                    }
                    if (isset($plain['caption'])) {
                        $plain['caption'] = tg_plain_text((string) $plain['caption']);
                    }
                    if (isset($plain['reply_markup']['inline_keyboard'])) {
                        $plain['reply_markup']['inline_keyboard'] =
                            tg_plain_kb((array) $plain['reply_markup']['inline_keyboard']);
                    }
                    log_line('info', 'telegram ' . $method . ': retried with standard emoji',
                        ['reason' => $description]);
                    $retry = self::call($method, $plain);
                    return $retry;
                } finally {
                    self::$plainRetry = false;
                }
            }
            if (!str_contains($description, 'message is not modified')) {
                log_line('warning', "telegram $method: $description");
            }
            return is_array($json) ? $json : null;
        }
        return $json;
    }

    public static function send(int|string $chat, string $text, ?array $kb = null): ?int
    {
        $params = ['chat_id' => $chat, 'text' => $text, 'parse_mode' => 'HTML',
                   'disable_web_page_preview' => true];
        $kb = kb_ensure_back(kb_clean($kb));
        if ($kb !== null) {
            $params['reply_markup'] = ['inline_keyboard' => $kb];
        }
        $result = self::call('sendMessage', $params);
        return (int) ($result['result']['message_id'] ?? 0);
    }

    public static function edit(int|string $chat, int $messageId, string $text, ?array $kb = null): void
    {
        $params = ['chat_id' => $chat, 'message_id' => $messageId, 'text' => $text,
                   'parse_mode' => 'HTML', 'disable_web_page_preview' => true];
        $kb = kb_ensure_back(kb_clean($kb));
        if ($kb !== null) {
            $params['reply_markup'] = ['inline_keyboard' => $kb];
        }
        self::call('editMessageText', $params);
    }

    public static function delete(int|string $chat, int $messageId): void
    {
        if ($messageId <= 0) {
            return;
        }
        self::call('deleteMessage', ['chat_id' => $chat, 'message_id' => $messageId]);
    }

    /** ادیت اگر شد، وگرنه پیام تازه — همان رفتار show() در نسخهٔ پایتون */
    public static function show(int|string $chat, ?int $messageId, string $text, ?array $kb = null): void
    {
        $kb = kb_ensure_back(kb_clean($kb));
        if ($messageId) {
            $result = self::call('editMessageText', [
                'chat_id' => $chat, 'message_id' => $messageId, 'text' => $text,
                'parse_mode' => 'HTML', 'disable_web_page_preview' => true,
                'reply_markup' => $kb === null ? null : ['inline_keyboard' => $kb],
            ]);
            if ($result !== null && (($result['ok'] ?? false) === true
                    || str_contains((string) ($result['description'] ?? ''), 'not modified'))) {
                return;
            }
        }
        self::send($chat, $text, $kb);
    }

    public static function photo(int|string $chat, string $fileId, string $caption, ?array $kb = null): void
    {
        $params = ['chat_id' => $chat, 'photo' => $fileId, 'caption' => $caption,
                   'parse_mode' => 'HTML'];
        $kb = kb_ensure_back(kb_clean($kb));
        if ($kb !== null) {
            $params['reply_markup'] = ['inline_keyboard' => $kb];
        }
        self::call('sendPhoto', $params);
    }

    /** ارسال عکس به یک تاپیک — خروجی: شناسهٔ پیام */
    public static function photoThread(int|string $chat, string $fileId, string $caption,
                                       int $threadId = 0, ?array $kb = null): int
    {
        $params = ['chat_id' => $chat, 'photo' => $fileId, 'caption' => $caption,
                   'parse_mode' => 'HTML'];
        if ($threadId > 0) {
            $params['message_thread_id'] = $threadId;
        }
        if ($kb !== null) {
            $params['reply_markup'] = ['inline_keyboard' => $kb];
        }
        if (self::$dry) {
            self::$outbox[] = ['sendPhoto', $params];
            return (int) (self::$photoSeq = self::$photoSeq + 1);
        }
        $result = self::call('sendPhoto', $params);
        return (int) ($result['result']['message_id'] ?? 0);
    }

    /**
     * آپلود یک عکس از مسیر محلی (multipart) و برگرداندن file_id.
     * برای ارسال بنر نمونهٔ کارت در KYC لازم است؛ اگر ناموفق باشد '' برمی‌گردد.
     */
    public static function uploadPhoto(int|string $chat, string $path, string $caption = '',
                                       int $threadId = 0): string
    {
        if (self::$dry) {
            self::$outbox[] = ['sendPhoto', ['chat_id' => $chat, 'path' => $path,
                'caption' => $caption, 'message_thread_id' => $threadId]];
            return 'DRY-PHOTO-ID';
        }
        $token = bot_token();
        if ($token === '' || !is_file($path)) {
            return '';
        }
        $content = @file_get_contents($path);
        if ($content === false || $content === '') {
            return '';
        }
        $boundary = 'panel' . bin2hex(random_bytes(12));
        $fields = ['chat_id' => (string) $chat];
        if ($caption !== '') {
            $fields['caption'] = $caption;
            $fields['parse_mode'] = 'HTML';
        }
        if ($threadId > 0) {
            $fields['message_thread_id'] = (string) $threadId;
        }
        $body = '';
        foreach ($fields as $key => $value) {
            $body .= '--' . $boundary . "\r\n"
                . 'Content-Disposition: form-data; name="' . $key . '"' . "\r\n\r\n"
                . $value . "\r\n";
        }
        $body .= '--' . $boundary . "\r\n"
            . 'Content-Disposition: form-data; name="photo"; filename="banner.jpg"' . "\r\n"
            . "Content-Type: image/jpeg\r\n\r\n"
            . $content . "\r\n"
            . '--' . $boundary . "--\r\n";
        $url = "https://api.telegram.org/bot{$token}/sendPhoto";
        [$raw, $error] = http_request('POST', $url,
            ['Content-Type: multipart/form-data; boundary=' . $boundary], $body, false, 120);
        if ($raw === null) {
            log_line('warning', 'sendPhoto upload failed: ' . $error);
            return '';
        }
        $json = json_decode((string) $raw, true);
        if (!is_array($json) || ($json['ok'] ?? false) !== true) {
            log_line('warning', 'sendPhoto upload: ' . mb_substr((string) $raw, 0, 200));
            return '';
        }
        $sizes = $json['result']['photo'] ?? [];
        $best = is_array($sizes) && $sizes ? end($sizes) : [];
        return (string) ($best['file_id'] ?? '');
    }

    /** ویرایش کپشن یک عکس (کارت رسید) */
    public static function editCaption(int|string $chat, int $messageId, string $caption,
                                       ?array $kb = null): void
    {
        $params = ['chat_id' => $chat, 'message_id' => $messageId, 'caption' => $caption,
                   'parse_mode' => 'HTML'];
        if ($kb !== null) {
            $params['reply_markup'] = ['inline_keyboard' => $kb];
        } else {
            $params['reply_markup'] = ['inline_keyboard' => []];
        }
        if (self::$dry) {
            self::$outbox[] = ['editMessageCaption', $params];
            return;
        }
        self::call('editMessageCaption', $params);
    }

    /** پاسخ سرتاسری را به آخر کار موکول می‌کند تا شعبه‌ها بتوانند خودشان جواب بدهند */
    public static function answer_later(string $callbackId): void
    {
        self::$pendingAnswer = $callbackId;
    }

    public static function answer(string $callbackId, string $text = '', bool $alert = false): void
    {
        if (self::$pendingAnswer !== null && self::$pendingAnswer === $callbackId) {
            self::$pendingAnswer = null;
        }
        if ($callbackId !== '' && isset(self::$answered[$callbackId])) {
            return;   // تلگرام برای پاسخ دوم خطا می‌دهد
        }
        if ($callbackId !== '') {
            self::$answered[$callbackId] = true;
            if (count(self::$answered) > 200) {
                self::$answered = array_slice(self::$answered, -100, null, true);
            }
        }
        self::call('answerCallbackQuery', [
            'callback_query_id' => $callbackId,
            'text'              => $text,
            'show_alert'        => $alert,
        ]);
    }

    /** ارسال پیام به یک تاپیک داخل گروه (message_thread_id) */
    public static function sendThread(int|string $chat, string $text, int $threadId = 0,
                                      ?array $kb = null): ?int
    {
        $params = ['chat_id' => $chat, 'text' => $text, 'parse_mode' => 'HTML',
                   'disable_web_page_preview' => true];
        if ($threadId > 0) {
            $params['message_thread_id'] = $threadId;
        }
        $kb = kb_ensure_back(kb_clean($kb));
        if ($kb !== null) {
            $params['reply_markup'] = ['inline_keyboard' => $kb];
        }
        $result = self::call('sendMessage', $params);
        return (int) ($result['result']['message_id'] ?? 0);
    }

    /** کپی یک پیام در چت دیگر (برای فروارد همگانی) */
    public static function copyMessage(int|string $chat, int|string $fromChat, int $messageId): bool
    {
        if (self::$dry) {
            self::$outbox[] = ['copyMessage', ['chat_id' => $chat, 'from_chat_id' => $fromChat,
                'message_id' => $messageId]];
            return true;
        }
        $result = self::call('copyMessage', ['chat_id' => $chat, 'from_chat_id' => $fromChat,
            'message_id' => $messageId]);
        return is_array($result) && (($result['ok'] ?? false) === true);
    }

    /** سنجاق / لغو سنجاق پیام در چت کاربر */
    public static function pin(int|string $chat, int $messageId, bool $on = true): void
    {
        if (self::$dry) {
            self::$outbox[] = [$on ? 'pinChatMessage' : 'unpinChatMessage',
                ['chat_id' => $chat, 'message_id' => $messageId]];
            return;
        }
        self::call($on ? 'pinChatMessage' : 'unpinChatMessage',
            ['chat_id' => $chat, 'message_id' => $messageId]);
    }

    public static function unpinAll(int|string $chat): void
    {
        if (self::$dry) {
            self::$outbox[] = ['unpinAllChatMessages', ['chat_id' => $chat]];
            return;
        }
        self::call('unpinAllChatMessages', ['chat_id' => $chat]);
    }

    /** اطلاعات یک چت (برای بررسی گروه گزارشات) */
    public static function getChat(int|string $chat): ?array
    {
        if (self::$dry) {
            self::$outbox[] = ['getChat', ['chat_id' => $chat]];
            return self::$chatStub;
        }
        $result = self::call('getChat', ['chat_id' => $chat]);
        $info = $result['result'] ?? null;
        return is_array($info) ? $info : null;
    }

    /** ساخت تاپیک در گروه انجمنی — خروجی: شناسهٔ تاپیک یا 0 */
    public static function createTopic(int|string $chat, string $name): int
    {
        if (self::$dry) {
            self::$outbox[] = ['createForumTopic', ['chat_id' => $chat, 'name' => $name]];
            if (self::$chatStub === null) {
                return 0;
            }
            return ++self::$topicSeq;
        }
        $result = self::call('createForumTopic', ['chat_id' => $chat, 'name' => $name]);
        return (int) ($result['result']['message_thread_id'] ?? 0);
    }

    /**
     * ارسال فایل به چت/تاپیک.
     * در حالت خشک فقط در outbox ثبت می‌شود.
     */
    public static function document(int|string $chat, string $path, string $caption = '',
                                    int $threadId = 0): bool
    {
        if (!is_file($path)) {
            return false;
        }
        if (self::$dry) {
            self::$outbox[] = ['sendDocument', ['chat_id' => $chat, 'path' => $path,
                'caption' => $caption, 'message_thread_id' => $threadId]];
            return true;
        }
        $token = bot_token();
        if ($token === '') {
            return false;
        }
        $content = @file_get_contents($path);
        if ($content === false) {
            log_line('warning', 'sendDocument: cannot read ' . $path);
            return false;
        }
        $name = basename($path);
        $boundary = 'panel' . bin2hex(random_bytes(12));
        $fields = ['chat_id' => (string) $chat, 'caption' => $caption];
        if ($threadId > 0) {
            $fields['message_thread_id'] = (string) $threadId;
        }
        $body = '';
        foreach ($fields as $key => $value) {
            $body .= '--' . $boundary . "\r\n"
                . 'Content-Disposition: form-data; name="' . $key . '"' . "\r\n\r\n"
                . $value . "\r\n";
        }
        $body .= '--' . $boundary . "\r\n"
            . 'Content-Disposition: form-data; name="document"; filename="' . $name . '"' . "\r\n"
            . "Content-Type: application/octet-stream\r\n\r\n"
            . $content . "\r\n"
            . '--' . $boundary . "--\r\n";
        $url = "https://api.telegram.org/bot{$token}/sendDocument";
        $headers = ['Content-Type: multipart/form-data; boundary=' . $boundary];
        [$raw, $error, $status] = http_request('POST', $url, $headers, $body, false, 300);
        if ($raw === null) {
            log_line('warning', 'sendDocument failed: ' . $error);
            return false;
        }
        $json = json_decode($raw, true);
        if (!is_array($json) || ($json['ok'] ?? false) !== true) {
            log_line('warning', 'sendDocument: ' . mb_substr($raw, 0, 200));
            return false;
        }
        return true;
    }

    /**
     * گرفتن فایل از تلگرام (بکاپ ارسالی مالک) و ذخیره در مسیر موقت.
     * خروجی: [مسیر فایل یا '', خطا]
     */
    public static function download(string $fileId, string $destDir = ''): array
    {
        $fileId = trim($fileId);
        if ($fileId === '') {
            return ['', 'شناسهٔ فایل خالی است'];
        }
        if (self::$dry) {
            self::$outbox[] = ['getFile', ['file_id' => $fileId]];
            return ['', 'dry-run'];
        }
        $token = bot_token();
        if ($token === '') {
            return ['', 'توکن ربات تنظیم نشده'];
        }
        $info = self::call('getFile', ['file_id' => $fileId]);
        $remote = (string) ($info['result']['file_path'] ?? '');
        if ($remote === '') {
            return ['', 'مسیر فایل از تلگرام نیامد'];
        }
        [$body, $error, $status] = http_request('GET',
            "https://api.telegram.org/file/bot{$token}/{$remote}", [], null, false, 300);
        if ($body === null || $status !== 200) {
            return ['', 'دانلود فایل انجام نشد: ' . ($error !== '' ? $error : 'HTTP ' . $status)];
        }
        $dir = $destDir !== '' ? rtrim($destDir, '/') : sys_get_temp_dir();
        $path = $dir . '/tg-' . bin2hex(random_bytes(4)) . '-'
            . basename($remote);
        if (@file_put_contents($path, $body) === false) {
            return ['', 'نوشتن فایل روی سرور انجام نشد'];
        }
        @chmod($path, 0600);
        return [$path, ''];
    }

    public static function getUpdates(int $timeout = 30): array
    {
        $result = self::call('getUpdates', [
            'offset'  => self::$updateOffset,
            'timeout' => $timeout,
            'allowed_updates' => ['message', 'callback_query'],
        ]);
        return $result['result'] ?? [];
    }

    public static function setOffset(int $offset): void
    {
        self::$updateOffset = $offset;
    }
}

/**
 * درخواست HTTP عمومی: با ext-curl اگر بود، وگرنه با باینری curl.
 * خروجی: [بدنه یا null, متن خطا, کد وضعیت]
 */
function http_request(string $method, string $url, array $headers = [], ?string $body = null,
                      bool $insecure = false, int $timeout = 25): array
{
    /* قلاب تست: درایورهای تست می‌توانند بدون شبکه پاسخ درگاه را شبیه‌سازی کنند */
    if (isset($GLOBALS['panel_http_mock']) && is_callable($GLOBALS['panel_http_mock'])) {
        return (array) call_user_func($GLOBALS['panel_http_mock'], $method, $url, $headers, $body);
    }
    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        $options = [
            CURLOPT_CUSTOMREQUEST  => strtoupper($method),
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT        => $timeout,
            CURLOPT_HTTPHEADER     => $headers,
        ];
        if ($body !== null) {
            $options[CURLOPT_POSTFIELDS] = $body;
        }
        if ($insecure) {
            $options[CURLOPT_SSL_VERIFYPEER] = false;
            $options[CURLOPT_SSL_VERIFYHOST] = 0;
        }
        curl_setopt_array($ch, $options);
        $result = curl_exec($ch);
        $error = curl_error($ch);
        $status = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        return $result === false ? [null, $error, 0] : [(string) $result, '', $status];
    }
    $binary = curl_binary();
    if ($binary === '') {
        return [null, 'neither ext-curl nor the curl binary is available', 0];
    }
    $tmpBody = null;
    $cmd = escapeshellcmd($binary) . ' -sS --max-time ' . (int) $timeout
        . ' -X ' . escapeshellarg(strtoupper($method))
        . ' -w ' . escapeshellarg('\n%{http_code}');
    if ($insecure) {
        $cmd .= ' -k';
    }
    foreach ($headers as $header) {
        $cmd .= ' -H ' . escapeshellarg($header);
    }
    if ($body !== null) {
        $tmpBody = tempnam(sys_get_temp_dir(), 'panel-body-');
        file_put_contents($tmpBody, $body);
        $cmd .= ' --data-binary ' . escapeshellarg('@' . $tmpBody);
    }
    $cmd .= ' ' . escapeshellarg($url) . ' 2>&1';
    $raw = shell_exec($cmd);
    if ($tmpBody !== null) {
        @unlink($tmpBody);
    }
    if ($raw === null || $raw === '') {
        return [null, 'curl binary returned nothing', 0];
    }
    $split = strrpos(rtrim($raw, "\n"), "\n");
    if ($split === false) {
        return [$raw, '', 0];
    }
    $payload = substr($raw, 0, $split);
    $status = (int) trim(substr($raw, $split + 1));
    return [$payload, '', $status];
}

/**
 * ساخت دکمه. رنگ دکمه‌ها (style) همان قالب Bot API است که نسخهٔ پایتون هم
 * استفاده می‌کند؛ اگر تلگرام پشتیبانی نکند خودش نادیده می‌گیرد.
 */
/**
 * رنگ‌های دکمه‌های غیر از منوی اصلی — هر دکمه رنگ خودش را دارد
 * (ثابت است تا هر بار باز شدن صفحه، رنگ‌ها نپرند).
 */
function auto_style(string $seed): string
{
    $palette = ['primary', 'success', 'danger', 'primary', 'success'];
    $hash = (int) sprintf('%u', crc32($seed));
    return $palette[$hash % count($palette)];
}

function btn(string $text, ?string $data = null, ?string $url = null, string $style = 'auto'): array
{
    if ($style === 'auto') {
        $style = auto_style($text . '|' . (string) $data . '|' . (string) $url);
    }
    $button = ['text' => $text];
    if ($data !== null) {
        $button['callback_data'] = $data;
    }
    if ($url !== null) {
        $button['url'] = $url;
    }
    if ($style !== '') {
        $button['style'] = $style;
    }
    return $button;
}

/**
 * دکمهٔ کپی واقعی — با فیلد copy_text تلگرام همان لحظهٔ زدن دکمه، مقدار
 * داخل کلیپ‌بورد گوشی می‌نشیند؛ لازم نیست کاربر روی عدد بزند.
 */
function copy_btn(string $text, string $value, string $style = 'success'): array
{
    $button = ['text' => $text, 'copy_text' => ['text' => $value]];
    if ($style !== '') {
        $button['style'] = $style;
    }
    return $button;
}

/** @param array<int, array<int, array>> $rows */
function kb(array $rows): array
{
    return kb_clean($rows);
}

/**
 * هر صفحه‌ای که دکمه دارد، حتماً یک دکمهٔ «بازگشت» هم دارد.
 * مقصد: اگر صفحه مدیریتی باشد «مدیریت»، وگرنه «منوی اصلی».
 * @param array<int, array<int, array>>|null $rows
 */
/* ── تاریخچهٔ صفحه‌ها: دکمهٔ «بازگشت» یک‌مرحله برمی‌گردد ───────────────── */

function nav_scope(string $data): string
{
    return str_starts_with($data, 'ad:') ? 'ad' : 'user';
}

/** تاریخچهٔ هر بخش جداست: خرید/پنل‌ها یک تاریخچه، پنل مدیریت تاریخچهٔ خودش */
function nav_state(int $uid): array
{
    $out = ['user' => [], 'ad' => []];
    if ($uid <= 0) {
        return $out;
    }
    $row = DB::one('SELECT data FROM nav_stack WHERE uid=?', [$uid]);
    $raw = $row === null ? [] : (json_decode((string) $row['data'], true) ?: []);
    if (!is_array($raw)) {
        return $out;
    }
    if (isset($raw['user']) || isset($raw['ad'])) {
        $out['user'] = array_values(array_filter((array) ($raw['user'] ?? []), 'is_string'));
        $out['ad'] = array_values(array_filter((array) ($raw['ad'] ?? []), 'is_string'));
        return $out;
    }
    /* ردیف‌های نسخهٔ قبل یک آرایهٔ ساده بودند */
    $out['user'] = array_values(array_filter($raw, 'is_string'));
    return $out;
}

function nav_save(int $uid, array $state): void
{
    if ($uid <= 0) {
        return;
    }
    $clean = [
        'user' => array_slice(array_values(array_filter((array) ($state['user'] ?? []), 'is_string')), -25),
        'ad'   => array_slice(array_values(array_filter((array) ($state['ad'] ?? []), 'is_string')), -25),
    ];
    DB::exec('INSERT INTO nav_stack(uid, data, updated_at) VALUES(?,?,?) '
        . 'ON CONFLICT(uid) DO UPDATE SET data=excluded.data, updated_at=excluded.updated_at',
        [$uid, json_encode($clean, JSON_UNESCAPED_UNICODE), now_ts()]);
}

function nav_get(int $uid, string $scope = 'user'): array
{
    $state = nav_state($uid);
    return $state[$scope] ?? [];
}

function nav_set(int $uid, array $stack, string $scope = 'user'): void
{
    if ($uid <= 0) {
        return;
    }
    $state = nav_state($uid);
    $state[$scope] = $stack;
    nav_save($uid, $state);
}

function nav_push(int $uid, string $data): void
{
    if ($uid <= 0 || $data === '') {
        return;
    }
    foreach (['nav:', 'wiz:', 'wizrole:', 'cancel'] as $skip) {
        if (str_starts_with($data, $skip) || $data === $skip) {
            return;
        }
    }
    $scope = nav_scope($data);
    if (($scope === 'user' && $data === 'home') || ($scope === 'ad' && $data === 'ad:home')) {
        /* صفحهٔ اول همان بخش، تاریخچهٔ خودش را صفر می‌کند و خودش نقطهٔ شروع می‌شود */
        nav_set($uid, [$data], $scope);
        return;
    }
    $stack = nav_get($uid, $scope);
    /* اگر مقصد از قبل در تاریخچه هست، به همان نقطه برمی‌گردیم؛
       وگرنه دکمه‌های «بازگشت» قدیمی باعث رفت‌وبرگشت بین دو صفحه می‌شوند */
    $pos = array_search($data, $stack, true);
    if ($pos !== false) {
        $stack = array_slice($stack, 0, (int) $pos + 1);
        nav_set($uid, $stack, $scope);
        return;
    }
    if ($stack !== [] && end($stack) === $data) {
        return;
    }
    $stack[] = $data;
    nav_set($uid, $stack, $scope);
}

/** یک صفحه عقب در همان بخش؛ خروجی: دادهٔ صفحهٔ قبلی یا رشتهٔ خالی */
function nav_back(int $uid, string $scope = 'user'): string
{
    $stack = nav_get($uid, $scope);
    if ($stack === []) {
        return '';
    }
    array_pop($stack);
    $prev = $stack === [] ? '' : (string) end($stack);
    nav_set($uid, $stack, $scope);
    return $prev;
}

function kb_ensure_back(?array $rows): ?array
{
    if ($rows === null || $rows === []) {
        return $rows;
    }
    $isAdmin = false;
    $isRoot = false;
    $hasBack = false;
    if (!empty($GLOBALS['panel_console_root'])) {
        return $rows;   // صفحهٔ اول پنل مدیریت، بدون دکمهٔ بازگشت
    }
    if (!empty($GLOBALS['panel_kb_locked'])) {
        return $rows;   // مرحلهٔ فرم: فقط «❌ انصراف»، نه بازگشت اضافه
    }
    $menuCount = 0;
    foreach ($rows as $row) {
        foreach ($row as $button) {
            $data = (string) ($button['callback_data'] ?? '');
            $text = (string) ($button['text'] ?? '');
            if (str_starts_with($data, 'menu:')) {
                $menuCount++;
            }
            if (str_starts_with($data, 'ad:')) {
                $isAdmin = true;
            }
            if ($data === 'nav:back' || str_starts_with($data, 'nav:back:')) {
                $hasBack = true;
            }
            if (preg_match('/^[«↩🔙]/u', $text) === 1) {
                $hasBack = true;   // این صفحه خودش دکمهٔ بازگشت دارد
            }
        }
    }
    if ($menuCount >= 5) {
        return $rows;   // منوی اصلی صفحهٔ اول است و دکمهٔ «⚙️ پنل مدیریت» باید همان بماند
    }
    /* بخش از روی صفحهٔ جاری تعیین می‌شود، نه از وجود یک دکمهٔ «ad:» در
       صفحه — همین باعث می‌شد بازگشت از صفحهٔ خرید به پنل مدیریت بپرد. */
    $scope = $GLOBALS['panel_nav_scope'] ?? ($isAdmin ? 'ad' : 'user');
    $backData = $scope === 'ad' ? 'nav:back:ad' : 'nav:back';

    /* هر دکمه‌ای که به «خانه» می‌رفت، حالا فقط یک قدم عقب می‌رود */
    foreach ($rows as $rowIndex => $row) {
        foreach ($row as $buttonIndex => $button) {
            $data = (string) ($button['callback_data'] ?? '');
            if ($scope === 'ad' && $data === 'ad:home') {
                $rows[$rowIndex][$buttonIndex]['callback_data'] = $backData;
                $hasBack = true;
            }
            if ($scope === 'user' && $data === 'home') {
                $rows[$rowIndex][$buttonIndex]['callback_data'] = $backData;
                $hasBack = true;
            }
        }
    }
    if (!$hasBack) {
        $rows[] = [btn('🔙 بازگشت', $backData, null, 'danger')];
    }
    return $rows;
}


/**
 * استانداردسازی همهٔ دکمه‌های بازگشت در سرتاسر ربات.
 * قانون: متن دکمه فقط «🔙 بازگشت» است و کارش رفتن به یک قدم قبل
 * (پشتهٔ ناوبری) — نه پرش به یک بخش نامربوط.
 * دکمه‌های «لغو» و «انصراف» دکمهٔ بازگشت نیستند و دست نمی‌خورند.
 */
function kb_back_normalize(array $button): array
{
    $text = trim((string) ($button['text'] ?? ''));
    if ($text === '') {
        return $button;
    }
    $data = (string) ($button['callback_data'] ?? '');
    $scope = (string) ($GLOBALS['panel_nav_scope'] ?? '');
    if ($scope === '') {
        $scope = str_starts_with($data, 'ad:') ? 'ad' : 'user';
    }
    $backData = $scope === 'ad' ? 'nav:back:ad' : 'nav:back';
    /* انصراف/لغو: متن تمیز می‌شود ولی کارکردش همان لغو مرحله است */
    if (preg_match('/لغو|انصراف/u', $text) === 1
            && preg_match('/^[«↩🔙❌]/u', $text) === 1 && !str_contains($text, 'بازگشت')) {
        $button['text'] = '❌ ' . preg_replace('/^[«↩🔙❌\s]+/u', '', $text);
        return $button;
    }
    /* هر دکمه‌ای که با « شروع می‌شود، دکمهٔ بازگشت است */
    if (preg_match('/^[«↩]/u', $text) === 1) {
        $button['text'] = '🔙 بازگشت';
        $button['callback_data'] = $backData;
        return $button;
    }
    /* دکمه‌های بازگشتِ استاندارد همیشه به پشته وصل می‌شوند (به‌جز KYC که
       مسیر داخلی خودش را دارد) */
    if (preg_match('/^🔙/u', $text) === 1 && !str_starts_with($data, 'kyc:')) {
        $button['text'] = '🔙 بازگشت';
        if (!str_starts_with($data, 'nav:back')) {
            $button['callback_data'] = $backData;
        }
        return $button;
    }
    return $button;
}

function kb_clean(?array $rows): ?array
{
    if ($rows === null) {
        return null;
    }
    $seen = [];
    $out = [];
    foreach ($rows as $row) {
        $cleanRow = [];
        foreach ($row as $button) {
            $key = (string) ($button['callback_data'] ?? '') . '|' . (string) ($button['url'] ?? '')
                . '|' . (string) ($button['copy_text']['text'] ?? '');
            if (isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;
            /* هر دکمه باید رنگ داشته باشد؛ بی‌رنگ یعنی «شیشه‌ای» و کاربر
               دکمه را به‌عنوان دکمه نمی‌بیند. رنگ‌های خود ادمین حفظ می‌شود. */
            if (!isset($button['style']) || (string) $button['style'] === '') {
                $button['style'] = 'primary';
            }
            $button = kb_back_normalize($button);
            $cleanRow[] = $button;
        }
        if ($cleanRow) {
            $out[] = $cleanRow;
        }
    }
    return $out;
}

/* 6) Conversation state (persisted — survives service restarts) */

final class State
{
    public static function get(int $uid): array
    {
        $row = DB::one('SELECT state, data FROM tg_state WHERE uid=?', [$uid]);
        if ($row === null) {
            return ['state' => '', 'data' => []];
        }
        return ['state' => (string) $row['state'],
                'data'  => json_decode((string) $row['data'], true) ?: []];
    }

    public static function set(int $uid, string $state, array $data = []): void
    {
        DB::exec('INSERT INTO tg_state(uid, state, data, updated_at) VALUES(?,?,?,?) '
            . 'ON CONFLICT(uid) DO UPDATE SET state=excluded.state, data=excluded.data, '
            . 'updated_at=excluded.updated_at',
            [$uid, $state, json_encode($data, JSON_UNESCAPED_UNICODE), now_ts()]);
    }

    public static function clear(int $uid): void
    {
        DB::exec('DELETE FROM tg_state WHERE uid=?', [$uid]);
    }
}

/* 7) Domain: users, wallet, orders, catalog */

/**
 * کاربران «شبح»: ردیف‌هایی که فقط از جستجوی مدیر یا شناسهٔ دستی ساخته شده‌اند
 * (بی‌نام، بی‌موجودی و بدون هیچ سفارش/پنل/تراکنش). این‌ها نباید در «کاربران» بمانند.
 */
function purge_ghost_users(): int
{
    $rows = DB::all("SELECT u.tg_id FROM users u "
        . "WHERE COALESCE(TRIM(u.name), '') = '' "
        . "AND COALESCE(TRIM(u.uname), '') = '' "
        . "AND COALESCE(u.balance, 0) = 0 "
        . "AND NOT EXISTS (SELECT 1 FROM orders o WHERE o.tg_id = u.tg_id) "
        . "AND NOT EXISTS (SELECT 1 FROM wallet_tx w WHERE w.tg_id = u.tg_id) "
        . "AND NOT EXISTS (SELECT 1 FROM panels p WHERE p.tg_id = u.tg_id) "
        . "AND NOT EXISTS (SELECT 1 FROM slots s WHERE s.tg_id = u.tg_id)");
    $gone = 0;
    foreach ($rows as $row) {
        DB::exec('DELETE FROM users WHERE tg_id=?', [(int) $row['tg_id']]);
        $gone++;
    }
    return $gone;
}

function user_ensure(int $tgId, string $name, string $uname): array
{
    if (is_bot_self($tgId)) {
        /* حساب خود ربات هیچ‌وقت کاربر نمی‌شود و کیف پول ندارد */
        return ['tg_id' => $tgId, 'name' => $name, 'uname' => $uname, 'balance' => 0,
                'is_blocked' => 0, 'created_at' => now_ts(), 'last_seen' => now_ts()];
    }
    $isNew = DB::one('SELECT tg_id FROM users WHERE tg_id=?', [$tgId]) === null;
    DB::exec('INSERT INTO users(tg_id, name, uname, created_at, last_seen) VALUES(?,?,?,?,?) '
        . 'ON CONFLICT(tg_id) DO UPDATE SET name=excluded.name, uname=excluded.uname, '
        . 'last_seen=excluded.last_seen',
        [$tgId, $name, $uname, now_ts(), now_ts()]);
    if ($isNew) {
        try {
            post_report('👥 <b>کاربر تازه</b>' . "\n"
                . '👤 ' . e(mb_substr($name !== '' ? $name : (string) $tgId, 0, 24))
                . ' <code>' . $tgId . '</code>'
                . ($uname !== '' ? "\n" . '🔗 @' . e($uname) : ''), 'users');
        } catch (Throwable $ex) {
            log_line('warning', 'report user failed: ' . $ex->getMessage());
        }
    }
    return user_get($tgId) ?? ['tg_id' => $tgId, 'name' => $name, 'balance' => 0];
}

function user_get(int $tgId): ?array
{
    return DB::one('SELECT * FROM users WHERE tg_id=?', [$tgId]);
}

function balance_of(int $tgId): int
{
    if (is_bot_self($tgId)) {
        return 0; // حساب خود ربات کیف پول ندارد
    }
    return (int) DB::val('SELECT balance FROM users WHERE tg_id=?', [$tgId], 0);
}

function add_balance(int $tgId, int $amount, string $kind, string $ref = '', string $note = ''): int
{
    /* تغییر موجودی همیشه اتمی است: دو شارژ/کسر هم‌زمان پشت سر هم اجرا می‌شوند،
       نه روی هم — و شمارش مصرف همیشه از خودِ دیتابیس خوانده می‌شود. */
    return db_tx(static function () use ($tgId, $amount, $kind, $ref, $note): int {
        $applied = DB::update('UPDATE users SET balance = balance + ? WHERE tg_id=?',
            [$amount, $tgId]);
        if ($applied === 0) {
            log_line('warning', 'add_balance: user not found', ['tg' => $tgId, 'amount' => $amount]);
            return 0;
        }
        $newBalance = (int) DB::val('SELECT balance FROM users WHERE tg_id=?', [$tgId], 0);
        DB::exec('INSERT INTO wallet_tx(tg_id, amount, kind, ref, note, balance, created_at) '
            . 'VALUES(?,?,?,?,?,?,?)',
            [$tgId, $amount, $kind, $ref, mb_substr($note, 0, 200), $newBalance, now_ts()]);
        return $newBalance;
    });
}

const CATEGORY_LABELS = [
    'v2ray'     => '🌐 V2ray / Xray',
    'wireguard' => '🛡 WireGuard',
    'openvpn'   => '🔐 OpenVPN',
    'l2tp'      => '📡 L2TP / IKEv2',
    'special'   => '💎 ویژه',
];

function cat_label(?array $cat): string
{
    if ($cat === null) {
        return 'بدون دسته';
    }
    return trim(((string) ($cat['emoji'] ?? '')) . ' ' . ((string) ($cat['name'] ?? '')));
}

function cat_list(bool $activeOnly = false): array
{
    return DB::all('SELECT * FROM categories' . ($activeOnly ? ' WHERE active=1' : '')
        . ' ORDER BY sort, id');
}

function cat_get(int $id): ?array
{
    return DB::one('SELECT * FROM categories WHERE id=?', [$id]);
}

function cat_create(string $name, string $emoji = '🗂'): int
{
    return DB::exec('INSERT INTO categories(name, emoji, created_at) VALUES(?,?,?)',
        [mb_substr(trim($name), 0, 60), $emoji ?: '🗂', now_ts()]);
}

function products_list(bool $activeOnly = false): array
{
    return DB::all('SELECT * FROM products' . ($activeOnly ? ' WHERE active=1' : '')
        . ' ORDER BY sort, id');
}

function product_get(int $id): ?array
{
    return DB::one('SELECT * FROM products WHERE id=?', [$id]);
}

function product_update(int $id, string $column, mixed $value): void
{
    $allowed = ['name', 'emoji', 'hourly_price', 'per_gb_price', 'min_balance', 'max_users',
                'extra_block_size', 'extra_block_price',
                'device_limit', 'days', 'data_cap_gb', 'slots_needed', 'renew_price',
                'panel_prefix', 'role_id', 'panel_id', 'active', 'trial'];
    if (!in_array($column, $allowed, true)) {
        throw new InvalidArgumentException("column not editable: $column");
    }
    DB::exec("UPDATE products SET $column=? WHERE id=?", [$value, $id]);
}

function ref_code(): string
{
    return strtoupper(bin2hex(random_bytes(4)));
}

function create_order(int $tgId, string $kind, int $price, ?int $productId = null,
                      array $payload = [], int $discount = 0, string $discountCode = ''): array
{
    $payable = max(0, $price - $discount);
    $id = DB::exec('INSERT INTO orders(tg_id, kind, product_id, price, discount, payable, status, '
        . 'ref, payload, created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',
        [$tgId, $kind, $productId, $price, $discount, $payable, 'pending', ref_code(),
         json_encode($payload, JSON_UNESCAPED_UNICODE), now_ts()]);
    if ($discountCode !== '' && $discount > 0) {
        DB::exec('UPDATE discounts SET uses = uses + 1 WHERE code=?', [strtoupper($discountCode)]);
    }
    return order_get($id) ?? [];
}

function order_get(int $id): ?array
{
    return DB::one('SELECT * FROM orders WHERE id=?', [$id]);
}

function order_mark(int $id, string $status): void
{
    DB::exec('UPDATE orders SET status=?, paid_at=? WHERE id=?',
        [$status, $status === 'delivered' ? now_ts() : null, $id]);
}

function discount_check(string $code, int $price): array
{
    $code = strtoupper(trim($code));
    if ($code === '') {
        return [0, ''];
    }
    if (!set_bool('discount_enabled', true)) {
        return [0, 'کد تخفیف غیرفعال است.'];
    }
    $row = DB::one('SELECT * FROM discounts WHERE code=? AND active=1', [$code]);
    if ($row === null) {
        return [0, 'کد تخفیف نامعتبر است.'];
    }
    if ($row['expires_at'] && (int) $row['expires_at'] < now_ts()) {
        return [0, 'کد تخفیف منقضی شده است.'];
    }
    if ((int) $row['max_uses'] && (int) $row['uses'] >= (int) $row['max_uses']) {
        return [0, 'ظرفیت این کد تکمیل شده است.'];
    }
    $amount = (int) ($price * (int) $row['percent'] / 100) + (int) $row['amount'];
    $amount = min($amount, $price);
    return [$amount, 'کد تخفیف اعمال شد: ' . money($amount)];
}

function slots_total(int $tgId): array
{
    $free = set_int('slots_free', 3);
    $bought = (int) DB::val('SELECT COALESCE(SUM(count),0) FROM slots WHERE tg_id=?', [$tgId], 0);
    $used = (int) DB::val("SELECT COUNT(*) FROM panels WHERE tg_id=? "
        . "AND status IN ('active','suspended') AND COALESCE(is_trial,0)=0", [$tgId], 0);
    return [$free, $bought, $used];
}

function slots_available(int $tgId): int
{
    [$free, $bought, $used] = slots_total($tgId);
    return max(0, $free + $bought - $used);
}

/* 8) PasarGuard API client */

final class PanelError extends RuntimeException
{
    public function __construct(string $message, public int $status = 0)
    {
        parent::__construct($message);
    }
}

/**
 * پیام خطای پنل را خوانا می‌کند.
 * پاسخ اعتبارسنجی پاسارگارد یک آرایه است و قبلاً به‌صورت «Array» چاپ می‌شد:
 *   {"detail":[{"loc":["body","password"],"msg":"Password must contain at least 2 digits"}]}
 */
function panel_error_detail(mixed $decoded, string $raw = ''): string
{
    $parts = [];
    $detail = is_array($decoded) ? ($decoded['detail'] ?? ($decoded['message'] ?? null)) : null;
    if (is_string($detail) && trim($detail) !== '') {
        $parts[] = trim($detail);
    } elseif (is_array($detail)) {
        foreach ($detail as $item) {
            if (is_string($item)) {
                $parts[] = $item;
                continue;
            }
            if (!is_array($item)) {
                continue;
            }
            $loc = $item['loc'] ?? [];
            $loc = is_array($loc) ? implode('.', array_map('strval', $loc)) : (string) $loc;
            $msg = (string) ($item['msg'] ?? ($item['message'] ?? ''));
            if ($msg === '' && isset($item['ctx']['error'])) {
                $msg = (string) $item['ctx']['error'];
            }
            $parts[] = trim(($loc !== '' ? $loc . ': ' : '') . $msg);
        }
    }
    if ($parts === []) {
        $trimmed = trim($raw);
        if ($trimmed !== '' && str_starts_with($trimmed, '{')) {
            $trimmed = '';
        }
        $parts[] = $trimmed !== '' ? mb_substr($trimmed, 0, 200) : 'پاسخ نامعتبر';
    }
    $text = implode(' | ', array_filter($parts));
    return mb_substr($text, 0, 300);
}

function normalize_panel_url(string $url): string
{
    $value = rtrim(trim($url), '/');
    if ($value === '') {
        return '';
    }
    foreach (['/dashboard', '/login', '/admin'] as $suffix) {
        if (str_ends_with($value, $suffix)) {
            $value = rtrim(substr($value, 0, -strlen($suffix)), '/');
        }
    }
    if (!str_starts_with($value, 'http://') && !str_starts_with($value, 'https://')) {
        $value = (str_ends_with($value, ':80') ? 'http://' : 'https://') . $value;
    }
    return rtrim($value, '/');
}

final class PgPanel
{
    private ?string $token = null;
    private string $apiKey = '';

    public function __construct(private array $row)
    {
        $this->apiKey = trim((string) ($row['api_key'] ?? ''));
    }

    /** روش اتصال همیشه کلید API است */
    public function auth_mode(): string
    {
        return 'api';
    }

    public function has_key(): bool
    {
        return $this->apiKey !== '';
    }

    public static function from_id(int $id): self
    {
        $row = DB::one('SELECT * FROM pg_panels WHERE id=?', [$id]);
        if ($row === null) {
            throw new PanelError('panel not found');
        }
        return new self($row);
    }

    public static function default_panel(): ?self
    {
        $row = DB::one('SELECT * FROM pg_panels WHERE active=1 ORDER BY is_default DESC, id LIMIT 1');
        return $row === null ? null : new self($row);
    }

    public function name(): string
    {
        return (string) $this->row['name'];
    }

    private function request(string $method, string $path, ?array $json = null, array $query = []): array
    {
        $base = normalize_panel_url((string) $this->row['url']);
        $url = $base . $path . ($query ? '?' . http_build_query($query) : '');
        $this->login();
        $headers = ['Accept: application/json', 'X-Api-Key: ' . $this->apiKey];
        $body = null;
        if ($json !== null) {
            $headers[] = 'Content-Type: application/json';
            $body = json_encode($json, JSON_UNESCAPED_UNICODE);
        }
        [$payload, $error, $status] = http_request($method, $url, $headers, $body, true,
            max(5, min(120, set_int('panel_test_timeout', 20))));
        if ($payload === null) {
            throw new PanelError('connection failed: ' . $error);
        }
        $decoded = json_decode((string) $payload, true);
        if ($status >= 400) {
            $detail = panel_error_detail($decoded, (string) $payload);
            throw new PanelError('HTTP ' . $status . ($detail !== '' ? ' — ' . $detail : ''), $status);
        }
        return is_array($decoded) ? $decoded : [];
    }

    /** فقط کلید API پذیرفته می‌شود */
    public function login(): void
    {
        if ($this->apiKey === '') {
            throw new PanelError('کلید API این پنل تنظیم نشده است؛ از «🔌 پنل‌ها → ➕ افزودن پنل» '
                . 'کلید را ثبت کنید');
        }
    }

    public function me(): array
    {
        $this->login();
        return $this->request('GET', '/api/admin');
    }

    public function roles(): array
    {
        $this->login();
        $data = $this->request('GET', '/api/admin-roles/simple');
        return $data['roles'] ?? $data;
    }

    public function groups(): array
    {
        $this->login();
        $data = $this->request('GET', '/api/groups/simple');
        return $data['groups'] ?? $data;
    }

    public function create_admin(string $username, string $password, int $roleId, array $extra = []): array
    {
        $this->login();
        /* فیلدهای معتبر خود پنل (AdminCreate/AdminModify در پاسارگارد v5):
           username, password, role_id, status, data_limit, note, permission_overrides.
           فیلدهای قدیمی (is_active/users_limit/expire) در v5 وجود ندارند و
           باعث 422 می‌شدند. */
        $status = (string) ($extra['status'] ?? '') !== '' ? (string) $extra['status'] : 'active';
        $body = ['username' => $username, 'password' => $password, 'role_id' => $roleId,
                 'status' => $status];
        if (isset($extra['data_limit']) && (int) $extra['data_limit'] > 0) {
            $body['data_limit'] = (int) $extra['data_limit'];
        }
        if (!empty($extra['note'])) {
            $body['note'] = (string) $extra['note'];
        }
        if (isset($extra['users_limit']) && (int) $extra['users_limit'] > 0) {
            $body['permission_overrides'] = ['max_users' => (int) $extra['users_limit']];
        }
        try {
            return $this->request('POST', '/api/admin', $body);
        } catch (PanelError $ex) {
            if ($ex->status === 422) {
                /* آخرین تلاش: فقط سه فیلد اجباری، بدون هیچ چیزی که پنل نشناسد */
                return $this->request('POST', '/api/admin', [
                    'username' => $username,
                    'password' => $password,
                    'role_id'  => $roleId,
                ]);
            }
            throw $ex;
        }
    }

    public function admin_by_username(string $username): ?array
    {
        $this->login();
        $data = $this->request('GET', '/api/admins', null, ['username' => $username, 'limit' => 1]);
        $admins = $data['admins'] ?? [];
        return $admins[0] ?? null;
    }

    /**
     * جزئیات کامل یک ادمین (مصرف، سقف، تعداد کاربر، وضعیت).
     * PasarGuard این اطلاعات را در فهرست ادمین‌ها برمی‌گرداند:
     * GET /api/admins?username=<u>  → { admins: [AdminDetails], ... }
     */
    public function admin_info(string $username): array
    {
        $this->login();
        $username = trim($username);
        if ($username === '') {
            return $this->request('GET', '/api/admin');
        }
        $data = $this->request('GET', '/api/admins', null, [
            'username' => $username,
            'limit'    => 1,
        ]);
        $admins = $data['admins'] ?? [];
        if (is_array($admins)) {
            foreach ($admins as $row) {
                if (is_array($row)
                    && mb_strtolower((string) ($row['username'] ?? '')) === mb_strtolower($username)) {
                    return $row;
                }
            }
            if (isset($admins[0]) && is_array($admins[0])) {
                return $admins[0];
            }
        }
        return $data;
    }

    public function delete_admin(int $id): void
    {
        $this->login();
        $this->request('DELETE', '/api/admin/by-id/' . $id);
    }

    /** حذف ادمین با نام کاربری (فقط برای پنل‌های تست استفاده می‌شود) */
    public function delete_admin_by_username(string $username): void
    {
        $this->login();
        $this->request('DELETE', '/api/admin/by-username/' . rawurlencode($username));
    }

    /**
     * حذف کامل ادمین پنل همراه با همهٔ کاربرانی که زیرمجموعهٔ او ساخته شده‌اند.
     * اول کاربران (کانفیگ‌ها) پاک می‌شوند تا هیچ کانفیگ یتیمی روی پنل نماند،
     * بعد خود ادمین. خروجی: ['users' => تعداد حذف‌شده, 'admin' => true]
     */
    public function delete_admin_with_users(string $username): array
    {
        $this->login();
        $deleted = 0;
        for ($round = 0; $round < 20; $round++) {
            $users = $this->users_of($username, 1000, 0);
            if ($users === []) {
                break;
            }
            $ids = [];
            $names = [];
            foreach ($users as $user) {
                if (isset($user['id'])) {
                    $ids[] = (int) $user['id'];
                }
                if (!empty($user['username'])) {
                    $names[] = (string) $user['username'];
                }
            }
            if ($ids === [] && $names === []) {
                break;
            }
            $removed = 0;
            if ($ids !== []) {
                try {
                    $res = $this->request('POST', '/api/users/bulk/delete',
                        ['ids' => array_values($ids)]);
                    $removed = (int) ($res['count'] ?? $res['deleted'] ?? count($ids));
                } catch (Throwable $ex) {
                    $removed = 0; // نسخه‌های قدیمی پنل این مسیر را ندارند
                }
            }
            if ($removed <= 0) {
                foreach ($names as $name) {
                    try {
                        $this->request('DELETE', '/api/user/by-username/' . rawurlencode($name));
                        $removed++;
                    } catch (Throwable $ex) {
                        if (!str_contains($ex->getMessage(), '404')) {
                            // بقیهٔ کاربران را رها نکن
                        }
                    }
                }
            }
            $deleted += max(0, $removed);
            if ($removed <= 0) {
                break;
            }
        }
        $this->request('DELETE', '/api/admin/by-username/' . rawurlencode($username));
        return ['users' => $deleted, 'admin' => true];
    }

    public function update_admin(string $username, array $fields): array
    {
        $this->login();
        return $this->request('PUT', '/api/admin/by-username/' . rawurlencode($username), $fields);
    }

    /** تغییر رمز ورود پنل کاربر */
    public function set_password(string $username, string $password): array
    {
        return $this->update_admin($username, ['password' => $password]);
    }

    public function set_status(mixed $admin, string $status): array
    {
        $this->login();
        $state = $status === 'active' ? 'active' : 'disabled';
        return $this->request('PUT', '/api/admin/by-username/' . rawurlencode((string) $admin),
            ['status' => $state]);
    }

    /** مصرف/سقف ادمین از خود پنل */
    public function usage(int $adminId, string $username = ''): array
    {
        return $this->admin_info($username);
    }

    /** کاربران یک ادمین (برای شمارش دستگاه‌ها و بررسی تخلف) */
    public function users_of(string $adminUsername, int $limit = 200, int $offset = 0): array
    {
        $this->login();
        $data = $this->request('GET', '/api/users', null, [
            'admin'  => $adminUsername,
            'limit'  => max(1, min(1000, $limit)),
            'offset' => max(0, $offset),
        ]);
        return is_array($data['users'] ?? null) ? $data['users'] : [];
    }

    /**
     * آمار سیستم پنل: نسخه، RAM سرور، CPU و تعداد کاربران.
     * PasarGuard/Marzban: GET /api/system — اگر نبود، خروجی خالی برمی‌گردد.
     */
    public function system_info(): array
    {
        $this->login();
        try {
            $data = $this->request('GET', '/api/system');
        } catch (Throwable $ex) {
            return [];
        }
        return is_array($data) ? $data : [];
    }

    /** خواندن دوبارهٔ یک کانفیگ از پنل: GET /api/user/by-username/{username} */
    public function user_info(string $username): array
    {
        $this->login();
        return $this->request('GET', '/api/user/by-username/' . rawurlencode($username));
    }

    /** وضعیت یک کانفیگ (کاربر) روی پنل را عوض می‌کند: active | disabled */
    public function set_user_status(string $username, string $status): array
    {
        $this->login();
        return $this->request('PUT', '/api/user/' . rawurlencode($username),
            ['status' => $status === 'active' ? 'active' : 'disabled']);
    }

    /** خروج همهٔ دستگاه‌های ثبت‌شدهٔ یک کاربر پنل */
    public function reset_hwids(int $userId): array
    {
        $this->login();
        return $this->request('POST', '/api/user/' . $userId . '/hwids/reset');
    }
}

function panel_test(array $row): array
{
    $started = microtime(true);
    try {
        $client = new PgPanel($row);
        $me = $client->me();
        $who = (string) ($me['username'] ?? ($row['username'] ?? ''));
        $lines = ['اتصال برقرار شد — ادمین «' . $who . '»'];
        $lines[] = 'روش اتصال: 🔑 API Key';
        try {
            $roles = $client->roles();
            $lines[] = 'نقش‌ها: ' . count($roles) . ' عدد';
            set_put('roles_cache_' . (int) ($row['id'] ?? 0),
                json_encode(roles_normalize($roles), JSON_UNESCAPED_UNICODE));
        } catch (Throwable $ex) {
            $lines[] = 'نقش‌ها خوانده نشد: ' . mb_substr($ex->getMessage(), 0, 80);
        }
        try {
            $groups = $client->groups();
            $lines[] = 'گروه‌ها: ' . count($groups) . ' عدد';
        } catch (Throwable $ex) {
            $lines[] = 'گروه‌ها خوانده نشد';
        }
        $ms = (int) round((microtime(true) - $started) * 1000);
        $lines[] = 'زمان پاسخ: ' . fa_digits($ms) . ' میلی‌ثانیه';
        if (!empty($row['id'])) {
            DB::exec('UPDATE pg_panels SET last_ok_at=?, last_error=NULL WHERE id=?',
                [now_ts(), (int) $row['id']]);
        }
        return [true, implode("\n", $lines)];
    } catch (Throwable $ex) {
        $message = $ex->getMessage();
        if (str_contains($message, 'SSL') || str_contains($message, 'wrong version')) {
            $message .= ' — پنل احتمالاً روی http است، آدرس را با http:// بفرستید';
        }
        if (!empty($row['id'])) {
            DB::exec('UPDATE pg_panels SET last_error=?, last_ok_at=0 WHERE id=?',
                [mb_substr($message, 0, 300), (int) $row['id']]);
        }
        return [false, $message];
    }
}

/*
   8) SELF-UPDATE — نسخهٔ تازه از مخزن گیت‌هاب، بدون دست‌زدن به داده.

   مسیر کار:
     ۱) نسخهٔ منتشرشده از API گیت‌هاب خوانده می‌شود (ریلیز، وگرنه فایل VERSION)،
     ۲) اگر از نسخهٔ نصب‌شده تازه‌تر بود، آرشیو همان برنچ دانلود می‌شود،
     ۳) فقط فایل‌های کد جایگزین می‌شوند؛ .env و دیتابیس و لاگ و بکاپ دست‌نخورده
        می‌مانند،
     ۴) مایگریشن اجرا و سرویس نرم ری‌استارت می‌شود.
*/

const UPDATE_DEFAULT_REPO = 'XuSibiL/SIBILPANEL';
/* کش فقط برای تیک خودکار/نمایش است؛ هر بررسیِ کاربر همیشه تازه خوانده می‌شود */
const UPDATE_CACHE_TTL = 1800;   // فقط برای نشان نسخه در پنل مدیریت
const UPDATE_RAW_CACHE_TTL = 300;

/** مخزن رسمی: مقدار .env وگرنه مخزن پیش‌فرض */
function update_repo(): string
{
    $repo = trim(cfg('PANEL_UPDATE_REPO'));
    if ($repo === '') {
        $repo = UPDATE_DEFAULT_REPO;
    }
    $repo = preg_replace('#^https?://(www\.)?github\.com/#i', '', $repo) ?? $repo;
    $repo = preg_replace('#\.git$#i', '', $repo) ?? $repo;
    return trim($repo, "/ \t");
}

function update_branch(): string
{
    $branch = trim(cfg('PANEL_UPDATE_BRANCH'));
    return $branch !== '' ? $branch : 'main';
}

/** آدرس دانلود آرشیو کد همین برنچ */
function update_archive_url(): string
{
    $mirror = trim(cfg('PANEL_UPDATE_ARCHIVE_URL'));
    if ($mirror !== '') {
        return $mirror;
    }
    return 'https://codeload.github.com/' . update_repo() . '/tar.gz/refs/heads/' . rawurlencode(update_branch());
}

/** مقایسهٔ نسخه؛ true یعنی نسخهٔ دوردست تازه‌تر است */
function update_is_newer(string $remote, string $local): bool
{
    $remote = trim(ltrim($remote, 'vV'));
    $local = trim(ltrim($local, 'vV'));
    if ($remote === '' || !preg_match('/^\d+(\.\d+)*$/', $remote)) {
        return false;
    }
    return version_compare($remote, $local, '>');
}

/**
 * یک GET ساده با هدر گیت‌هاب؛ خروجی [بدنه، کد وضعیت].
 * هدر no-cache اجباری است تا CDN گیت‌هاب نسخهٔ قدیمی را برنگرداند.
 */
function update_http_get(string $url, int $timeout = 12): array
{
    [$body, $error, $status] = http_request('GET', $url, [
        'User-Agent: panel-updater',
        'Accept: application/vnd.github+json',
        'Cache-Control: no-cache',
        'Pragma: no-cache',
    ], null, false, $timeout);
    if ($body === null || $body === '') {
        return ['', (int) $status];
    }
    return [(string) $body, (int) $status];
}

/** آدرس با پارامتر ضدفشرده‌سازی تا همان لحظه نسخهٔ تازه بیاید */
function update_bust_url(string $url): string
{
    return $url . (str_contains($url, '?') ? '&' : '?') . 't=' . time() . mt_rand(100, 999);
}

/**
 * نسخهٔ فایل VERSION از Contents API گیت‌هاب.
 * `raw.githubusercontent.com` تا ۵ دقیقه پس از پوش، نسخهٔ کهنه را از کش
 * (x-cache: HIT) برمی‌گرداند؛ این مسیر همان لحظه به‌روز است.
 */
function update_version_contents_api(string $repo, string $branch): string
{
    [$body, $status] = update_http_get(update_bust_url(
        'https://api.github.com/repos/' . $repo . '/contents/VERSION?ref='
        . rawurlencode($branch)), 10);
    if ($status < 200 || $status >= 300 || $body === '') {
        return '';
    }
    $json = json_decode($body, true);
    if (!is_array($json) || ($json['encoding'] ?? '') !== 'base64'
        || !isset($json['content'])) {
        return '';
    }
    /* JSON رشتهٔ base64 را با «\\n» می‌فرستد؛ قبل از decode پاک می‌شود */
    $b64 = (string) $json['content'];
    $b64 = str_replace(chr(92) . 'n', '', $b64);
    $b64 = str_replace(["\n", "\r", ' '], '', $b64);
    $decoded = base64_decode($b64, true);
    if ($decoded === false) {
        return '';
    }
    $version = trim($decoded);
    return preg_match('/^\d+(\.\d+)*$/', $version) ? $version : '';
}

/** بالاترین نسخهٔ معتبر از میان چند مقدار */
function update_max_version(string ...$versions): string
{
    $best = '';
    foreach ($versions as $raw) {
        $candidate = trim(ltrim(trim($raw), 'vV'));
        if (!preg_match('/^\d+(\.\d+)*$/', $candidate)) {
            continue;
        }
        if ($best === '' || version_compare($candidate, $best, '>')) {
            $best = $candidate;
        }
    }
    return $best;
}

/**
 * آخرین نسخهٔ منتشرشده در گیت‌هاب.
 *  · `$force = true` (پیش‌فرض): همیشه تازه خوانده می‌شود — دکمهٔ «بررسی» و CLI
 *  · `$force = false`: تیک خودکار/نمایش، با کش کوتاه
 * مقدار نهایی = بالاترین نسخهٔ بین «ریلیز»، «تگ‌ها» و «فایل VERSION برنچ»، تا
 * هیچ منبع قدیمی نسخهٔ تازه‌تر را پنهان نکند. کش فقط وقتی استفاده می‌شود که
 * هیچ منبعی جواب ندهد (آفلاین).
 */
function update_remote_version(bool $force = true): array
{
    $repo = update_repo();
    $cached = json_decode((string) set_get('update_remote', ''), true);
    if (!$force && is_array($cached)
        && (int) ($cached['at'] ?? 0) > time() - UPDATE_CACHE_TTL
        && (string) ($cached['version'] ?? '') !== '') {
        return ['version' => (string) $cached['version'],
                'source' => (string) ($cached['source'] ?? 'cache'), 'cached' => true];
    }

    $release = '';
    $versionFile = '';
    $contents = '';
    $tags = '';

    /* ۱) فایل VERSION خام — سریع و بدون مصرف سهمیهٔ API گیت‌هاب */
    [$raw, $code] = update_http_get(update_bust_url(
        'https://raw.githubusercontent.com/' . $repo . '/' . update_branch() . '/VERSION'), 10);
    $raw = trim($raw);
    if ($code >= 200 && $code < 300 && preg_match('/^\d+(\.\d+)*$/', $raw)) {
        $versionFile = $raw;
    }

    /* ۲) اگر همین حالا نسخهٔ تازه‌تری دیده شد، کار تمام است (بدون درخواست API).
       وگرنه ممکن است فایل خام از کش CDN عقب باشد؛ پس API را می‌پرسیم:
       اول ریلیز (بعد از هر انتشار همان لحظه به‌روز)، بعد Contents API. */
    if ($versionFile === '' || !update_is_newer($versionFile, PANEL_VERSION)) {
        [$body, $status] = update_http_get(update_bust_url(
            'https://api.github.com/repos/' . $repo . '/releases/latest'));
        if ($status >= 200 && $status < 300 && $body !== '') {
            $json = json_decode($body, true);
            $tag = is_array($json) ? (string) ($json['tag_name'] ?? '') : '';
            if ($tag !== '') {
                $release = ltrim($tag, 'vV');
            }
        }
        if ($release === '' || !update_is_newer($release, PANEL_VERSION)) {
            $contents = update_version_contents_api($repo, update_branch());
        }
        if ($release === '' && $contents === '' && $versionFile === '') {
            [$tagBody, $tagStatus] = update_http_get(update_bust_url(
                'https://api.github.com/repos/' . $repo . '/tags?per_page=50'), 10);
            if ($tagStatus >= 200 && $tagStatus < 300 && $tagBody !== '') {
                $list = json_decode($tagBody, true);
                if (is_array($list)) {
                    foreach ($list as $row) {
                        $tags = update_max_version($tags, (string) ($row['name'] ?? ''));
                    }
                }
            }
        }
    }

    $version = update_max_version($versionFile, $release, $contents, $tags);

    if ($version !== '') {
        $source = $version === $versionFile ? 'version-file'
            : ($version === $release ? 'release'
                : ($version === $contents ? 'contents-api' : 'tags'));
        set_put('update_remote', json_encode(
            ['version' => $version, 'source' => $source, 'at' => time()]));
        return ['version' => $version, 'source' => $source, 'cached' => false];
    }

    /* هیچ منبعی جواب نداد: آخرین مقدار شناخته‌شده (حالت آفلاین) */
    if (is_array($cached) && (string) ($cached['version'] ?? '') !== '') {
        return ['version' => (string) $cached['version'],
                'source' => 'offline-cache', 'cached' => true];
    }
    return ['version' => '', 'source' => 'unavailable', 'cached' => false];
}

/** وضعیت کامل: نسخهٔ محلی، نسخهٔ دوردست، و این‌که آپدیت هست یا نه */
function update_status(bool $force = true): array
{
    $remote = update_remote_version($force);
    return [
        'local'     => PANEL_VERSION,
        'remote'    => $remote['version'],
        'source'    => $remote['source'],
        'available' => update_is_newer($remote['version'], PANEL_VERSION),
        'repo'      => update_repo(),
        'branch'    => update_branch(),
    ];
}

/** آرشیو را دانلود و در پوشهٔ موقت باز می‌کند؛ خروجی [مسیر ریشه یا null، پیام خطا] */
function update_download_archive(): array
{
    $tmp = sys_get_temp_dir() . '/panel-update-' . bin2hex(random_bytes(4));
    if (!@mkdir($tmp, 0700, true)) {
        return [null, 'temp directory is not writable'];
    }
    $archive = $tmp . '/code.tar.gz';
    $url = update_archive_url();

    [$body, $status] = update_http_get($url, 60);
    if ($status < 200 || $status >= 300 || $body === '') {
        return [null, 'download failed (HTTP ' . (int) $status . ')'];
    }
    if (@file_put_contents($archive, $body) === false) {
        return [null, 'could not write the archive'];
    }

    $extract = $tmp . '/x';
    @mkdir($extract, 0700, true);
    $tar = trim((string) shell_exec('command -v tar 2>/dev/null'));
    if ($tar === '') {
        return [null, 'tar is not available on this server'];
    }
    @shell_exec(escapeshellcmd($tar) . ' -xzf ' . escapeshellarg($archive) . ' -C ' . escapeshellarg($extract) . ' 2>&1');
    $roots = glob($extract . '/*', GLOB_ONLYDIR) ?: [];
    foreach ($roots as $root) {
        if (is_file($root . '/sibil.php')) {
            return [$root, ''];
        }
    }
    return [null, 'the archive does not contain the bot files'];
}

/** لیست چیزهایی که آپدیت هرگز به آن‌ها دست نمی‌زند */
function update_protected(): array
{
    return ['.env', '.env.local', '.installer-url', 'sibil.sqlite3', 'panel.sqlite3',
        'sibil.pid', 'logs', 'backups', 'uploads', 'tests', 'release'];
}

/** کپی امن: فقط فایل‌های کد، بدون حذف داده و تنظیمات */
function update_copy_tree(string $from, string $to, string $rel = ''): array
{
    $copied = 0;
    $protected = update_protected();
    $items = @scandir($from);
    if ($items === false) {
        return [0, ['cannot read ' . $from]];
    }
    foreach ($items as $item) {
        if ($item === '.' || $item === '..' || $item === '.git') {
            continue;
        }
        if ($rel === '' && in_array($item, $protected, true)) {
            continue;
        }
        if (str_starts_with($item, '.env') || str_ends_with($item, '.sqlite3')
            || str_ends_with($item, '.sqlite3-wal') || str_ends_with($item, '.sqlite3-shm')) {
            continue;
        }
        $src = $from . '/' . $item;
        $dst = $to . '/' . $item;
        if (is_dir($src)) {
            if (!is_dir($dst) && !@mkdir($dst, 0755, true)) {
                return [$copied, ['cannot create ' . $dst]];
            }
            [$n, $err] = update_copy_tree($src, $dst, $rel === '' ? $item : $rel . '/' . $item);
            $copied += $n;
            if ($err) {
                return [$copied, $err];
            }
            continue;
        }
        if (@copy($src, $dst)) {
            @chmod($dst, 0644);
            $copied++;
        }
    }
    return [$copied, []];
}

/** ری‌استارت نرم: پرچم خروج تمیز، وگرنه ری‌استارت پشت‌صحنه */
function update_restart(?string $target = null): string
{
    $target = $target ?? panel_root();
    /* برای نصب‌های دستی یا تست، ری‌استارت خودکار با PANEL_UPDATE_RESTART=0 خاموش می‌شود */
    if (cfg('PANEL_UPDATE_RESTART') === '0') {
        return 'skipped';
    }
    $flag = $target . '/.restart-request';
    @touch($flag);
    $php = PHP_BINARY;
    $script = $target . '/sibil.php';
    $log = $target . '/sibil.log';
    $pid = (int) @file_get_contents($target . '/sibil.pid');
    $inner = 'sleep 4';
    if ($pid > 0) {
        $inner .= '; kill -TERM ' . $pid . ' 2>/dev/null';
    }
    $inner .= '; sleep 1; cd ' . escapeshellarg($target)
        . ' && nohup ' . escapeshellarg($php) . ' ' . escapeshellarg($script)
        . ' --poll >> ' . escapeshellarg($log) . ' 2>&1 &';
    @shell_exec('nohup bash -c ' . escapeshellarg($inner) . ' >/dev/null 2>&1 &');
    return 'restarting';
}

/** آپدیت کامل؛ خروجی [موفق؟، پیام] */
function update_apply(?string $target = null): array
{
    $target = $target !== null ? rtrim($target, '/') : panel_root();
    $status = update_status(true);
    /* آینه/فورس: وقتی آرشیو دستی تنظیم شده، نسخه از خودِ آرشیو خوانده می‌شود */
    $forced = trim(cfg('PANEL_UPDATE_ARCHIVE_URL')) !== '' || cfg('PANEL_UPDATE_FORCE') === '1';
    /* اگر فایل VERSION روی دیسک با نسخهٔ کد یکی نیست (سرور نیمه‌آپدیت‌شده)،
       آپدیت باید اجرا شود حتی وقتی گیت‌هاب نسخهٔ تازه‌تری نشان نمی‌دهد */
    $onDisk = trim((string) @file_get_contents($target . '/VERSION'));
    $mismatch = $onDisk !== '' && $onDisk !== PANEL_VERSION;
    if (!$status['available'] && !$forced && !$mismatch) {
        return [false, 'already-latest'];
    }
    $version = (string) $status['remote'];

    [$root, $error] = update_download_archive();
    if ($root === null) {
        return [false, $error];
    }

    /* فایل اصلی باید سالم باشد، وگرنه نسخهٔ فعلی دست‌نخورده می‌ماند */
    $lint = trim((string) shell_exec(escapeshellarg(PHP_BINARY) . ' -l '
        . escapeshellarg($root . '/sibil.php') . ' 2>&1'));
    if (!str_contains($lint, 'No syntax errors')) {
        return [false, 'the downloaded code failed the syntax check'];
    }

    [$copied, $errors] = update_copy_tree($root, $target);
    if ($errors) {
        return [false, (string) $errors[0]];
    }
    if ($copied < 3) {
        return [false, 'nothing was copied'];
    }

    /* نسخهٔ واقعیِ نصب‌شده بعد از کپی خوانده می‌شود (برای حالت آینه) */
    $versionFile = trim((string) @file_get_contents($target . '/VERSION'));
    if ($versionFile !== '') {
        $version = $versionFile;
    }

    /* مایگریشن جدا اجرا می‌شود تا جدول‌ها با کد تازه هم‌قدم شوند */
    @shell_exec('cd ' . escapeshellarg($target) . ' && '
        . escapeshellarg(PHP_BINARY) . ' ' . escapeshellarg($target . '/sibil.php')
        . ' --migrate >/dev/null 2>&1');

    set_put('update_remote', json_encode(['version' => $version, 'source' => 'applied', 'at' => time()]));
    set_put('update_last_at', (string) time());
    @unlink($root . '/../code.tar.gz');

    $mode = update_restart($target);
    return [true, json_encode(['version' => $version, 'copied' => $copied, 'restart' => $mode])];
}

/* ── صفحهٔ مدیریت: بروزرسانی ─────────────────────────────────────────────── */

function update_screen_text(bool $force = true): string
{
    $status = update_status($force);
    $remote = $status['remote'] !== '' ? $status['remote'] : 'نامشخص';
    $line = $status['available']
        ? '🟠 نسخهٔ جدید در دسترس است.'
        : ($status['remote'] === ''
            ? '⚪️ نسخهٔ دوردست خوانده نشد؛ اتصال سرور به گیت‌هاب را بررسی کنید.'
            : '🟢 روی آخرین نسخه هستید.');

    $offlineNote = ($status['source'] ?? '') === 'offline-cache'
        ? "⚪️ اتصال به گیت‌هاب برقرار نشد؛ این شماره از آخرین بررسی ذخیره شده است."
            . "\n" : '';
    return '⬆️ <b>بروزرسانی ربات</b>' . "\n" . SEP . "\n"
        . 'نسخهٔ نصب‌شده: <b>' . e($status['local']) . '</b>' . "\n"
        . 'آخرین نسخه در گیت‌هاب: <b>' . e($remote) . '</b>' . "\n"
        . $offlineNote
        . $line . "\n" . SEP . "\n"
        . '📦 منبع: <code>' . e($status['repo']) . '</code> · شاخهٔ ' . e($status['branch']) . "\n"
        . 'دیتابیس، فایل تنظیمات و بکاپ‌ها در آپدیت دست‌نخورده می‌مانند.';
}

function update_screen_kb(bool $available): array
{
    $rows = [];
    if ($available) {
        $rows[] = [btn('⬆️ بروزرسانی کن', 'ad:upd:run', null, 'danger')];
    }
    $rows[] = [btn('🔄 بررسی مجدد', 'ad:upd:check', null, 'primary')];
    $rows[] = [btn('« بازگشت به تنظیمات', 'ad:settings', null, 'danger')];
    return kb_clean($rows);
}

function screen_update(int|string $chat, ?int $messageId, bool $force = true): void
{
    $status = update_status($force);
    Tg::show($chat, $messageId, update_screen_text($force), update_screen_kb((bool) $status['available']));
}

/** دکمهٔ «بروزرسانی کن» — انجام، گزارش نتیجه به همان پیام */
function update_run_from_bot(int|string $chat, ?int $messageId): void
{
    [$ok, $message] = update_apply();
    if (!$ok) {
        $text = $message === 'already-latest'
            ? '✅ شما روی آخرین نسخه هستید و نیازی به بروزرسانی نیست.'
            : '⚠️ بروزرسانی انجام نشد: ' . e($message);
        Tg::show($chat, $messageId, $text . "\n" . SEP . "\n" . update_screen_text(true),
            update_screen_kb(false));
        return;
    }
    $data = (array) json_decode($message, true);
    $new = (string) ($data['version'] ?? '');
    Tg::show($chat, $messageId,
        '✅ ربات با موفقیت به نسخهٔ <b>' . e($new) . '</b> بروزرسانی شد.' . "\n" . SEP . "\n"
        . 'دیتابیس و تنظیمات دست‌نخورده ماندند. سرویس همین حالا ری‌استارت می‌شود.',
        [[btn('🔄 بررسی وضعیت', 'ad:upd', null, 'success')]]);
}
