    }
    $text .= "\n🔋 شارژ کیف پول: " . money($stats['topups']) . "\n"
        . '⚡️ مصرف: ' . money($stats['usage']) . "\n"
        . '↩️ بازگشت وجه: ' . money($stats['refunds']) . "\n\n";
