/*
   ماژول احراز هویت چندسطحی (KYC) — لایهٔ گارد، جدا از هستهٔ پرداخت.

   این ماژول هیچ جدول یا فیلد پرداختی را تغییر نمی‌دهد. وظیفه‌ها:
     · سنجش سقف روزانه/ماهانهٔ واریز کارت‌به‌کارت از رسیدهای تأییدشده،
     · ثبت و احراز کارت‌های کاربر،
     · گرفتن درخواست سطح ۱ و ۲ با گردش‌کار کامل،
     · تأیید/رد مدیر و ارسال عکس و کپشن به تاپیک همان سطح.
*/

const KYC_LEVEL_TITLES = [
    0 => 'بدون احراز هویت',
    1 => 'احراز سطح ۱',
    2 => 'احراز سطح ۲',
];

/** بالاترین سطح احراز هویت در این نسخه */
const KYC_MAX_LEVEL = 2;

/** خط جداکنندهٔ استاندارد پیام‌ها */
const SEP = '➖➖➖➖➖➖➖➖';

/** پیش‌شماره‌های کارت بانکی ایران → نام بانک */
const KYC_CARD_BANKS = [
    '603799' => 'بانک ملی ایران', '603770' => 'بانک کشاورزی', '603769' => 'بانک صادرات',
    '610433' => 'بانک ملت', '991020' => 'بانک ملت', '627412' => 'بانک اقتصاد نوین',
    '627381' => 'بانک انصار', '505785' => 'بانک ایران زمین', '622106' => 'بانک پارسیان',
    '622994' => 'بانک پارسیان', '639194' => 'بانک پارسیان', '585983' => 'بانک تجارت',
    '627393' => 'بانک تجارت', '627760' => 'پست بانک ایران', '639347' => 'پست بانک ایران',
    '627648' => 'بانک توسعه صادرات', '627649' => 'بانک توسعه صادرات',
    '636214' => 'بانک آینده', '502229' => 'بانک پاسارگاد', '639607' => 'بانک سرمایه',
    '639346' => 'بانک سینا', '502806' => 'بانک شهر', '504706' => 'بانک شهر',
    '628023' => 'بانک مسکن', '621986' => 'بانک سامان', '589463' => 'بانک رفاه کارگران',
    '639370' => 'بانک مهر ایران', '627960' => 'بانک کوثر', '627488' => 'بانک قوامین',
    '636795' => 'بانک مرکزی', '505416' => 'بانک گردشگری', '505801' => 'بانک سپه',
    '627353' => 'بانک صنعت و معدن', '627961' => 'بانک صنعت و معدن', '589210' => 'بانک سپه',
    '636949' => 'بانک حکمت ایرانیان', '627884' => 'بانک دی', '502938' => 'بانک دی',
    '585983' => 'بانک تجارت', '639599' => 'بانک قرض‌الحسنه رسالت',
];

/* ── ۱) خواندن وضعیت ─────────────────────────────────────────────────────── */

function kyc_on(): bool
{
    return set_bool('kyc_on', true);
}

function kyc_level(int $uid): int
{
    $level = (int) DB::val('SELECT kyc_level FROM users WHERE tg_id=?', [$uid], 0);
    return max(0, min(KYC_MAX_LEVEL, $level));
}

function kyc_set_level(int $uid, int $level): void
{
    DB::exec('UPDATE users SET kyc_level=? WHERE tg_id=?',
        [max(0, min(KYC_MAX_LEVEL, $level)), $uid]);
}

/** سقف روزانه و ماهانهٔ هر سطح (تومان) */
function kyc_caps(int $level): array
{
    $level = max(0, min(KYC_MAX_LEVEL, $level));
    return [set_int('kyc_l' . $level . '_daily', 500000),
            set_int('kyc_l' . $level . '_monthly', 5000000)];
}

/** تبدیل تاریخ شمسی به میلادی (برای پیدا کردن اول ماه) */
function j2g(int $jy, int $jm, int $jd): array
{
    $jy += 1595;
    $days = -355668 + (365 * $jy) + (intdiv($jy, 33) * 8)
        + intdiv(($jy % 33) + 3, 4) + $jd
        + (($jm < 7) ? ($jm - 1) * 31 : (($jm - 7) * 30) + 186);
    $gy = 400 * intdiv($days, 146097);
    $days %= 146097;
    if ($days > 36524) {
        $gy += 100 * intdiv(--$days, 36524);
        $days %= 36524;
        if ($days >= 365) {
            $days++;
        }
    }
    $gy += 4 * intdiv($days, 1461);
    $days %= 1461;
    if ($days > 365) {
        $gy += intdiv(--$days, 365);
        $days %= 365;
    }
    $gd = $days + 1;
    $leap = (($gy % 4 === 0 && $gy % 100 !== 0) || $gy % 400 === 0);
    $lengths = [31, $leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    $gm = 1;
    foreach ($lengths as $len) {
        if ($gd <= $len) {
            break;
        }
        $gd -= $len;
        $gm++;
    }
    return [$gy, $gm, $gd];
}

/** منطقهٔ زمانی ایران (+03:30) */
function kyc_iran_tz(): DateTimeZone
{
    return new DateTimeZone('Asia/Tehran');
}

/** آغاز روز (۰۰:۰۰) و آغاز ماه شمسی به وقت ایران */
function kyc_day_start(?int $ts = null): int
{
    $ts = $ts ?? now_ts();
    [$jy, $jm, $jd] = jparts($ts);
    [$gy, $gm, $gd] = j2g($jy, $jm, $jd);
    $dt = new DateTimeImmutable(sprintf('%04d-%02d-%02d 00:00:00', $gy, $gm, $gd),
        kyc_iran_tz());
    return $dt->getTimestamp();
}

function kyc_month_start(?int $ts = null): int
{
    $ts = $ts ?? now_ts();
    [$jy, $jm] = jparts($ts);
    [$gy, $gm, $gd] = j2g($jy, $jm, 1);
    $dt = new DateTimeImmutable(sprintf('%04d-%02d-%02d 00:00:00', $gy, $gm, $gd),
        kyc_iran_tz());
    return $dt->getTimestamp();
}

/**
 * مصرف سقف: جمع رسیدهای کارت‌به‌کارتِ تأییدشده در بازه.
 * فقط خواندن از جدول موجود رسیدها — هیچ نوشتنی در هستهٔ پرداخت انجام نمی‌شود.
 */
function kyc_spent(int $uid, ?int $ts = null): array
{
    $ts = $ts ?? now_ts();
    $day = (int) DB::val("SELECT COALESCE(SUM(amount),0) FROM receipts "
        . "WHERE tg_id=? AND status='approved' AND reviewed_at>=?", [$uid, kyc_day_start($ts)], 0);
    $month = (int) DB::val("SELECT COALESCE(SUM(amount),0) FROM receipts "
        . "WHERE tg_id=? AND status='approved' AND reviewed_at>=?",
        [$uid, kyc_month_start($ts)], 0);
    return ['day' => $day, 'month' => $month];
}

function kyc_summary(int $uid, ?int $ts = null): array
{
    $level = kyc_level($uid);
    [$daily, $monthly] = kyc_caps($level);
    $spent = kyc_spent($uid, $ts);
    return [
        'level' => $level,
        'title' => KYC_LEVEL_TITLES[$level],
        'daily' => $daily,
        'monthly' => $monthly,
        'spent_day' => $spent['day'],
        'spent_month' => $spent['month'],
        'left_day' => max(0, $daily - $spent['day']),
        'left_month' => max(0, $monthly - $spent['month']),
    ];
}

/* ── ۲) کارت‌ها ──────────────────────────────────────────────────────────── */

function kyc_cards(int $uid, ?string $status = null): array
{
    if ($status !== null) {
        return DB::all('SELECT * FROM kyc_cards WHERE tg_id=? AND status=? ORDER BY id DESC',
            [$uid, $status]);
    }
    return DB::all('SELECT * FROM kyc_cards WHERE tg_id=? ORDER BY id DESC', [$uid]);
}

function kyc_card_get(int $cardId): ?array
{
    return DB::one('SELECT * FROM kyc_cards WHERE id=?', [$cardId]);
}

function kyc_card_mask(string $number): string
{
    $digits = preg_replace('/\D+/', '', fa_digits($number)) ?? '';
    if (strlen($digits) !== 16) {
        return $digits === '' ? '—' : $digits;
    }
    return substr($digits, 0, 4) . '-****-****-' . substr($digits, 12);
}

function kyc_card_bank(string $number): string
{
    $digits = preg_replace('/\D+/', '', fa_digits($number)) ?? '';
    return KYC_CARD_BANKS[substr($digits, 0, 6)] ?? 'نامشخص';
}

/** اعتبارسنجی لان (همهٔ کارت‌های بانکی ایران این شرط را دارند) */
function kyc_card_valid(string $number): bool
{
    $digits = preg_replace('/\D+/', '', fa_digits($number)) ?? '';
    if (!preg_match('/^\d{16}$/', $digits)) {
        return false;
    }
    $sum = 0;
    for ($i = 0; $i < 16; $i++) {
        $digit = (int) $digits[15 - $i];
        if ($i % 2 === 1) {
            $digit *= 2;
            if ($digit > 9) {
                $digit -= 9;
            }
        }
        $sum += $digit;
    }
    return $sum % 10 === 0;
}

function kyc_card_find(int $uid, string $number): ?array
{
    $digits = preg_replace('/\D+/', '', fa_digits($number)) ?? '';
    return DB::one('SELECT * FROM kyc_cards WHERE tg_id=? AND card_number=?', [$uid, $digits]);
}

function kyc_cards_verified(int $uid): array
{
    return kyc_cards($uid, 'verified');
}

/**
 * قفل حساب به کارت‌های احرازشده:
 * تا وقتی هیچ کارتی احراز نشده، واریز از هر کارت ثبت‌شده آزاد است؛
 * بعد از اولین احراز، فقط کارت‌های احرازشده معتبرند.
 */
function kyc_locked_to_verified(int $uid): bool
{
    return count(kyc_cards_verified($uid)) > 0;
}

function kyc_pending_request(int $uid): ?array
{
    return DB::one("SELECT * FROM kyc_requests WHERE tg_id=? AND status='pending' "
        . 'ORDER BY id DESC LIMIT 1', [$uid]);
}

/* ── ۳) گارد واریز کارت‌به‌کارت (نقطهٔ اتصال به هستهٔ پرداخت) ─────────────── */

/**
 * اگر واریز باید متوقف شود، پیام + دکمه‌ها را برمی‌گرداند؛ وگرنه null.
 * ترتیب سنجش: سقف روزانه ← سقف ماهانه ← کارت احرازشده.
 */
function kyc_guard(int $uid, int $amount, int $orderId = 0): ?array
{
    if (!kyc_on() || is_owner($uid)) {
        return null;
    }
    $sum = kyc_summary($uid);
    $amount = max(0, $amount);
    $back = [btn('« بازگشت', 'home', null, 'danger')];
    $levelText = kyc_level_emoji($sum['level']) . ' ' . $sum['title'];

    /* راهکارهای همیشگی: ارتقا، رمزارز، استارز. سقف فقط برای کارت‌به‌کارت است. */
    $solutions = "💡 راهکارها برای ادامه واریز/خرید:\n\n"
        . '۱. ارتقای سطح احراز هویت از منوی حساب کاربری جهت افزایش سقف ریالی.' . "\n\n"
        . '۲. استفاده از درگاه‌های رمزارزی (کریپتو) — بدون هیچ‌گونه محدودیت سقف و '
        . 'بدون نیاز به احراز هویت.' . "\n\n"
        . '۳. پرداخت مستقیم با استارز تلگرام (Telegram Stars ⭐) — کاملاً بدون '
        . 'محدودیت سقف.';
    /* دکمهٔ «بدون سقف» به همان لیست درگاه‌ها می‌رود تا کاربر کریپتو/استارز
       را انتخاب کند؛ هیچ سقفی روی آن دو نیست. */
    $noCapData = $orderId > 0 ? 'inv:gw:' . $orderId : 'home';
    $buttons = [
        [btn('⬆️ ارتقای سطح احراز هویت', 'kyc:up:'
            . min(KYC_MAX_LEVEL, $sum['level'] + 1), null, 'success')],
        [btn('₿ / ⭐️ پرداخت بدون سقف (کریپتو و استارز)', $noCapData, null, 'primary')],
        [btn('🪪 وضعیت احراز هویت', 'kyc:home', null, 'primary')],
        $back,
    ];

    if ($amount > $sum['left_day']) {
        return ['text' => "⚠️ کاربر گرامی، مبلغ درخواستی بیشتر از سقف مجاز واریز "
            . "روزانه شما با کارت‌به‌کارت است!\n\n"
            . "📊 وضعیت شما:\n\n"
            . '• سطح فعلی: ' . $levelText . "\n\n"
            . '• سقف مجاز روزانه: ' . money($sum['daily']) . "\n\n"
            . '• باقی‌مانده سقف امروز: ' . money($sum['left_day']) . "\n\n"
            . '• مبلغ این سفارش: ' . money($amount) . "\n\n"
            . $solutions, 'kb' => $buttons];
    }

    if ($amount > $sum['left_month']) {
        return ['text' => "⚠️ کاربر گرامی، مبلغ درخواستی بیشتر از سقف مجاز واریز "
            . "ماهانه شما با کارت‌به‌کارت است!\n\n"
            . "📊 وضعیت شما:\n\n"
            . '• سطح فعلی: ' . $levelText . "\n\n"
            . '• سقف مجاز ماهانه: ' . money($sum['monthly']) . "\n\n"
            . '• باقی‌مانده سقف این ماه: ' . money($sum['left_month']) . "\n\n"
            . '• مبلغ این سفارش: ' . money($amount) . "\n\n"
            . "این سقف اول هر ماه شمسی از نو شمرده می‌شود.\n\n"
            . $solutions, 'kb' => $buttons];
    }

    if ($sum['level'] >= 1 && count(kyc_cards_verified($uid)) === 0) {
        return ['text' => "⚠️ کاربر گرامی، برای واریز کارت‌به‌کارت باید حداقل یک "
            . "کارت احرازشده داشته باشید.\n\n"
            . "📊 وضعیت شما:\n\n"
            . '• سطح فعلی: ' . $levelText . "\n\n"
            . '• کارت احرازشده: ۰' . "\n\n"
            . "حساب شما در این سطح فقط از کارت‌های احرازشده واریز می‌گیرد.\n\n"
            . $solutions, 'kb' => [
                [btn('💳 کارت‌های من', 'kyc:cards', null, 'success')],
                [btn('₿ / ⭐️ پرداخت بدون سقف (کریپتو و استارز)', $noCapData,
                    null, 'primary')],
                $back,
            ]];
    }

    return null;
}

/**
 * گارد در نقطهٔ انتخاب درگاه: اگر کاربر کارت‌به‌کارت را انتخاب کرد و
 * فاکتور از سقف رد شده بود، همان‌جا جلویش گرفته می‌شود. کریپتو و استارز
 * هیچ‌وقت به این تابع نمی‌رسند.
 */
function kyc_guard_gateway(int|string $chat, ?int $messageId, int $uid, array $order): bool
{
    $block = kyc_guard($uid, (int) $order['payable'], (int) $order['id']);
    if ($block === null) {
        return false;
    }
    Tg::show($chat, $messageId, $block['text'], $block['kb']);
    return true;
}


/* ── ۴) متن‌ها و صفحه‌ها ─────────────────────────────────────────────────── */

const KYC_TERMS_TEXT = "📜 <b>Terms and conditions</b>\n\n"
    . "۱. کارتی که باهاش واریز انجام میشه باید به نام خودتون باشه.\n"
    . "۲. مسئولیت هر واریز از کارت متعلق به شخص دیگری که با اکانت شما انجام بشه، "
    . "متعلق به خودته.\n"
    . "۳. اطلاعات و مدارک فقط برای احراز هویت استفاده میشه و در اختیار کسی "
    . "قرار نمی‌گیره.\n"
    . "۴. فروش سرویس به شکلی که خلاف قوانین باشه ممنوعه و باعث مسدود شدن حساب "
    . "می‌شه.\n"
    . "۵. اطلاعات و مدارکی که می‌فرستید باید درست و مال خودتان باشه؛ کارت هم باید "
    . "به نام خودتان باشه.\n"
    . "۶. پشتیبانی می‌تواند هر درخواستی که مدارکش مشکوک یا ناخوانا باشد را رد کند.\n\n"
    . "Pressing the button below means\nyou accept these terms.\n\n"
    . "⚠️ <i>The terms are in Persian and are\nnot translated — this is a contract, "
    . "and\na machine translation of a\ncontract cannot be relied on. Ask\nsupport "
    . "if you need it explained.</i>";

/** دکمهٔ لغوی که همهٔ صفحه‌های KYC باید داشته باشند */
function kyc_cancel_btn(): array
{
    return [btn('❌ انصراف', 'kyc:cancel', null, 'danger')];
}

/** تنها دکمهٔ «یک قدم عقب» در صفحه‌های KYC */
function kyc_back_btn(string $data): array
{
    return [btn('🔙 بازگشت', $data, null, 'primary')];
}

function kyc_level_emoji(int $level): string
{
    return [0 => '⚪️', 1 => '🥇', 2 => '💎'][max(0, min(KYC_MAX_LEVEL, $level))];
}

/** صفحهٔ وضعیت احراز هویت */
function screen_kyc(int|string $chat, ?int $messageId, int $uid): void
{
    $sum = kyc_summary($uid);
    $level = $sum['level'];
    $cards = kyc_cards($uid);
    $verified = 0;
    foreach ($cards as $card) {
        if ($card['status'] === 'verified') {
            $verified++;
        }
    }
    $pending = kyc_pending_request($uid);

    $text = '🪪 <b>سطح احراز هویت</b>' . "\n"
        . SEP . "\n\n"
        . 'سطح فعلی: <b>' . kyc_level_emoji($level) . ' ' . $sum['title'] . "</b>\n\n"
        . '<b>سقف واریز کارت‌به‌کارت</b>' . "\n"
        . '• روزانه: ' . money($sum['daily']) . ' — باقی‌مانده <b>'
        . money($sum['left_day']) . "</b>\n"
        . '• ماهانه: ' . money($sum['monthly']) . ' — باقی‌مانده <b>'
        . money($sum['left_month']) . "</b>\n\n"
        . '<i>این سقف‌ها فقط برای کارت‌به‌کارت است؛ رمزارز و استارز سقف ندارند.</i>'
        . "\n" . SEP . "\n"
        . '💳 کارت‌های ثبت‌شده: ' . count($cards) . ' · احرازشده: ' . $verified;

    if ($pending !== null) {
        $text .= "\n\n⏳ یک درخواست سطح <b>" . (int) $pending['level']
            . '</b> هم‌اکنون در حال بررسی است.';
    }
    if (kyc_locked_to_verified($uid)) {
        $one = kyc_cards_verified($uid)[0] ?? null;
        if ($one !== null) {
            $text .= "\n\n🔒 حسابتان به کارت‌های احرازشده قفل شده؛ واریز فقط از "
                . '<code>' . e(kyc_card_mask((string) $one['card_number'])) . '</code> '
                . 'و کارت‌های احرازشدهٔ دیگر.';
        }
    }

    $rows = [];
    $next = $level + 1;
    if ($next <= KYC_MAX_LEVEL) {
        [$nd, $nm] = kyc_caps($next);
        $text .= "\n\n↗️ <b>ارتقا به " . KYC_LEVEL_TITLES[$next] . "</b>\n"
            . 'سقف روزانه ' . money($nd) . ' • ماهانه ' . money($nm) . "\n";
        if ($next === 1) {
            $text .= "\n<b>چی لازمه:</b>\n· یک کارت بانکی به نام خودتان\n"
                . '· عکس همان کارت فیزیکی در دست';
        } elseif ($next === 2) {
            $text .= "\n<b>چی لازمه:</b>\n· نام و نام خانوادگی\n· کد ملی\n"
                . '· تاریخ تولد' . "\n· شماره تماس\n"
                . '· یک عکس سلفی که چهره‌ات و کارت ملی و کارت بانکی کنار هم '
                . 'در آن باشد';
        }
        if ($pending === null || (int) $pending['level'] < $next) {
            $rows[] = [btn('⬆️ ارتقا به ' . KYC_LEVEL_TITLES[$next], 'kyc:up:' . $next,
                null, 'success')];
        }
    }
    $rows[] = [btn('💳 کارت‌های من', 'kyc:cards', null, 'primary')];
    $rows[] = [btn('🔙 بازگشت', 'menu:wallet', null, 'danger')];
    Tg::show($chat, $messageId, $text, $rows);
}

/** فهرست کارت‌های کاربر */
function screen_kyc_cards(int|string $chat, ?int $messageId, int $uid): void
{
    $cards = kyc_cards($uid);
    $text = "💳 <b>کارت‌های من</b>\n" . SEP . "\n\n";
    if (!$cards) {
        $text .= "هنوز هیچ کارتی ثبت نکردی.\n"
            . 'شمارهٔ ۱۶ رقمی کارتی که می‌خواهید با آن واریز کنید را ثبت کنید.';
    } else {
        $text .= 'هر کارتی که ثبت می‌کنی، با یک عکس از خودِ کارت فیزیکی احراز '
            . "می‌شود.\n\n";
        foreach ($cards as $card) {
            $statusText = match ($card['status']) {
                'verified' => '✅ احراز شده',
                'pending' => '⏳ در انتظار احراز',
                'rejected' => '❌ رد شده',
                default => '⏳ در انتظار احراز',
            };
            $text .= '· <code>' . e(kyc_card_mask((string) $card['card_number'])) . '</code>'
                . ' — ' . e((string) $card['bank']) . ' — ' . $statusText . "\n";
        }
    }
    if (kyc_locked_to_verified($uid)) {
        $text .= "\n🔒 بعد از اولین احراز، حسابتان فقط با کارت‌های احرازشده واریز "
            . 'می‌گیرد.';
    }
    $rows = [];
    foreach ($cards as $card) {
        if ($card['status'] === 'verified') {
            continue;
        }
        $rows[] = [btn('📸 احراز کارت ' . kyc_card_mask((string) $card['card_number']),
            'kyc:cardv:' . (int) $card['id'], null, 'success')];
    }
    $rows[] = [btn('➕ افزودن کارت', 'kyc:add', null, 'primary')];
    $rows[] = [btn('🔙 بازگشت', 'kyc:home', null, 'danger')];
    Tg::show($chat, $messageId, $text, $rows);
}

/** درخواست شمارهٔ ۱۶ رقمی کارت */
function kyc_ask_card(int|string $chat, int $uid): void
{
    $prev = (array) (State::get($uid)['data'] ?? []);
    kyc_forget($chat, 0, $prev);
    kyc_prompt($uid, 'kyc_card', [], "➕ <b>افزودن کارت</b>\n\n"
        . 'شمارهٔ ۱۶ رقمی کارتی که می‌خواهید با آن واریز کنید را بفرستید.' . "\n\n"
        . 'کارت باید به نام خودتان باشد.');
}

/** صفحهٔ شرایط و قوانین */
function screen_kyc_terms(int|string $chat, ?int $messageId, int $uid, int $level,
                          int $cardId = 0): void
{
    $back = $level >= 2 ? 'kyc:home' : 'kyc:cards';
    Tg::show($chat, $messageId, KYC_TERMS_TEXT, [
        [btn('✅ می‌پذیرم', 'kyc:accept:' . $level . ':' . $cardId, null, 'success')],
        kyc_back_btn($back),
    ]);
}

/**
 * ارسال عکس نمونه (بنر مقایسهٔ کارت فیزیکی و اسکرین‌شات) + متن راهنما،
 * سپس رفتن به حالت انتظار عکس.
 */
function kyc_send_banner(int $uid, int $level, int $cardId, string $cardMask,
                         ?array $carry = null): void
{
    if ($level >= 2) {
        $instructions = "📸 <b>عکس سلفی با مدارک</b>" . "\n"
            . "➖➖➖➖➖➖➖➖" . "\n\n"
            . 'کارت ملی و کارت بانکی را با دو دست، با فاصله‌ای متعارف، '
            . "زیر صورتت نگه دار؛\n"
            . 'طوری که هم <b>چهره‌ات کاملاً واضح</b> باشد و هم متن و اعداد هر دو '
            . "کارت خوانا.\n\n"
            . "✅ <b>درست</b>\n"
            . '• چهره‌ات کامل و بدون ماسک و عینک تیره در کادر باشد.' . "\n"
            . '• هر دو کارت کامل، بدون تاری و بدون انعکاس نور.' . "\n"
            . '• شمارهٔ کارت و کد ملی خوانا باشند.' . "\n\n"
            . "❌ <b>قبول نمی‌شود</b>\n"
            . '• عکسی که صورتت در آن نیست یا نصفه است.' . "\n"
            . '• اسکرین‌شات، عکس از صفحهٔ گوشی یا عکس فوروارد شده.' . "\n"
            . '• کارت ناخوانا، تار یا با بازتاب نور.' . "\n"
            . '• کارتی که به نام خودتان نیست.';
        $stateName = 'kyc_l2_photo';
    } else {
        $instructions = "📸 <b>احراز کارت " . $cardMask . "</b>" . "\n"
            . "➖➖➖➖➖➖➖➖" . "\n\n"
            . 'عکس همین کارت را بفرستید — یک عکس تازه با دوربین گوشی از خودِ کارت '
            . "فیزیکی، در حالی که توی دستت است.\n\n"
            . "✅ <b>درست</b>\n"
            . '• کارت توی دستت باشد و انگشت‌هایت توی عکس معلوم باشند.' . "\n"
            . '• شمارهٔ ۱۶ رقمی و نام صاحب کارت کامل و خوانا باشند.' . "\n"
            . '• کارت بیشترِ عکس را پر کند؛ نور کافی، بدون برق فلاش.' . "\n"
            . '• تاریخ انقضا و CVV2 لازم نیست — با انگشتت بپوشانشان.' . "\n\n"
            . "❌ <b>قبول نمی‌شود</b>\n"
            . '• اسکرین‌شات یا عکس از همراه بانک، اپ بانک یا کارت مجازی.' . "\n"
            . '• عکس از روی صفحهٔ گوشی یا لپ‌تاپ، یا عکس یک عکس.' . "\n"
            . '• عکس فوروارد شده.' . "\n"
            . '• کارتی که به نام خودتان نیست.';
        $stateName = 'kyc_photo_1';
    }
    $carry = $carry ?? (array) (State::get($uid)['data'] ?? []);
    kyc_prompt($uid, $stateName, ['card_id' => $cardId] + $carry, $instructions);
    kyc_send_banner_image($uid, $level);
}

/** ارسال تصویر نمونهٔ همان سطح (یک‌بار آپلود می‌شود و file_id آن کش می‌شود) */
function kyc_send_banner_image(int $uid, int $level = 1): void
{
    $level = $level >= 2 ? 2 : 1;
    $caption = $level >= 2
        ? '🖼 <b>نمونهٔ عکس درست و غلط</b>' . "\n"
            . 'کارت ملی و کارت بانکی زیر صورت، در دست ✅ · اسکرین‌شات صورت ❌'
        : '🖼 <b>نمونهٔ عکس درست و غلط</b>' . "\n"
            . 'کارت فیزیکی توی دستت ✅ · اسکرین‌شات و عکس صفحه ❌';
    $key = $level >= 2 ? 'kyc_banner2_file' : 'kyc_banner_file';
    $fileId = trim(set_get($key));
    if ($fileId !== '') {
        Tg::photo($uid, $fileId, $caption);
        return;
    }
    /* عکس فقط برای گرفتن file_id یک لحظه روی سرور نوشته می‌شود و
       بلافاصله پاک می‌شود؛ هیچ مدرکی روی دیسک نمی‌ماند. */
    $saved = kyc_upload_banner($uid, $caption, $level);
    if ($saved !== '') {
        set_put($key, $saved);
    }
}

/** تصویر نمونهٔ داخل کد را روی سرور می‌نویسد و به تلگرام آپلود می‌کند */
function kyc_upload_banner(int $uid, string $caption, int $level = 1): string
{
    $bytes = base64_decode($level >= 2 ? KYC_BANNER2_B64 : KYC_BANNER_B64, true);
    if ($bytes === false || $bytes === '') {
        return '';
    }
    $path = sys_get_temp_dir() . '/panel_kyc_banner_' . $level . '_'
        . bin2hex(random_bytes(4)) . '.jpg';
    if (@file_put_contents($path, $bytes) === false) {
        return '';
    }
    try {
        return Tg::uploadPhoto($uid, $path, $caption);
    } finally {
        /* مدارک و بنر هیچ‌وقت روی دیسک نمی‌مانند */
        @unlink($path);
    }
}

/* ── ۵) ثبت درخواست و کارت به کارت ─────────────────────────────────────── */

/** شناسهٔ تاپیک هر سطح در گروه گزارشات */
function kyc_topic_id(int $level): int
{
    $level = max(1, min(KYC_MAX_LEVEL, $level));
    return max(0, set_int('kyc_topic_' . $level, 0));
}

/** نام دقیق تاپیک‌ها در سوپرگروه گزارشات (خواستهٔ مالک) */
const KYC_TOPIC_TITLES = [
    1 => 'احرازی های سطح 1',
    2 => 'احرازی های سطح 2',
];

/**
 * تاپیک اختصاصی همان سطح. اگر ساخته نشده باشد، یک‌بار ساخته و ذخیره می‌شود؛
 * تلاش ناموفق تا ۱۰ دقیقه تکرار نمی‌شود تا به API فشار نیاید.
 */
function kyc_topic_ensure(int $level): int
{
    $level = max(1, min(KYC_MAX_LEVEL, $level));
    $have = kyc_topic_id($level);
    if ($have > 0) {
        return $have;
    }
    $chat = report_chat_id();
    if ($chat === '') {
        return 0;
    }
    if ((int) set_get('kyc_topic_fail_at', '0') > now_ts() - 600) {
        return 0;
    }
    $thread = Tg::createTopic($chat, KYC_TOPIC_TITLES[$level]);
    if ($thread <= 0) {
        set_put('kyc_topic_fail_at', (string) now_ts());
        log_line('warning', 'kyc topic create failed', ['level' => $level, 'chat' => $chat]);
        return 0;
    }
    set_put('kyc_topic_' . $level, (string) $thread);
    Tg::sendThread($chat, '📌 این تاپیک مخصوص بایگانی دائمی «'
        . KYC_TOPIC_TITLES[$level] . '» است؛ هیچ پیامی از این تاپیک پاک نمی‌شود.',
        $thread);
    return $thread;
}

/**
 * نام قطعی تاپیک‌ها را روی تلگرام اعمال می‌کند (اگر تاپیک از قبل با نام
 * دیگری ساخته شده باشد). یک‌بار برای هر شناسه انجام می‌شود.
 */
function kyc_topics_rename(): void
{
    $chat = report_chat_id();
    if ($chat === '') {
        return;
    }
    $done = (string) set_get('kyc_topic_named', '');
    $stamp = [];
    foreach ([1, 2] as $level) {
        $thread = kyc_topic_id($level);
        if ($thread <= 0 || str_contains($done, $level . ':' . $thread)) {
            continue;
        }
        $res = Tg::call('editForumTopic', ['chat_id' => $chat,
            'message_thread_id' => $thread, 'name' => KYC_TOPIC_TITLES[$level]]);
        if (is_array($res) && ($res['ok'] ?? false) === true) {
            $stamp[] = $level . ':' . $thread;
        }
    }
    if ($stamp !== []) {
        set_put('kyc_topic_named', trim($done . ',' . implode(',', $stamp), ','));
    }
}

/**
 * در استارتاپ: اگر تاپیک‌های احراز هویت نبودند بساز، و نام قطعی را بگذار.
 * اگر گروه تنظیم نشده باشد، هیچ کاری نمی‌کند (و لاگ هم نمی‌سوزاند).
 */
function kyc_topics_startup(): void
{
    if (!kyc_on() || report_chat_id() === '') {
        return;
    }
    $made = false;
    foreach ([1, 2] as $level) {
        if (kyc_topic_id($level) <= 0) {
            set_put('kyc_topic_fail_at', '0');
            if (kyc_topic_ensure($level) > 0) {
                $made = true;
            }
        }
    }
    if ($made) {
        log_line('info', 'kyc topics created on startup',
            ['1' => kyc_topic_id(1), '2' => kyc_topic_id(2)]);
    }
    kyc_topics_rename();
}

/** ساخت/بازیابی تاپیک‌های KYC — خروجی: [موفق, متن] */
function kyc_topics_build(): array
{
    if (report_chat_id() === '') {
        return [false, 'اول گروه گزارشات را ثبت کنید.'];
    }
    $made = 0;
    $have = 0;
    $failed = 0;
    foreach ([1, 2] as $level) {
        if (kyc_topic_id($level) > 0) {
            $have++;
            continue;
        }
        set_put('kyc_topic_fail_at', '0');
        if (kyc_topic_ensure($level) > 0) {
            $made++;
        } else {
            $failed++;
        }
    }
    $text = 'تاپیک‌های احراز هویت — آماده: ' . fa_digits($have)
        . ' · تازه ساخته شد: ' . fa_digits($made)
        . ($failed > 0 ? ' · ناموفق: ' . fa_digits($failed) . ' (ربات باید در گروه '
            . 'مدیر باشد و گروه «تاپیک» داشته باشد)' : '');
    return [$failed === 0, $text];
}

function kyc_photo_id(array $message): string
{
    if (isset($message['photo']) && is_array($message['photo'])) {
        $sizes = $message['photo'];
        return (string) (end($sizes)['file_id'] ?? '');
    }
    if (isset($message['document']['file_id'])
        && str_starts_with((string) ($message['document']['mime_type'] ?? ''), 'image/')) {
        return (string) $message['document']['file_id'];
    }
    return '';
}

/** ثبت درخواست احراز + کارت بررسی برای مدیران */
function kyc_submit_request(int $uid, int $level, string $photoId, array $payload,
                            int $cardId = 0): int
{
    $reqId = DB::exec('INSERT INTO kyc_requests(tg_id, level, status, payload, photo_id, '
        . 'card_id, created_at) VALUES(?,?,?,?,?,?,?)',
        [$uid, $level, 'pending', json_encode($payload, JSON_UNESCAPED_UNICODE),
         $photoId, $cardId, now_ts()]);
    State::clear($uid);
    Tg::send($uid, "✅ <b>درخواستت ثبت شد</b>\n\n"
        . 'سطح: <b>' . KYC_LEVEL_TITLES[$level] . "</b>\n"
        . 'همین حالا برای بررسی به مدیر فرستادم. نتیجه را همین‌جا بهت خبر می‌دهم.'
        . "\n\n" . 'تا آن موقع می‌توانید از ربات استفاده کنید.',
        [[btn('🪪 وضعیت احراز هویت', 'kyc:home', null, 'primary')]]);
    kyc_post_admin_card($reqId);
    return $reqId;
}

/** کارت بررسی درخواست برای همهٔ مدیران (چت خصوصی) */
function kyc_post_admin_card(int $reqId): void
{
    $req = DB::one('SELECT * FROM kyc_requests WHERE id=?', [$reqId]);
    if ($req === null) {
        return;
    }
    $uid = (int) $req['tg_id'];
    $photo = (string) $req['photo_id'];
    $kb = kb_ensure_back(kb_clean([
        [btn('✅ تایید احراز هویت', 'kyc:ok:' . $reqId, null, 'success')],
        [btn('❌ رد درخواست', 'kyc:no:' . $reqId, null, 'danger')],
    ]));
    $caption = kyc_admin_card_caption($req);
    foreach (receipt_targets() as $adminId) {
        if ($photo !== '') {
            Tg::photoThread($adminId, $photo, $caption, 0, $kb);
        } else {
            Tg::send($adminId, $caption, $kb);
        }
    }
}

/** متن کامل درخواست برای مدیر */
function kyc_admin_card_caption(array $req): string
{
    $uid = (int) $req['tg_id'];
    $level = (int) $req['level'];
    $user = user_get($uid);
    $payload = json_decode((string) ($req['payload'] ?? ''), true);
    $payload = is_array($payload) ? $payload : [];
    [$name, $uname] = receipt_who($uid);
    $text = '🪪 <b>درخواست ' . KYC_LEVEL_TITLES[$level] . ' #' . (int) $req['id'] . "</b>\n\n"
        . '👤 ' . e($name) . ' · <code>' . $uid . '</code>' . "\n"
        . '🔗 ' . e($uname) . "\n"
        . '📎 لینک: ' . (trim((string) ($user['uname'] ?? '')) !== ''
            ? '<a href="https://t.me/' . e((string) $user['uname']) . '">t.me/'
                . e((string) $user['uname']) . '</a>'
            : '<a href="tg://user?id=' . $uid . '">پیام به کاربر</a>') . "\n"
        . '📅 ثبت‌نام: ' . fa_ts((int) ($user['created_at'] ?? 0)) . "\n"
        . '🪪 سطح فعلی: ' . KYC_LEVEL_TITLES[kyc_level($uid)] . "\n\n";
    if ($level === 1) {
        $card = kyc_card_get((int) ($req['card_id'] ?? 0));
        /* برای مدیر، شمارهٔ ۱۶ رقمی خام و کامل — تا با عکس تطبیق داده شود */
        $text .= '💳 شماره کارت: <code>'
            . e((string) preg_replace('/\D+/', '', (string) ($card['card_number'] ?? '')))
            . "</code>\n"
            . '🏦 بانک: ' . e((string) ($card['bank'] ?? '—')) . "\n";
    } else {
        $text .= '📝 نام: ' . e((string) ($payload['name'] ?? '—')) . "\n"
            . '📝 نام خانوادگی: ' . e((string) ($payload['family'] ?? '—')) . "\n"
            . '🔢 کد ملی: <code>' . e((string) ($payload['ncode'] ?? '—')) . "</code>\n"
            . '📅 تاریخ تولد: ' . e((string) ($payload['birth'] ?? '—')) . "\n"
            . '📱 شماره تماس: ' . e((string) ($payload['phone'] ?? '—'))
            . ' <i>(ارسال با کانتکت تلگرام ✅)</i>' . "\n";
        $cards = kyc_cards($uid);
        if ($cards) {
            $text .= "💳 کارت‌های ثبت‌شده (شمارهٔ کامل برای تطبیق):\n";
            foreach ($cards as $card) {
                $text .= '· <code>'
                    . e((string) preg_replace('/\D+/', '', (string) $card['card_number']))
                    . '</code> — ' . e((string) $card['bank'])
                    . ' — ' . ($card['status'] === 'verified' ? '✅' : '⏳') . "\n";
            }
        }
    }
    $text .= "\n🕒 " . fa_ts((int) $req['created_at'])
        . "\n<i>عکس مدرک بالای همین پیام است.</i>";
    return $text;
}

/* ── ۶) گردش‌کار سطح ۲ (پرسش‌های گام‌به‌گام) ──────────────────────────────── */

function kyc_l2_start(int $uid, int|string $chat, int $cardId = 0): void
{
    if (kyc_level($uid) < 1) {
        Tg::send($chat, '⛔️ برای احراز سطح ۲ باید اول احراز سطح ۱ تأیید شده باشد.',
            [[btn('🪪 وضعیت احراز هویت', 'kyc:home', null, 'danger')]]);
        return;
    }
    if (kyc_pending_request($uid) !== null) {
        Tg::send($chat, '⏳ یک درخواست در حال بررسی دارید.',
            [[btn('🔙 بازگشت', 'kyc:home', null, 'danger')]]);
        return;
    }
    kyc_prompt($uid, 'kyc_l2_name', ['card_id' => $cardId],
        "📝 <b>نام:</b>\n\n" . 'نام کوچکت را به فارسی بنویسید.');
}

function kyc_ask_phone(int $uid, int $cardId = 0, ?array $carry = null): void
{
    /* دادهٔ گام‌های قبلی حفظ می‌شود؛ فقط وضعیت عوض می‌شود */
    $keep = $carry ?? (array) (State::get($uid)['data'] ?? []);
    if ($cardId > 0) {
        $keep['card_id'] = $cardId;
    }
    State::set($uid, 'kyc_l2_phone', $keep);
    $sent = Tg::call('sendMessage', [
        'chat_id' => $uid,
        'text' => "📱 <b>شماره تماس</b>\n\n"
            . 'برای اینکه شماره‌ات قابل تأیید باشد، دکمهٔ «📱 ارسال شمارهٔ من» را بزن؛ '
            . 'توسط تلگرام تأیید می‌شود.' . "\n\n"
            . 'اگر دکمه را در دسترس ندارید، شماره را همین‌جا بنویسید.',
        'parse_mode' => 'HTML',
        'reply_markup' => [
            'keyboard' => [[['text' => '📱 ارسال شمارهٔ من', 'request_contact' => true]]],
            'resize_keyboard' => true,
            'one_time_keyboard' => true,
        ],
    ]);
    $promptId = (int) ($sent['result']['message_id'] ?? 0);
    if ($promptId > 0) {
        $keep['prompt_msg'] = $promptId;
        State::set($uid, 'kyc_l2_phone', $keep);
    }
    Tg::send($uid, '⌨️ از دکمهٔ پایین استفاده کنید یا شماره‌ات را بنویسید.', [kyc_cancel_btn()]);
}

/** حذف کیبورد پایین صفحه */
function kyc_hide_reply_keyboard(int $uid, string $text): void
{
    Tg::call('sendMessage', ['chat_id' => $uid, 'text' => $text, 'parse_mode' => 'HTML',
        'reply_markup' => ['remove_keyboard' => true]]);
}

/** اعتبارسنجی کد ملی ایران (۱۰ رقم + رقم کنترل) */
function kyc_national_code_ok(string $code): bool
{
    $code = preg_replace('/\D+/', '', fa_digits($code)) ?? '';
    if (!preg_match('/^\d{10}$/', $code)) {
        return false;
    }
    if (preg_match('/^(\d)\1{9}$/', $code)) {
        return false;
    }
    $sum = 0;
    for ($i = 0; $i < 9; $i++) {
        $sum += (int) $code[$i] * (10 - $i);
    }
    $rem = $sum % 11;
    $check = (int) $code[9];
    return $rem < 2 ? $check === $rem : $check === 11 - $rem;
}

/** اعتبارسنجی تاریخ تولد شمسی: 1370/05/03 */
function kyc_birth_ok(string $value): bool
{
    $clean = preg_replace('/\s+/', '', fa_digits($value)) ?? '';
    $clean = str_replace(['-', '.'], '/', $clean);
    if (!preg_match('/^(1[2-4]\d{2})\/(\d{1,2})\/(\d{1,2})$/', $clean, $m)) {
        return false;
    }
    $jy = (int) $m[1];
    $jm = (int) $m[2];
    $jd = (int) $m[3];
    if ($jm < 1 || $jm > 12 || $jd < 1) {
        return false;
    }
    $max = $jm <= 6 ? 31 : ($jm <= 11 ? 30 : 30);
    if ($jd > $max) {
        return false;
    }
    [$cy] = jparts(now_ts());
    return $jy <= $cy && $jy >= 1200;
}

/** نرمال‌سازی شمارهٔ موبایل ایران: 09xxxxxxxxx */
function kyc_phone_clean(string $raw): string
{
    $digits = preg_replace('/\D+/', '', fa_digits($raw)) ?? '';
    if (str_starts_with($digits, '0098')) {
        $digits = substr($digits, 4);
    } elseif (str_starts_with($digits, '98') && strlen($digits) === 12) {
        $digits = substr($digits, 2);
    }
    if (strlen($digits) === 10 && str_starts_with($digits, '9')) {
        $digits = '0' . $digits;
    }
    return preg_match('/^09\d{9}$/', $digits) ? $digits : '';
}

function kyc_valid_persian_name(string $value): bool
{
    $value = trim($value);
    if (mb_strlen($value, 'UTF-8') < 2 || mb_strlen($value, 'UTF-8') > 30) {
        return false;
    }
    return (bool) preg_match('/^[\x{0600}-\x{06FF}\s\x{200c}]+$/u', $value);
}

/* ── ۷) روتر پیام‌های KYC ────────────────────────────────────────────────── */

function kyc_cancel(int|string $chat, int $uid): void
{
    State::clear($uid);
    Tg::call('sendMessage', ['chat_id' => $chat, 'text' => '✖️ لغو شد.',
        'reply_markup' => ['remove_keyboard' => true]]);
    screen_kyc($chat, null, $uid);
}

/**
 * پاک کردن هر ردی از مدارک در چت خصوصی کاربر:
 * خودِ پیام کاربر + پرسش قبلی ربات + پیام تأیید موقت قبلی.
 */
function kyc_forget(int|string $chat, int $userMsgId, array $data): void
{
    if ($userMsgId > 0) {
        Tg::delete($chat, $userMsgId);
    }
    foreach (['prompt_msg', 'ack_msg'] as $key) {
        $id = (int) ($data[$key] ?? 0);
        if ($id > 0 && $id !== $userMsgId) {
            Tg::delete($chat, $id);
        }
    }
}

/** پرسش تازهٔ ربات + ذخیرهٔ شناسهٔ آن تا در گام بعد پاک شود */
function kyc_prompt(int $uid, string $state, array $data, string $text, ?array $kb = null): int
{
    /* شناسهٔ پرسش قبلی دور ریخته می‌شود (خودش قبلاً پاک شده)؛
       پیام «دریافت شد»ِ همین گام می‌ماند تا در گام بعد پاک شود. */
    unset($data['prompt_msg']);
    $GLOBALS['panel_kb_locked'] = true;
    try {
        $msgId = (int) Tg::send($uid, $text, $kb ?? [kyc_cancel_btn()]);
    } finally {
        $GLOBALS['panel_kb_locked'] = false;
    }
    if ($msgId > 0) {
        $data['prompt_msg'] = $msgId;
    }
    State::set($uid, $state, $data);
    return $msgId;
}

/** پیام «دریافت شد» که در گام بعد پاک می‌شود */
function kyc_ack(int $uid, array $data, string $text): array
{
    $msgId = (int) Tg::send($uid, $text);
    if ($msgId > 0) {
        $data['ack_msg'] = $msgId;
    }
    return $data;
}

function kyc_message_router(array $message, array $state): void
{
    $uid = (int) ($message['from']['id'] ?? 0);
    $chat = (int) ($message['chat']['id'] ?? $uid);
    if ($uid === 0) {
        return;
    }
    $text = trim((string) ($message['text'] ?? ''));
    $data = is_array($state['data'] ?? null) ? $state['data'] : [];
    $cardId = (int) ($data['card_id'] ?? 0);
    $userMsgId = (int) ($message['message_id'] ?? 0);
    $lower = mb_strtolower($text, 'UTF-8');
    if ($text !== '' && in_array($lower, ['لغو', 'انصراف', 'cancel', '/cancel'], true)) {
        kyc_cancel($chat, $uid);
        return;
    }

    /* هر چه کاربر فرستاده (متن یا عکس) از چت خصوصی پاک می‌شود؛
       مقدار اول در استیت ذخیره شده است. */
    kyc_forget($chat, $userMsgId, $data);
    unset($data['prompt_msg'], $data['ack_msg']);

    switch ($state['state']) {
        case 'kyc_card':
            $digits = preg_replace('/\D+/', '', fa_digits($text)) ?? '';
            if (!preg_match('/^\d{16}$/', $digits)) {
                kyc_prompt($uid, 'kyc_card', $data, "❌ شمارهٔ کارت باید ۱۶ رقم باشد.\n\n"
                    . 'دوباره بفرستید — مثلاً:' . "\n" . '<code>6037000000000000</code>');
                return;
            }
            if (!kyc_card_valid($digits)) {
                kyc_prompt($uid, 'kyc_card', $data, "❌ این شمارهٔ کارت معتبر نیست "
                    . "(رقم کنترل اشتباه است).\n\n"
                    . 'شماره را از روی کارتت دوباره بخوان و بفرستید.');
                return;
            }
            $existing = kyc_card_find($uid, $digits);
            State::clear($uid);
            if ($existing !== null) {
                Tg::send($chat, '✅ این کارت قبلاً ثبت شده بود: <code>'
                    . e(kyc_card_mask($digits)) . '</code>');
                screen_kyc_cards($chat, null, $uid);
                return;
            }
            $cardId = DB::exec('INSERT INTO kyc_cards(tg_id, card_number, bank, status, '
                . 'created_at) VALUES(?,?,?,?,?)',
                [$uid, $digits, kyc_card_bank($digits), 'pending', now_ts()]);
            Tg::send($chat, "✅ کارت ثبت شد\n\n"
                . 'شماره: <code>' . e(kyc_card_mask($digits)) . "</code>\n"
                . 'بانک: ' . kyc_card_bank($digits) . "\n\n"
                . 'برای اینکه از این کارت بشود واریز کرد، باید آن را احراز کنید.',
                [[btn('📸 احراز کارت ' . kyc_card_mask($digits), 'kyc:cardv:' . $cardId,
                    null, 'success')],
                 [btn('➕ افزودن کارت دیگر', 'kyc:add', null, 'primary')],
                 [btn('🔙 بازگشت', 'kyc:cards', null, 'danger')]]);
            return;

        case 'kyc_card_terms':
            State::set($uid, 'kyc_card_terms', $data);
            screen_kyc_terms($chat, null, $uid, 1, $cardId);
            return;

        case 'kyc_photo_1':
            $photo = kyc_photo_id($message);
            if ($photo === '') {
                kyc_prompt($uid, 'kyc_photo_1', $data,
                    '📷 لطفاً <b>عکس</b> کارت را بفرستید (نه متن).');
                return;
            }
            $card = kyc_card_get($cardId);
            if ($card === null) {
                State::clear($uid);
                Tg::send($chat, 'کارت پیدا نشد. از «💳 کارت‌های من» دوباره شروع کنید.',
                    [[btn('💳 کارت‌های من', 'kyc:cards', null, 'danger')]]);
                return;
            }
            kyc_submit_request($uid, 1, $photo, ['card' => $card['card_number']], $cardId);
            return;

        case 'kyc_l2_name':
            if (!kyc_valid_persian_name($text)) {
                kyc_prompt($uid, 'kyc_l2_name', $data,
                    '❌ نام را به فارسی و درست بنویسید (۲ تا ۳۰ حرف).');
                return;
            }
            $data = kyc_ack($uid, $data, '✅ دریافت شد');
            kyc_prompt($uid, 'kyc_l2_family', ['name' => $text] + $data,
                "🧾 <b>نام خانوادگی:</b>\n\n" . 'نام خانوادگیت را به فارسی بنویسید.');
            return;

        case 'kyc_l2_family':
            if (!kyc_valid_persian_name($text)) {
                kyc_prompt($uid, 'kyc_l2_family', $data,
                    '❌ نام خانوادگی را به فارسی و درست بنویسید (۲ تا ۳۰ حرف).');
                return;
            }
            $data = kyc_ack($uid, $data, '✅ دریافت شد');
            kyc_prompt($uid, 'kyc_l2_ncode', ['family' => $text] + $data,
                "🔢 <b>کد ملی:</b>\n\n"
                . 'کد ملی ۱۰ رقمی‌ات را بفرستید. کد ملی باید مال خودتان باشد و با کارتت '
                . 'یکی باشد.');
            return;

        case 'kyc_l2_ncode':
            if (!kyc_national_code_ok($text)) {
                kyc_prompt($uid, 'kyc_l2_ncode', $data, "❌ کد ملی معتبر نیست.\n\n"
                    . 'باید ۱۰ رقم باشد و رقم کنترلی درستی داشته باشد. دوباره بفرستید.');
                return;
            }
            $data = kyc_ack($uid, $data, '✅ دریافت شد');
            kyc_prompt($uid, 'kyc_l2_birth', ['ncode' => preg_replace('/\D+/', '',
                fa_digits($text)) ?? ''] + $data,
                "📅 <b>تاریخ تولد:</b>\n\n" . 'مثال: <code>1370/05/03</code>');
            return;

        case 'kyc_l2_birth':
            if (!kyc_birth_ok($text)) {
                kyc_prompt($uid, 'kyc_l2_birth', $data, '❌ تاریخ تولد معتبر نیست. '
                    . 'با این شکل بفرستید: <code>1370/05/03</code>');
                return;
            }
            $data = kyc_ack($uid, $data, '✅ دریافت شد');
            $data['birth'] = str_replace(['-', '.'],
                '/', preg_replace('/\s+/', '', fa_digits($text)) ?? '');
            kyc_ask_phone($uid, $cardId, $data);
            return;

        case 'kyc_l2_phone':
            $phone = '';
            $viaContact = false;
            if (isset($message['contact']['phone_number'])) {
                $contactUid = (int) ($message['contact']['user_id'] ?? 0);
                if ($contactUid !== 0 && $contactUid !== $uid) {
                    kyc_prompt($uid, 'kyc_l2_phone', $data, '❌ این شماره مال حساب خودتان '
                        . 'نیست. شمارهٔ خودتان را بفرستید.');
                    return;
                }
                $phone = kyc_phone_clean((string) $message['contact']['phone_number']);
                $viaContact = $phone !== '';
            } elseif ($text !== '') {
                $phone = kyc_phone_clean($text);
            }
            if ($phone === '') {
                kyc_prompt($uid, 'kyc_l2_phone', $data, '❌ شمارهٔ موبایل معتبر نیست. '
                    . 'باید با ۰۹ شروع شود و ۱۱ رقم باشد.');
                return;
            }
            DB::exec('UPDATE users SET kyc_phone=?, phone=? WHERE tg_id=?',
                [$phone, $phone, $uid]);
            kyc_hide_reply_keyboard($uid, '✅ شماره‌ات ثبت شد' . ($viaContact
                ? "\n" . 'تأیید با کانتکت تلگرام ✅' : ''));
            kyc_send_banner($uid, 2, $cardId, '', ['phone' => $phone,
                'phone_contact' => $viaContact ? 1 : 0] + $data);
            return;

        case 'kyc_l2_photo':
            $photo = kyc_photo_id($message);
            if ($photo === '') {
                kyc_prompt($uid, 'kyc_l2_photo', $data,
                    '📷 لطفاً <b>عکس</b> کارت ملی و کارت بانکی را بفرستید.');
                return;
            }
            kyc_submit_request($uid, 2, $photo, [
                'name' => (string) ($data['name'] ?? ''),
                'family' => (string) ($data['family'] ?? ''),
                'ncode' => (string) ($data['ncode'] ?? ''),
                'birth' => (string) ($data['birth'] ?? ''),
                'phone' => (string) ($data['phone'] ?? ''),
                'phone_contact' => (int) ($data['phone_contact'] ?? 0),
            ], $cardId);
            return;

        case 'kyc_reason':
            State::clear($uid);
            if ($text === '') {
                Tg::send($chat, '❌ دلیل رد را بنویسید.');
                return;
            }
            [$ok, $note] = kyc_admin_review((int) ($data['req_id'] ?? 0), false, $uid, $text);
            Tg::send($chat, ($ok ? '✅ ' : '❌ ') . e($note),
                [[btn('🪪 احراز هویت', 'ad:setg:kyc', null, 'success')]]);
            return;

        case 'kyc_banner_admin':
            $photo = kyc_photo_id($message);
            State::clear($uid);
            if ($photo === '') {
                Tg::send($chat, '❌ عکس نفرستادی. دوباره از «🪪 احراز هویت» امتحان کنید.',
                    [[btn('🪪 احراز هویت', 'ad:setg:kyc', null, 'danger')]]);
                return;
            }
            set_put('kyc_banner_file', $photo);
            Tg::send($chat, '✅ عکس نمونه ذخیره شد.', [[btn('« احراز هویت',
                'ad:setg:kyc', null, 'success')]]);
            return;
    }
    State::clear($uid);
    Tg::send($chat, 'از دکمه‌های روی پیام استفاده کنید یا «لغو» را بزنید.',
        [[btn('🪪 وضعیت احراز هویت', 'kyc:home', null, 'primary')]]);
}

/* ── ۸) دکمه‌های KYC ─────────────────────────────────────────────────────── */

function kyc_callback(int $uid, int|string $chat, int $messageId, array $parts): void
{
    $action = (string) ($parts[1] ?? '');
    $arg = (int) ($parts[2] ?? 0);
    $arg2 = (int) ($parts[3] ?? 0);

    if (in_array($action, ['ok', 'no', 'pending', 'banner', 'resend'], true)
        && !is_admin($uid) && !is_owner($uid)) {
        Tg::send($chat, '⛔️ این بخش فقط برای مدیر است.');
        return;
    }

    switch ($action) {
        case 'home':
            screen_kyc($chat, $messageId, $uid);
            return;

        case 'cards':
            screen_kyc_cards($chat, $messageId, $uid);
            return;

        case 'add':
            kyc_ask_card($chat, $uid);
            return;

        case 'cancel':
            kyc_cancel($chat, $uid);
            return;

        case 'up':
            kyc_upgrade($chat, $messageId, $uid, $arg);
            return;

        case 'cardv':
            $card = kyc_card_get($arg);
            if ($card === null || (int) $card['tg_id'] !== $uid) {
                Tg::send($chat, 'این کارت پیدا نشد.',
                    [[btn('💳 کارت‌های من', 'kyc:cards', null, 'danger')]]);
                return;
            }
            if ($card['status'] === 'verified') {
                Tg::send($chat, '✅ این کارت قبلاً احراز شده است.',
                    [[btn('💳 کارت‌های من', 'kyc:cards', null, 'success')]]);
                return;
            }
            State::set($uid, 'kyc_card_terms', ['card_id' => $arg]);
            screen_kyc_terms($chat, $messageId, $uid, 1, $arg);
            return;

        case 'accept':
            $level = max(1, min(KYC_MAX_LEVEL, $arg));
            if ($level === 1) {
                $card = kyc_card_get($arg2);
                if ($card === null || (int) $card['tg_id'] !== $uid) {
                    Tg::send($chat, 'کارت پیدا نشد.',
                        [[btn('💳 کارت‌های من', 'kyc:cards', null, 'danger')]]);
                    return;
                }
                kyc_send_banner($uid, 1, $arg2,
                    kyc_card_mask((string) $card['card_number']));
                return;
            }
            kyc_l2_start($uid, $chat);
            return;

        case 'ok':
            [$ok, $note] = kyc_admin_review($arg, true, $uid);
            Tg::send($chat, ($ok ? '✅ ' : '❌ ') . e($note),
                [[btn('🪪 احراز هویت', 'ad:setg:kyc', null, 'success')]]);
            return;

        case 'no':
            $req = DB::one('SELECT * FROM kyc_requests WHERE id=?', [$arg]);
            if ($req === null || $req['status'] !== 'pending') {
                Tg::send($chat, '❌ این درخواست پیدا نشد یا قبلاً بررسی شده.',
                    [[btn('🪪 احراز هویت', 'ad:setg:kyc', null, 'danger')]]);
                return;
            }
            State::set($uid, 'kyc_reason', ['req_id' => $arg]);
            Tg::send($chat, '📝 <b>دلیل رد درخواست #' . $arg . '</b>' . "\n\n"
                . 'دلیل را بنویس؛ همین متن برای کاربر فرستاده می‌شود.',
                [[btn('🔙 بازگشت', 'ad:setg:kyc', null, 'danger')]]);
            return;

        case 'pending':
            screen_kyc_pending($chat, $messageId);
            return;

        case 'resend':
            kyc_post_admin_card($arg);
            Tg::send($chat, '🔁 کارت درخواست #' . $arg . ' دوباره فرستاده شد.');
            return;

        case 'topics':
            kyc_topics_startup();
            [$okTopics, $noteTopics] = kyc_topics_build();
            Tg::send($chat, ($okTopics ? '✅ ' : '⚠️ ') . e($noteTopics),
                [[btn('« احراز هویت', 'ad:setg:kyc', null, 'success')]]);
            return;

        case 'banner':
            State::set($uid, 'kyc_banner_admin', []);
            Tg::send($chat, '🖼 عکس نمونهٔ کارت (همان بنر مقایسه‌ای) را بفرستید تا '
                . 'در ربات استفاده شود.', [kyc_cancel_btn()]);
            return;
    }
    screen_kyc($chat, $messageId, $uid);
}

/** شروع ارتقا به سطح بعدی */
function kyc_upgrade(int|string $chat, ?int $messageId, int $uid, int $level): void
{
    $level = max(1, min(KYC_MAX_LEVEL, $level));
    $current = kyc_level($uid);
    if ($level > 3) {
        Tg::show($chat, $messageId, 'این سطح هنوز فعال نشده است.',
            [[btn('🔙 بازگشت', 'kyc:home', null, 'danger')]]);
        return;
    }
    if ($level === 1) {
        $cards = kyc_cards($uid);
        if (!$cards) {
            State::set($uid, 'kyc_card', []);
            Tg::show($chat, $messageId, "➕ <b>افزودن کارت</b>\n\n"
                . 'برای احراز سطح ۱ اول باید کارت بانکی‌ات را ثبت کنید.' . "\n\n"
                . 'شمارهٔ ۱۶ رقمی کارتی که می‌خواهید با آن واریز کنید را بفرستید.'
                . "\n\n" . 'کارت باید به نام خودتان باشد.', [kyc_cancel_btn()]);
            return;
        }
        screen_kyc_cards($chat, $messageId, $uid);
        return;
    }
    if ($current < $level - 1) {
        Tg::show($chat, $messageId, '⛔️ برای ' . KYC_LEVEL_TITLES[$level]
            . ' باید اول ' . KYC_LEVEL_TITLES[$level - 1] . ' تأیید شده باشد.',
            [[btn('🪪 وضعیت احراز هویت', 'kyc:home', null, 'danger')]]);
        return;
    }
    if (kyc_pending_request($uid) !== null) {
        Tg::show($chat, $messageId, '⏳ یک درخواست در حال بررسی دارید. تا نتیجه نیاید '
            . 'درخواست تازه ثبت نمی‌شود.',
            [[btn('🔙 بازگشت', 'kyc:home', null, 'danger')]]);
        return;
    }
    screen_kyc_terms($chat, $messageId, $uid, $level, 0);
}

/** فهرست درخواست‌های در انتظار (مدیر) */
function screen_kyc_pending(int|string $chat, ?int $messageId): void
{
    $rows = DB::all("SELECT * FROM kyc_requests WHERE status='pending' ORDER BY id LIMIT 10");
    $text = "🪪 <b>درخواست‌های احراز هویت</b>\n\n";
    if (!$rows) {
        $text .= 'درخواستی در انتظار نیست.';
        Tg::show($chat, $messageId, $text,
            [[btn('« احراز هویت', 'ad:setg:kyc', null, 'danger')]]);
        return;
    }
    $buttons = [];
    foreach ($rows as $row) {
        [$name] = receipt_who((int) $row['tg_id']);
        $text .= '· #' . (int) $row['id'] . ' · ' . e($name) . ' · '
            . KYC_LEVEL_TITLES[(int) $row['level']] . ' · '
            . fa_ts((int) $row['created_at']) . "\n";
        $buttons[] = [btn('#' . (int) $row['id'] . ' · ' . $name,
            'kyc:resend:' . (int) $row['id'])];
    }
    $buttons[] = [btn('« احراز هویت', 'ad:setg:kyc', null, 'danger')];
    Tg::show($chat, $messageId, $text, $buttons);
}

/* ── ۹) تایید/رد مدیر و گزارش دائمی تاپیک ───────────────────────────────── */

function kyc_admin_review(int $reqId, bool $approve, int $adminId, string $reason = ''): array
{
    if (!is_admin($adminId) && !is_owner($adminId)) {
        return [false, 'دسترسی ندارید'];
    }
    $req = DB::one('SELECT * FROM kyc_requests WHERE id=?', [$reqId]);
    if ($req === null) {
        return [false, 'درخواست پیدا نشد'];
    }
    if ((string) $req['status'] !== 'pending') {
        return [false, 'این درخواست قبلاً بررسی شده است'];
    }
    $uid = (int) $req['tg_id'];
    $level = max(1, min(KYC_MAX_LEVEL, (int) $req['level']));
    $cardId = (int) ($req['card_id'] ?? 0);
    $card = $cardId > 0 ? kyc_card_get($cardId) : null;
    $mask = $card !== null ? kyc_card_mask((string) $card['card_number']) : '';

    DB::exec('UPDATE kyc_requests SET status=?, reviewed_at=?, reviewed_by=?, reason=? '
        . 'WHERE id=?', [$approve ? 'approved' : 'rejected', now_ts(), $adminId,
        $approve ? '' : $reason, $reqId]);

    if (!$approve) {
        if ($cardId > 0) {
            DB::exec("UPDATE kyc_cards SET status='rejected' WHERE id=?", [$cardId]);
        }
        State::clear($uid);
        $body = "❌ <b>درخواست " . KYC_LEVEL_TITLES[$level] . " تأیید نشد</b>\n\n";
        if ($mask !== '') {
            $body .= '💳 کارت: <code>' . e($mask) . "</code>\n";
        }
        if (trim($reason) !== '') {
            $body .= '📝 دلیل: ' . e($reason) . "\n";
        }
        $body .= "\nمی‌توانید مدارک را درست کنید و از اول بفرستید.";
        Tg::send($uid, $body, [
            [btn('🔁 تلاش دوباره', 'kyc:home', null, 'success')],
            [btn('☎️ پشتیبانی', 'menu:support', null, 'primary')],
        ]);
        return [true, 'درخواست رد شد و به کاربر اطلاع داده شد'];
    }

    if ($cardId > 0) {
        DB::exec("UPDATE kyc_cards SET status='verified', level=?, verified_at=?, "
            . 'verified_by=? WHERE id=?', [$level, now_ts(), $adminId, $cardId]);
    }
    kyc_set_level($uid, $level);
    State::clear($uid);

    $head = $mask !== '' ? '✅ کارت <code>' . e($mask) . '</code> تأیید شد.'
        : '✅ مدارکت تأیید شد.';
    Tg::send($uid, $head . ' از این به بعد می‌توانید با آن واریز کنید.' . "\n"
        . '⬆️ سطحت هم رفت به ' . KYC_LEVEL_TITLES[$level] . ' – سقف واریزت بالا رفت.',
        [[btn('🪪 وضعیت احراز هویت', 'kyc:home', null, 'success')],
         [btn('« خانه', 'home', null, 'danger')]]);

    $userData = user_get($uid) ?? [];
    $payload = json_decode((string) ($req['payload'] ?? ''), true);
    $userData['request'] = $req;
    $userData['payload'] = is_array($payload) ? $payload : [];
    send_kyc_level_report($level, $userData, (string) $req['photo_id'],
        ['id' => $adminId]);

    return [true, 'تأیید شد — سطح ' . $level . ' ثبت و گزارش در تاپیک ارسال شد'];
}

/** کپشن گزارش دائمی هر سطح */
function kyc_report_caption(int $level, array $userData, array $adminInfo): string
{
    $level = max(1, min(KYC_MAX_LEVEL, $level));
    $req = is_array($userData['request'] ?? null) ? $userData['request'] : [];
    $payload = is_array($userData['payload'] ?? null) ? $userData['payload'] : [];
    $uid = (int) ($userData['tg_id'] ?? ($req['tg_id'] ?? 0));
    $uname = trim((string) ($userData['uname'] ?? ''));
    $adminId = (int) ($adminInfo['id'] ?? 0);
    $stamp = fa_ts(now_ts());

    $adminName = trim((string) (user_get($adminId)['name'] ?? ''));
    $adminLine = '👮 تاییدکننده: <code>' . $adminId . '</code>'
        . ($adminName !== '' ? ' · ' . e($adminName) : '');
    $link = $uname !== ''
        ? '<a href="https://t.me/' . e($uname) . '">@' . e($uname) . '</a>'
        : '<a href="tg://user?id=' . $uid . '">پیام به کاربر</a>';

    $text = '🪪 <b>' . KYC_LEVEL_TITLES[$level] . ' — تأیید شد</b>' . "\n"
        . SEP . "\n"
        . "<b>اطلاعات حساب</b>\n"
        . '🆔 شناسه عددی: <code>' . $uid . "</code>\n"
        . '👤 نام پروفایل: ' . e((string) ($userData['name'] ?? '—')) . "\n"
        . '🔗 یوزرنیم: ' . ($uname !== '' ? '@' . e($uname) : '—') . "\n"
        . '📎 لینک کاربر: ' . $link . "\n"
        . '📅 تاریخ ثبت‌نام: ' . fa_ts((int) ($userData['created_at'] ?? 0)) . "\n"
        . SEP . "\n";

    if ($level === 1) {
        $card = kyc_card_get((int) ($req['card_id'] ?? 0));
        $text .= "<b>کارت احرازشده</b>\n"
            . '💳 شماره کارت: <code>'
            . e((string) preg_replace('/\D+/', '', (string) ($card['card_number'] ?? '')))
            . "</code>\n"
            . '🏦 بانک: ' . e((string) ($card['bank'] ?? '—')) . "\n"
            . '📌 وضعیت: تأیید شد ✅' . "\n"
            . '🕒 زمان تأیید: ' . $stamp . "\n"
            . $adminLine;
        return $text;
    }

    $text .= "<b>اطلاعات هویتی</b>\n"
        . '📝 نام: ' . e((string) ($payload['name'] ?? '—')) . "\n"
        . '📝 نام خانوادگی: ' . e((string) ($payload['family'] ?? '—')) . "\n"
        . '🔢 کد ملی: <code>' . e((string) ($payload['ncode'] ?? '—')) . "</code>\n"
        . '📅 تاریخ تولد: ' . e((string) ($payload['birth'] ?? '—')) . "\n"
        . '📱 شماره تماس: ' . e((string) ($payload['phone'] ?? '—'))
        . ' <i>(' . ((int) ($payload['phone_contact'] ?? 0) === 1
            ? 'ارسال با کانتکت تلگرام ✅' : 'ورود دستی') . ")</i>\n\n";

    $cards = kyc_cards($uid);
    if ($cards) {
        $text .= "<b>کارت‌های ثبت‌شده</b>\n";
        foreach ($cards as $card) {
            $text .= '· <code>'
                . e((string) preg_replace('/\D+/', '', (string) $card['card_number']))
                . '</code>'
                . ' — ' . e((string) $card['bank'])
                . ' — ' . ($card['status'] === 'verified' ? 'احرازشده ✅' : 'احراز نشده') . "\n";
        }
    }
    $text .= "\n" . SEP . "\n"
        . '📌 وضعیت: ارتقا به سطح ' . $level . " با موفقیت انجام شد 🚀\n"
        . '🕒 زمان تأیید: ' . $stamp . "\n"
        . $adminLine;
    return $text;
}

/**
 * ارسال دائمی عکس مدرک + کپشن کامل به تاپیک همان سطح.
 * این پیام هیچ‌وقت حذف نمی‌شود (هیچ فراخوانی deleteMessage برای آن وجود ندارد).
 */
function send_kyc_level_report(int $level, array $userData, string $photoFileId,
                               array $adminInfo): int
{
    $chat = report_chat_id();
    if ($chat === '') {
        return 0;
    }
    /* همیشه تاپیک اختصاصی همان سطح؛ اگر ساخته نشد هرگز به General نمی‌رود
       و گزارش کامل برای مدیران در چت خصوصی می‌ماند */
    $thread = kyc_topic_ensure($level);
    $caption = kyc_report_caption($level, $userData, $adminInfo);
    if ($thread <= 0) {
        log_line('warning', 'kyc report has no topic', ['level' => $level]);
        foreach (receipt_targets() as $adminId) {
            $note = '⚠️ <b>تاپیک «' . KYC_TOPIC_TITLES[max(1, min(KYC_MAX_LEVEL, $level))]
                . '» ساخته نشده بود</b>؛ این گزارش در گروه ارسال نشد.' . "\n"
                . 'از ⚙️ تنظیمات → 🪪 احراز هویت → «🧵 ساخت تاپیک‌ها» درستش کنید.'
                . "\n\n";
            if ($photoFileId !== '') {
                Tg::photo($adminId, $photoFileId, $note . $caption);
            } else {
                Tg::send($adminId, $note . $caption);
            }
        }
        return 0;
    }
    if ($photoFileId !== '') {
        $msgId = Tg::photoThread($chat, $photoFileId, $caption, $thread);
        if ($msgId > 0) {
            return $msgId;
        }
        /* اگر تلگرام عکس را نپذیرفت، متن گزارش از دست نرود */
        $sent = Tg::sendThread($chat, $caption . "\n\n<i>عکس مدرک: "
            . e($photoFileId) . '</i>', $thread);
        return (int) $sent;
    }
    return (int) Tg::sendThread($chat, $caption, $thread);
}

function send_kyc_level_1_report(array $userData, string $photoFileId,
                                 array $adminInfo): int
{
    return send_kyc_level_report(1, $userData, $photoFileId, $adminInfo);
}

function send_kyc_level_2_report(array $userData, string $photoFileId,
                                 array $adminInfo): int
{
    return send_kyc_level_report(2, $userData, $photoFileId, $adminInfo);
}


/* ── گروه گزارشات: هر نوع گزارش تاپیک خودش را دارد ─────────────────────── */

const REPORT_KINDS = [
    'general' => '📢 گزارش‌های عمومی',
    'sales'   => '🛒 خریدها',
    'topup'   => '💰 شارژ کیف پول',
    'receipt' => '🧾 رسیدهای کارت‌به‌کارت',
    'usage'   => '⚡️ مصرف و صورت‌حساب',
    'panel'   => '📦 پنل‌ها و تعلیق',
    'users'   => '👥 کاربران',
    'error'   => '⚠️ خطاها',
    'daily'   => '📅 گزارش روزانه',
    'backup'  => '💾 بکاپ',
];

/** شناسهٔ گروه گزارشات (یا کانال قدیمی) */
function report_chat_id(): string
{
    $chat = trim(set_get('report_chat'));
    if ($chat === '') {
        $chat = trim(set_get('report_channel'));
    }
    return $chat;
}

function report_topics(): array
{
    $raw = trim(set_get('report_topics'));
    if ($raw === '') {
        return [];
    }
    $data = json_decode($raw, true);
    return is_array($data) ? $data : [];
}

function report_topic_id(string $kind): int
{
    if (!set_bool('report_topics_on', true)) {
        return 0;
    }
    $map = report_topics();
    return (int) ($map[$kind] ?? 0);
}

function report_ready(): bool
{
    return report_chat_id() !== '';
}

/**
 * آیا پنل مدیریت باید قفل باشد؟
 * تنظیم «report_force» (پیش‌فرض روشن) یعنی تا ثبت گروه گزارشات، مدیریت قفل است.
 */
function report_required(): bool
{
    return set_bool('report_force', true) && !report_ready();
}

/**
 * ارسال یک گزارش به تاپیک مربوط خودش (اگر تنظیم نشده باشد، هیچ کاری نمی‌کند).
 * هر گزارش فقط یک بار ارسال می‌شود: متن یکسان در بازهٔ کوتاه تکرار نمی‌شود.
 */
function post_report(string $text, string $kind = 'general'): void
{
    $chat = report_chat_id();
    if ($chat === '') {
        return;
    }
    $fingerprint = md5($kind . '|' . $text);
    $recent = json_decode((string) set_get('report_recent', '[]'), true);
    if (!is_array($recent)) {
        $recent = [];
    }
    if (($recent[$fingerprint] ?? 0) > now_ts() - 120) {
        log_line('debug', 'duplicate report skipped', ['kind' => $kind]);
        return;
    }
    $recent[$fingerprint] = now_ts();
    $recent = array_filter($recent, static fn($ts) => $ts > now_ts() - 600);
    set_put('report_recent', json_encode($recent));
    $thread = report_topic_id($kind) ?: report_topic_id('general');
    $sent = Tg::sendThread($chat, $text, $thread);
    if (!$sent && $thread > 0) {
        Tg::send($chat, $text);
    }
}

function report_status_text(): string
{
    $chat = report_chat_id();
    if ($chat === '') {
        return "🔴 <b>گروه گزارشات تنظیم نشده</b>\n\n"
            . 'بدون این گروه، هیچ گزارشی برایت ارسال نمی‌شود. ' . "\n"
            . 'ربات را در گروهی که «تاپیک‌ها» در آن فعال است عضو و <b>مدیر کل</b> کن، '
            . 'بعد شناسهٔ عددی گروه را همین‌جا بفرستید تا تاپیک هر گزارش ساخته شود.';
    }
    $map = report_topics();
    $lines = '🟢 <b>گروه گزارشات</b>: <code>' . e($chat) . '</code>' . "\n"
        . 'تاپیک‌ها: ' . fa_digits(count($map)) . ' از ' . fa_digits(count(REPORT_KINDS)) . "\n\n";
    foreach (REPORT_KINDS as $kind => $title) {
        $thread = (int) ($map[$kind] ?? 0);
        $lines .= ($thread > 0 ? '✅ ' : '▫️ ') . $title
            . ($thread > 0 ? ' <code>#' . $thread . '</code>' : ' — ساخته نشده') . "\n";
    }
    return $lines;
}

/** شناسهٔ گروه باید عددی و از نوع سوپرگروه باشد (با -100 شروع شود). */
function report_group_id_check(string $raw): array
{
    $chat = trim(preg_replace('/\s+/', '', $raw) ?? '');
    if ($chat === '') {
        return [false, 'شناسهٔ گروه خالی بود؛ عدد گروه را بفرستید.'];
    }
    if (preg_match('/^-?\d+$/', $chat) !== 1) {
        return [false, 'شناسه باید فقط عدد باشد (بدون فاصله و حرف). مثال: <code>-1003861909935</code>'];
    }
    if (!preg_match('/^-100\d{6,}$/', $chat)) {
        return [false, 'شناسهٔ سوپرگروه همیشه با <code>-100</code> شروع می‌شود. '
            . 'دستور <code>/getgroupid@myidbot</code> را داخل گروه بفرستید و همان عدد را کپی کنید.'];
    }
    return [true, ''];
}

/**
 * ثبت گروه گزارشات: اعتبارسنجی → پیام تست → ذخیره → ساخت تاپیک‌ها.
 * خروجی: [موفق, متن]
 */
function report_group_setup(string $raw): array
{
    [$idOk, $idWhy] = report_group_id_check($raw);
    if (!$idOk) {
        return [false, $idWhy];
    }
    $chat = trim(preg_replace('/\s+/', '', $raw) ?? '');
    $info = Tg::getChat($chat);
    if ($info === null) {
        return [false, "گروه پیدا نشد.\n\n"
            . '۱) ربات را عضو گروه کنید.' . "\n"
            . '۲) ربات را <b>مدیر کامل (Administrator)</b> کنید.' . "\n"
            . 'بعد شناسهٔ عددی گروه (مثل <code>-1003861909935</code>) را بفرستید.'];
    }
    $type = (string) ($info['type'] ?? '');
    if (!in_array($type, ['group', 'supergroup'], true)) {
        return [false, 'این شناسه مربوط به گروه نیست؛ شناسهٔ گروه گزارشات را بفرستید.'];
    }
    /* پیام تست، قبل از هر ذخیره‌ای: بدون آن معلوم نیست ربات واقعاً می‌تواند بنویسد */
    $tested = Tg::send($chat, '✅ <b>اتصال ربات به گروه گزارشات با موفقیت تایید شد.</b>' . "\n"
        . 'از این پس خریدها، رسیدها، شارژها، مصرف، تعلیق‌ها و خطاها همین‌جا ارسال می‌شوند.');
    if (!$tested) {
        return [false, "ربات نتوانست در گروه پیام بفرستد.\n\n"
            . 'ربات را عضو گروه کنید و دسترسی <b>مدیر کامل</b> (ارسال پیام) بدهید.'];
    }
    set_put('report_chat', $chat);
    if (trim(set_get('backup_chat')) === '') {
        set_put('backup_chat', $chat);
    }
    $title = (string) ($info['title'] ?? $chat);
    $note = '';
    if (empty($info['is_forum'])) {
        /* تاپیک پیشنهادی است، نه الزامی: بدون تاپیک همه‌چیز در یک جریان می‌رود */
        set_put('report_topics', '[]');
        $note = 'تاپیک‌ها (Topics) در این گروه فعال نیست؛ گزارش‌ها در جریان اصلی گروه '
            . 'ارسال می‌شوند. اگر می‌خواهید هر گزارش تاپیک جدا داشته باشد، از تنظیمات گروه '
            . 'حالت تاپیک را روشن کنید و دوباره شناسه را بفرستید.';
    } else {
        [$okTopics, $noteTopics] = report_topics_build();
        $note = $noteTopics;
        if (!$okTopics) {
            $note .= "\n" . 'گروه ثبت شد؛ تاپیک‌ها را بعداً با «🔁 ساخت تاپیک‌های باقی‌مانده» بسازید.';
        }
    }
    log_line('info', 'report group bound', ['chat' => $chat]);
    return [true, '✅ گروه گزارشات ثبت شد: <b>' . e($title) . '</b>'
        . "\n<code>" . e($chat) . "</code>\n\n" . $note];
}

/** ساخت تاپیک‌های گزارش که هنوز ساخته نشده‌اند. خروجی: [موفق, متن] */
function report_topics_build(): array
{
    $chat = report_chat_id();
    if ($chat === '') {
        return [false, 'اول گروه گزارشات را ثبت کنید.'];
    }
    $map = report_topics();
    $created = 0;
    $failed = 0;
    foreach (REPORT_KINDS as $kind => $title) {
        if ((int) ($map[$kind] ?? 0) > 0) {
            continue;
        }
        $thread = Tg::createTopic($chat, $title);
        if ($thread > 0) {
            $map[$kind] = $thread;
            $created++;
            Tg::sendThread($chat, 'این تاپیک مخصوص «' . $title . '» است.', $thread);
        } else {
            $failed++;
        }
    }
    set_put('report_topics', json_encode($map, JSON_UNESCAPED_UNICODE));
    if (!$map) {
        return [false, 'هیچ تاپیکی ساخته نشد؛ مطمئن شو ربات در گروه مدیر است.'];
    }
    $text = 'تاپیک‌های آماده: ' . fa_digits(count($map)) . ' عدد'
        . ($created > 0 ? ' · تازه ساخته شد: ' . fa_digits($created) : '')
        . ($failed > 0 ? ' · ناموفق: ' . fa_digits($failed) : '');
    return [$failed === 0, $text];
}

/* ── بکاپ خودکار: هر ۲۴ ساعت، به گروه بکاپ، بدون ماندن روی سرور ────────── */

/** گرفتن یک عکس لحظه‌ای از دیتابیس. خروجی: [مسیر یا '', خطا] */
function backup_ext(): string
{
    $ext = preg_replace('/[^a-z0-9]/', '', mb_strtolower(set_get('backup_ext', 'panelbak'))) ?: 'panelbak';
    return $ext;
}

/**
 * بررسی معتبر بودن فایل بکاپ: باید پسوند خودِ ربات را داشته باشد و
 * محتوایش gzip (یا مستقیم sqlite) باشد.
 * خروجی: [ok, پیام, مسیر فایل sqlite موقت]
 */
function backup_unpack(string $path): array
{
    if (!is_file($path)) {
        return [false, 'فایل پیدا نشد: ' . $path, ''];
    }
    $ext = mb_strtolower(pathinfo($path, PATHINFO_EXTENSION));
    /* فرمت استاندارد و تاریخ‌دار: sibil-backup-YYYY-MM-DD.sqlite3
       پسوند قدیمی (.panelbak) هم برای بکاپ‌های قبلی پذیرفته می‌شود. */
    if (!in_array($ext, [backup_ext(), 'sqlite3', 'sqlite', 'db'], true)) {
        return [false, 'این فایل بکاپ این ربات نیست. فایل '
            . '<code>sibil-backup-YYYY-MM-DD.sqlite3</code> یا .' . backup_ext()
            . ' را بفرستید (پسوند فایل: ' . ($ext !== '' ? $ext : '—') . ').', ''];
    }
    $payload = @file_get_contents($path);
    if ($payload === false || $payload === '') {
        return [false, 'فایل بکاپ خالی است.', ''];
    }
    $data = $payload;
    if (str_starts_with($payload, "\x1f\x8b")) {
        $data = function_exists('gzdecode') ? @gzdecode($payload) : false;
        if ($data === false) {
            return [false, 'فایل بکاپ سالم نیست (باز کردن gzip انجام نشد).', ''];
        }
    }
    if (!str_starts_with($data, "SQLite format 3")) {
        return [false, 'محتوای فایل بکاپ، دیتابیس این ربات نیست.', ''];
    }
    $temp = sys_get_temp_dir() . '/panel-restore-' . bin2hex(random_bytes(4)) . '.sqlite3';
    if (@file_put_contents($temp, $data) === false) {
        return [false, 'نوشتن فایل موقت انجام نشد.', ''];
    }
    return [true, '', $temp];
}

/**
 * سلامت دیتابیس برای کپشن بکاپ: integrity_check + شمارش جدول‌های مهم.
 * خروجی: ['ok' => bool, 'integrity' => string, 'counts' => array]
 */
function backup_health(): array
{
    $integrity = 'unknown';
    try {
        $integrity = (string) DB::val('PRAGMA integrity_check', [], 'unknown');
    } catch (Throwable $ex) {
        $integrity = 'error: ' . $ex->getMessage();
    }
    $counts = [];
    foreach (['users', 'panels', 'orders', 'payments', 'receipts', 'wallet_tx',
              'kyc_cards', 'kyc_requests'] as $table) {
        try {
            $counts[$table] = (int) DB::val('SELECT COUNT(*) FROM ' . $table, [], 0);
        } catch (Throwable $ex) {
            $counts[$table] = -1;
        }
    }
    return ['ok' => $integrity === 'ok', 'integrity' => $integrity, 'counts' => $counts];
}

function backup_snapshot(): array
{
    $source = db_path();
    if (!is_file($source)) {
        return ['', 'فایل دیتابیس پیدا نشد.'];
    }
    $raw = sys_get_temp_dir() . '/panel-raw-' . date('Ymd-Hi') . '-'
        . bin2hex(random_bytes(3)) . '.sqlite3';
    try {
        DB::pdo()->exec("VACUUM INTO " . DB::pdo()->quote($raw));
    } catch (Throwable $ex) {
        if (!@copy($source, $raw)) {
            return ['', 'کپی دیتابیس انجام نشد: ' . $ex->getMessage()];
        }
    }
    if (!is_file($raw)) {
        return ['', 'ساخت فایل بکاپ انجام نشد.'];
    }
    /* فایل استاندارد و بازشو با sqlite3: sibil-backup-YYYY-MM-DD.sqlite3 */
    $target = backup_temp_path();
    if (!@copy($raw, $target)) {
        @unlink($raw);
        return ['', 'ساخت فایل بکاپ انجام نشد.'];
    }
    @unlink($raw);
    @chmod($target, 0600);
    return [$target, ''];
}

/** ارسال بکاپ به گروه و پاک کردن فایل از سرور */
function backup_send(string $caption = '', bool $force = false): array
{
    $last = (int) set_get('last_backup_at', '0');
    if (!$force && $last > 0 && (now_ts() - $last) < 300) {
        return [true, 'همین چند لحظه پیش یک بکاپ ارسال شد؛ برای جلوگیری از تکرار انجام نشد.'];
    }
    [$path, $error] = backup_snapshot();
    if ($path === '') {
        return [false, $error];
    }
    $size = (int) filesize($path);
    $chat = trim(set_get('backup_chat'));
    if ($chat === '') {
        $chat = report_chat_id();
    }
    if ($chat === '') {
        @unlink($path);
        return [false, 'گروه بکاپ تنظیم نشده؛ فایل روی سرور نگه داشته نشد و پاک شد.'];
    }
    $thread = report_topic_id('backup');
    $health = backup_health();
    $text = ($caption !== '' ? $caption . "\n" : '')
        . '💾 <b>بکاپ ' . e(brand()) . '</b>' . "\n" . SEP . "\n"
        . '📅 ' . fa_date_only(now_ts()) . ' → ⏰ ' . fa_time_only(now_ts()) . "\n"
        . '📦 حجم: ' . fa_digits(round($size / 1024, 1)) . ' کیلوبایت' . "\n"
        . '🩺 سلامت دیتابیس: ' . ($health['ok'] ? 'سالم ✅' : 'هشدار ⚠️ ('
            . e($health['integrity']) . ')') . "\n"
        . '👥 کاربر: ' . fa_digits($health['counts']['users'] ?? 0)
        . ' · 📦 پنل: ' . fa_digits($health['counts']['panels'] ?? 0)
        . ' · 🧾 رسید: ' . fa_digits($health['counts']['receipts'] ?? 0) . "\n"
        . '🪪 احراز: ' . fa_digits($health['counts']['kyc_cards'] ?? 0) . "\n"
        . SEP . "\n"
        . '<i>فقط داده است، بدون سورس. برای بازگردانی کافی است همین فایل را '
        . 'کنار سورس ربات بگذار و اجرا کن؛ همهٔ حساب‌ها، موجودی‌ها و پنل‌ها '
        . 'برمی‌گردند.</i>';
    $okSend = Tg::document($chat, $path, $text, $thread);
    @unlink($path);
    /* فایل تنظیمات هم کنار بکاپ می‌رود تا بازگردانی، کامل باشد */
    if ($okSend && backup_with_env()) {
        $envFile = env_file_path();
        if (is_file($envFile)) {
            $envCopy = backup_env_temp_path();
            if (@copy($envFile, $envCopy)) {
                Tg::document($chat, $envCopy,
                    '⚙️ <b>فایل تنظیمات (.env)</b>' . "\n" . SEP . "\n"
                    . 'این فایل کلید ربات و تنظیمات اتصال است؛ همراه بکاپ '
                    . date('Y-m-d') . " نگهش دارید.\n"
                    . '<i>دسترسی: فقط اعضای همین گروه. برای خاموش‌کردن این فایل: '
                    . 'تنظیمات → بکاپ → ارسال فایل تنظیمات.</i>', $thread);
                @unlink($envCopy);
            }
        }
    }
    if ($okSend) {
        set_put('last_backup_at', (string) now_ts());
        return [true, '✅ بکاپ ارسال شد (' . fa_digits(round($size / 1024, 1)) . ' کیلوبایت).'];
    }
    return [false, 'ارسال بکاپ به گروه انجام نشد؛ ربات باید در گروه مدیر باشد.'];
}

/** اگر زمانش رسیده باشد، بکاپ خودکار می‌گیرد */
/**
 * بکاپ خودکار: هر روز رأس ساعت ۰۰:۰۰ به وقت ایران یک‌بار.
 * اگر ربات ساعت ۰۰:۰۰ روشن نبود، اولین باری که بیدار شد همان روز جبران می‌کند
 * (چون مبنا «شروع امروز» است، نه فاصلهٔ ۲۴ ساعته از آخرین بکاپ).
 */
function backup_due(): bool
{
    if (!set_bool('backup_on', true)) {
        return false;
    }
    $hour = max(0, min(23, set_int('backup_at_hour', 0)));
    $nowLocal = (int) (now_ts() + IRAN_OFFSET);
    $todayAnchor = $nowLocal - ($nowLocal % DAY) - (int) IRAN_OFFSET + $hour * 3600;
    $last = (int) set_get('last_backup_at', '0');
    if ($last >= $todayAnchor) {
        return false;
    }
    /* ساعت بیدارباش هم رسیده باشد */
    return now_ts() >= $todayAnchor;
}

function maybe_backup(): void
{
    if (!backup_due()) {
        return;
    }
    $hour = max(0, min(23, set_int('backup_at_hour', 0)));
    [$ok, $note] = backup_send('بکاپ خودکار روزانه — ساعت '
        . sprintf('%02d:00', $hour) . ' به وقت ایران');
    log_line($ok ? 'info' : 'warning', 'backup: ' . $note);
    if (!$ok) {
        set_put('last_backup_at', (string) now_ts());
        post_report('⚠️ <b>بکاپ خودکار انجام نشد</b>' . "\n" . e($note), 'error');
    }
}

/*
   9c) BACKUP & RESTORE — فایل استاندارد تاریخ‌دار + بازگردانی تضمینی

   قانون‌ها:
   ۱) نام فایل استاندارد است: sibil-backup-YYYY-MM-DD.sqlite3
      (همان فایلی که با ابزار sqlite3 هم باز می‌شود)
   ۲) کنار دیتابیس، فایل تنظیمات .env هم فرستاده می‌شود (قابل خاموش‌کردن)
   ۳) بازگردانی هم از CLI («sibil restore <file>») و هم از خود ربات انجام می‌شود
   ۴) بازگردانی هرگز جدول‌ها را نصفه نمی‌گذارد: اعتبارسنجی → نسخهٔ ایمن از
      دادهٔ فعلی → جایگزینی اتمی → مایگریشن؛ اگر مایگریشن خطا بدهد، همان
      نسخهٔ ایمن برمی‌گردد و هیچ داده‌ای گم نمی‌شود.
*/

/** تاریخ فایل بکاپ (YYYY-MM-DD) به وقت ایران */
function backup_stamp(): string
{
    return date('Y-m-d', now_ts() + (int) IRAN_OFFSET);
}

/** مسیر موقت یک بکاپ تازه با نام استاندارد و تاریخ‌دار */
function backup_temp_path(): string
{
    return sys_get_temp_dir() . '/sibil-backup-' . backup_stamp() . '.sqlite3';
}

/** مسیر فایل .env کنار بکاپ */
function backup_env_temp_path(): string
{
    return sys_get_temp_dir() . '/sibil-env-' . backup_stamp() . '.txt';
}

/** آیا .env هم داخل بکاپ برود؟ (پیش‌فرض: بله) */
function backup_with_env(): bool
{
    return set_bool('backup_env', true);
}

/**
 * اعتبارسنجی یک فایل بکاپ، بدون دست‌زدن به دادهٔ فعلی.
 * فایل gzip قدیمی (.panelbak) همان‌جا باز می‌شود.
 * خروجی: [ok, متن, مسیر sqlite قابل استفاده]
 */
function backup_validate(string $path): array
{
    if (!is_file($path)) {
        return [false, 'فایل بکاپ پیدا نشد.', ''];
    }
    $head = (string) @file_get_contents($path, false, null, 0, 16);
    if (!str_starts_with($head, 'SQLite format 3')) {
        $raw = (string) @file_get_contents($path);
        if (str_starts_with($raw, "\x1f\x8b")) {
            $unpacked = @gzdecode($raw);
            if ($unpacked === false || !str_starts_with($unpacked, 'SQLite format 3')) {
                return [false, 'فایل بکاپ سالم نیست (gzip خراب است).', ''];
            }
            $tmp = sys_get_temp_dir() . '/sibil-restore-'
                . bin2hex(random_bytes(4)) . '.sqlite3';
            if (@file_put_contents($tmp, $unpacked) === false) {
                return [false, 'نوشتن فایل موقت انجام نشد.', ''];
            }
            $path = $tmp;
        } else {
            return [false, 'این فایل، دیتابیس این ربات نیست.', ''];
        }
    }
    try {
        $probe = new PDO('sqlite:' . $path, null, null,
            [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 5]);
        $integrity = (string) $probe->query('PRAGMA integrity_check')->fetchColumn();
        if ($integrity !== 'ok') {
            return [false, 'دیتابیس داخل بکاپ سالم نیست (integrity: ' . $integrity . ').', ''];
        }
        $users = (int) $probe->query('SELECT COUNT(*) FROM users')->fetchColumn();
        $panels = (int) $probe->query('SELECT COUNT(*) FROM panels')->fetchColumn();
        $probe = null;
    } catch (Throwable $ex) {
        return [false, 'دیتابیس داخل بکاپ خوانده نشد: ' . $ex->getMessage(), ''];
    }
    return [true, '👥 ' . fa_digits($users) . ' کاربر · 📦 ' . fa_digits($panels)
        . ' پنل · 🩺 سلامت: ok', $path];
}

/**
 * بازگردانی واقعی: نسخهٔ ایمن از دادهٔ فعلی → جایگزینی اتمی → مایگریشن.
 * خروجی: [موفق, متن]
 */
function backup_restore_apply(string $sqlitePath): array
{
    [$okFile, $whyFile, $ready] = backup_validate($sqlitePath);
    if (!$okFile) {
        return [false, $whyFile];
    }
    $target = db_path();
    $safety = '';
    if (is_file($target)) {
        $safety = $target . '.before-restore-' . date('Ymd-His');
        if (!@copy($target, $safety)) {
            return [false, 'نوشتن نسخهٔ ایمن از دادهٔ فعلی انجام نشد؛ بازگردانی متوقف شد.'];
        }
    }
    /* هر سه فایل (اصلی + WAL + SHM) پاک می‌شوند تا دادهٔ قبلی برنگردد */
    DB::close();
    foreach (['', '-wal', '-shm'] as $suffix) {
        if ($suffix !== '' && is_file($target . $suffix)) {
            @unlink($target . $suffix);
        }
    }
    if (!@copy($ready, $target)) {
        DB::close();
        if ($safety !== '' && is_file($safety)) {
            @copy($safety, $target);
        }
        return [false, 'جایگزینی دیتابیس انجام نشد؛ دادهٔ قبلی بازگشت.'];
    }
    @chmod($target, 0640);
    DB::close();
    try {
        db_bootstrap();
        settings_bootstrap();
    } catch (Throwable $ex) {
        DB::close();
        if ($safety !== '' && is_file($safety)) {
            @copy($safety, $target);
            DB::close();
            try {
                db_bootstrap();
            } catch (Throwable $ignored) {
            }
        }
        return [false, 'مایگریشن بکاپ خطا داد؛ دادهٔ قبلی بازگشت: ' . $ex->getMessage()];
    }
    $health = backup_health();
    $users = (int) DB::val('SELECT COUNT(*) FROM users', [], 0);
    post_report('♻️ <b>بازگردانی بکاپ انجام شد</b>' . "\n" . SEP . "\n"
        . '👥 کاربر: ' . fa_digits($users) . "\n"
        . '🩺 سلامت دیتابیس: ' . ($health['ok'] ? 'سالم ✅' : 'هشدار ⚠️'), 'backup');
    return [true, '✅ بازگردانی انجام شد — ' . fa_digits($users) . ' کاربر و همهٔ '
        . 'موجودی‌ها، سفارش‌ها و پنل‌ها برگشتند.'];
}

/** مسیر فایل نشانهٔ «بازگردانی در انتظار» */
function backup_restore_flag(): string
{
    return panel_home() . '/.restore-request';
}

/** فایل بکاپِ ارسال‌شده به ربات را ذخیره و برای تأیید آماده می‌کند */
function backup_restore_stage(string $fileId, string $fileName = ''): array
{
    [$path, $error] = Tg::download($fileId);
    if ($path === '') {
        return [false, 'دریافت فایل انجام نشد: ' . $error];
    }
    [$okFile, $note, $ready] = backup_validate($path);
    if (!$okFile) {
        @unlink($path);
        return [false, $note];
    }
    $keep = panel_home() . '/uploads';
    if (!is_dir($keep)) {
        @mkdir($keep, 0755, true);
    }
    $dest = $keep . '/restore-' . date('Ymd-His') . '.sqlite3';
    if (!@copy($ready, $dest)) {
        @unlink($path);
        return [false, 'ذخیرهٔ فایل بکاپ روی سرور انجام نشد.'];
    }
    @unlink($path);
    if ($ready !== $path && str_contains($ready, 'sibil-restore-')) {
        @unlink($ready);
    }
    set_put('restore_pending', $dest);
    set_put('restore_pending_name', $fileName !== '' ? $fileName : basename($dest));
    return [true, '📦 فایل بکاپ دریافت و بررسی شد.' . "\n" . $note];
}

/**
 * درخواست بازگردانی: ربات خروج می‌کند و سرویس دوباره بالا می‌آید؛
 * در استارتاپ بعدی، backup_restore_apply_pending() کار را تمام می‌کند.
 */
function backup_restore_request(): array
{
    $path = trim(set_get('restore_pending', ''));
    if ($path === '' || !is_file($path)) {
        return [false, 'فایل بکاپ در انتظار پیدا نشد؛ دوباره بفرستید.'];
    }
    if (@file_put_contents(backup_restore_flag(), $path) === false) {
        return [false, 'ثبت درخواست بازگردانی انجام نشد.'];
    }
    return [true, '♻️ بازگردانی شروع شد؛ ربات چند ثانیه قطع می‌شود و با دادهٔ بکاپ برمی‌گردد.'];
}

/** در استارتاپ: اگر درخواست بازگردانی هست، همان‌جا اعمال می‌شود */
function backup_restore_apply_pending(): void
{
    $flag = backup_restore_flag();
    if (!is_file($flag)) {
        return;
    }
    $path = trim((string) @file_get_contents($flag));
    @unlink($flag);
    set_put('restore_pending', '');
    if ($path === '' || !is_file($path)) {
        log_line('warning', 'restore pending but the file is gone');
        return;
    }
    [$ok, $note] = backup_restore_apply($path);
    @unlink($path);
    log_line($ok ? 'info' : 'error', 'restore: ' . $note);
    foreach (admin_ids() as $adminId) {
        Tg::send($adminId, ($ok ? '✅ ' : '⚠️ ') . $note);
    }
}
/* 13) Payments and delivery */

/** نام کاربری پنل: پیشوند محصول + پسوند تصادفی (سازگار با قوانین پاسارگارد) */
function random_username(string $prefix): string
{
    $clean = preg_replace('/[^a-zA-Z0-9_]/', '', $prefix) ?? '';
    $clean = mb_substr(trim($clean, '_'), 0, 14);
    $suffix = '';
    for ($i = 0; $i < 6; $i++) {
        $suffix .= chr(random_int(97, 122));
    }
    /* بدون پیشوند هم نام کاربری کاملاً تصادفی ساخته می‌شود */
    return $clean === '' ? $suffix : $clean . '_' . $suffix;
}

/**
 * رمز تصادفی با ساختار امن — حرف بزرگ و کوچک، رقم و نماد.
 * نمونه: 7P20g8Z!ot%k
 */
function random_password(int $length = 12): string
{
    $length = max(10, min(32, $length));
    $lower  = 'abcdefghijkmnpqrstuvwxyz';
    $upper  = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
    $digit  = '23456789';
    $symbol = '!@#$%^&*-_+?';
    $all    = $lower . $upper . $digit . $symbol;
    /* قوانین خود پنل پاسارگارد: حداقل ۱۲ کاراکتر، ۲ رقم، ۲ حرف بزرگ،
       ۲ حرف کوچک و ۱ کاراکتر ویژه — دقیقاً همین تعداد را تضمین می‌کنیم */
    $length = max(12, min(64, $length));
    $chars = [
        $digit[random_int(0, strlen($digit) - 1)],
        $digit[random_int(0, strlen($digit) - 1)],
        $upper[random_int(0, strlen($upper) - 1)],
        $upper[random_int(0, strlen($upper) - 1)],
        $lower[random_int(0, strlen($lower) - 1)],
        $lower[random_int(0, strlen($lower) - 1)],
        $symbol[random_int(0, strlen($symbol) - 1)],
    ];
    while (count($chars) < $length) {
        $chars[] = $all[random_int(0, strlen($all) - 1)];
    }
    shuffle($chars);
    $password = implode('', $chars);
    return str_contains($password, '"') ? str_replace('"', '*', $password) : $password;
}

/** رمز مناسب پنل که نام کاربری داخلش نباشد (پنل این را هم رد می‌کند) */
function panel_password_ok(string $password, string $username = ''): bool
{
    return strlen($password) >= 12
        && preg_match_all('/\d/', $password) >= 2
        && preg_match_all('/[A-Z]/', $password) >= 2
        && preg_match_all('/[a-z]/', $password) >= 2
        && preg_match('/[!@#$%^&*()\-_=+\[\]{}|;:,.<>?\/~`]/', $password) === 1
        && ($username === '' || !str_contains(mb_strtolower($password), mb_strtolower($username)));
}

/** رمز پنل: تا وقتی قوانین پنل را رعایت نکند دوباره ساخته می‌شود */
function panel_password(int $length, string $username): string
{
    for ($try = 0; $try < 20; $try++) {
        $candidate = random_password($length);
        if (panel_password_ok($candidate, $username)) {
            return $candidate;
        }
    }
    /* پشتیبان قطعی: ساخت دستی طبق قانون */
    return bin2hex(random_bytes(6)) . '!' . random_int(100, 999);
}

/** تحویل سفارش: ساخت ادمین روی پنل پاسارگارد و ثبت ردیف پنل. */
/** خطای پنل یعنی «این نام قبلاً هست»؟ */
function panel_error_is_duplicate(Throwable $ex): bool
{
    $status = $ex instanceof PanelError ? (int) $ex->status : 0;
    $msg = mb_strtolower($ex->getMessage());
    if (str_contains($msg, 'exist') || str_contains($msg, 'duplicate')
        || str_contains($msg, 'already') || str_contains($msg, 'تکراری')) {
        return true;
    }
    return in_array($status, [400, 409, 422], true)
        && (str_contains($msg, 'username') || str_contains($msg, 'admin'));
}

/** نام آزاد روی خود پنل (نه فقط دیتابیس ربات) */
function panel_free_username(PgPanel $client, int $length = 8): string
{
    for ($try = 0; $try < 6; $try++) {
        $candidate = random_panel_username($length);
        try {
            if ($client->admin_by_username($candidate) === null) {
                return $candidate;
            }
        } catch (Throwable $ex) {
            return $candidate;   // پنل جواب نداد؛ همان نام را امتحان می‌کنیم
        }
    }
    return random_panel_username($length + 2);
}

function deliver_panel_order(array $order): array
{
    $product = order_product($order);
    if ($product === null) {
        return [false, 'محصول این سفارش پیدا نشد.'];
    }
    $isTrial = (string) $order['kind'] === 'trial';
    $panelRow = null;
    if (!empty($product['panel_id'])) {
        $panelRow = DB::one('SELECT * FROM pg_panels WHERE id=? AND active=1', [(int) $product['panel_id']]);
    }
    if ($panelRow === null) {
        $panelRow = DB::one('SELECT * FROM pg_panels WHERE active=1 ORDER BY is_default DESC, id LIMIT 1');
    }
    if ($panelRow === null) {
        return [false, "هیچ پنل پاسارگارد فعالی وصل نیست.\n"
            . 'در «🔌 پنل‌ها → ➕ افزودن پنل» پنل را با کلید API وصل کن، '
            . 'بعد دوباره همین دکمه را بزنید.'];
    }
    if (trim((string) ($panelRow['api_key'] ?? '')) === '') {
        return [false, "کلید API این پنل ثبت نشده است.\n"
            . 'در «🔌 پنل‌ها» روی پنل بزنید و «🔑 تغییر کلید API» را انجام بدهید.'];
    }
    $payloadOrder = json_decode((string) ($order['payload'] ?? ''), true) ?: [];
    $unlimitedTrial = $isTrial && !empty($payloadOrder['trial_unlimited']);
    $dataCapGb = $unlimitedTrial ? 0.0
        : ($isTrial ? (float) ($payloadOrder['trial_gb'] ?? set_int('trial_gb', 1))
            : (float) $product['data_cap_gb']);
    $expireAt = $unlimitedTrial ? 0
        : ($isTrial
            ? time() + max(1, (int) ($payloadOrder['trial_hours'] ?? set_int('trial_hours', 24))) * 3600
            : time() + (int) $product['days'] * DAY);
    /* سقف کاربرانِ داخلِ پنل: برای تست از تنظیم مستقل trial_user_limit خوانده می‌شود
       (قبلاً اشتباهاً ۱ بود و ظرفیت پنل پاسارگاد را قفل می‌کرد) */
    $userCap = $unlimitedTrial ? 0
        : ($isTrial ? max(1, set_int('trial_user_limit', 10)) : (int) $product['max_users']);
    $roleId = (int) $product['role_id'];
    if ($roleId <= 0) {
        $roleId = auto_role_id($panelRow);
        if ($roleId > 0) {
            DB::exec('UPDATE products SET role_id=? WHERE id=?', [$roleId, (int) $product['id']]);
        }
    }
    if ($roleId <= 0) {
        return [false, 'این محصول هنوز نقش پنل ندارد.' . "\n"
            . 'در بخش محصول دکمهٔ «🎭 نقش پنل» را بزنید و یکی از نقش‌های خود پنل را انتخاب کنید.'];
    }
    $base = normalize_panel_url((string) $panelRow['url']);
    $client = new PgPanel($panelRow);
    $username = '';
    $created = [];
    $lastError = '';
    $wantedName = trim((string) ($payloadOrder['panel_username'] ?? ''));
    $finalName = '';
    $tries = $wantedName !== '' ? 5 : 4;
    $password = '';
    for ($attempt = 1; $attempt <= $tries; $attempt++) {
        if ($attempt === 1 && $wantedName !== '') {
            $username = $wantedName;
        } else {
            /* نام رندوم را قبل از ساخت روی خود پنل چک می‌کنیم */
            $username = panel_free_username($client, $attempt >= 3 ? 10 : 8);
        }
        /* رمز باید قوانین خود پنل را رعایت کند و نام کاربری داخلش نباشد */
        $password = panel_password(set_int('panel_pass_len', 12), $username);
        try {
            $created = $client->create_admin($username, $password, $roleId, [
                'users_limit' => $userCap,
                'data_limit'  => (int) round($dataCapGb * 1024 ** 3),
                'expire'      => $expireAt,
                'note'        => (string) $product['name'],
            ]);
            $lastError = '';
            $finalName = $username;
            break;
        } catch (Throwable $ex) {
            $lastError = $ex->getMessage();
            log_line('warning', 'create_admin failed (' . $username . '): ' . $lastError);
            /* 422 یعنی داده پذیرفته نشد (نام یا رمز). یک‌بار با نام و رمز تازه
               دوباره تلاش می‌کنیم؛ 401/403/500 دوباره‌تلاش بی‌فایده است. */
            $status = $ex instanceof PanelError ? (int) $ex->status : 0;
            $retryable = panel_error_is_duplicate($ex) || $status === 422;
            if (!$retryable) {
                break;
            }
        }
    }
    if ($lastError !== '') {
        $note = $lastError;
        if (str_contains($note, '401')) {
            $note .= "\nکلید API معتبر نیست یا باطل شده؛ کلید تازه بساز و از «🔑 تغییر کلید API» ثبت کنید.";
        }
        return [false, 'ساخت پنل روی سرور انجام نشد: ' . $note];
    }
    /* ⏱ ساعت‌های اول پیش‌پرداخت شده‌اند: کسر ساعتی فقط بعد از آن‌ها شروع می‌شود */
    $prepaidHours = $isTrial ? 0 : prepaid_hours();
    $billingStartAt = $prepaidHours > 0 ? now_ts() + $prepaidHours * 3600 : 0;
    /* اگر سفارش از مسیر عادی ساخته نشده باشد (پرداخت مستقیم/ادمین)، پیش‌پرداخت
       از خود محصول محاسبه می‌شود تا هیچ پنلی بدون پیش‌پرداخت ساخته نشود */
    $prepaidAmount = $isTrial ? 0
        : max(0, (int) ($payloadOrder['prepaid'] ?? panel_prepaid_amount($product)));
    $panelId = DB::exec('INSERT INTO panels(tg_id, product_id, panel_admin_id, panel_username, '
        . 'panel_password, label, max_users, device_limit, data_cap, expires_at, per_gb_price, '
        . 'hourly_price, min_balance, status, created_at, pg_panel_id, order_id, user_cap, is_trial, '
        . 'billing_start_at, prepaid_amount, last_meter_at) '
        . 'VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
        [$order['tg_id'], $product['id'], (int) ($created['id'] ?? 0), $username, $password,
         $product['name'] . ($isTrial ? ' (تست)' : ''), $userCap, (int) $product['device_limit'],
         (int) round($dataCapGb * 1024 ** 3),
         $expireAt, $isTrial ? 0 : (int) $product['per_gb_price'],
         $isTrial ? 0 : (int) $product['hourly_price'],
         (int) $product['min_balance'], 'active',
         now_ts(), (int) $panelRow['id'], (int) $order['id'], $userCap, $isTrial ? 1 : 0,
         $billingStartAt, $prepaidAmount,
         $billingStartAt > 0 ? $billingStartAt : now_ts()]);
    if (!$isTrial) {
        /* این‌ها نباید تحویل پنل را خراب کنند؛ پنل ساخته شده و باید به کاربر برسد */
        try {
            grant_order_discount($order, $panelId);
        } catch (Throwable $ex) {
            log_line('warning', 'grant_order_discount failed: ' . $ex->getMessage());
        }
        /* ⚠️ اینجا دیگر پولی کسر نمی‌شود: پیش‌پرداخت هنگام پرداخت فاکتور
           از کیف پول رفته است؛ فقط ثبت دفتری می‌شود */
        if ($prepaidAmount > 0) {
            try {
                panel_record_prepaid($panelId, (int) $order['tg_id'], $prepaidAmount,
                    $prepaidHours);
            } catch (Throwable $ex) {
                log_line('warning', 'prepaid ledger failed: ' . $ex->getMessage());
            }
        }
    }
    $user = user_get((int) $order['tg_id']);
    $who = e(mb_substr((string) ($user['name'] ?? $order['tg_id']), 0, 22));
    try {
        post_report(($isTrial ? '🧪 <b>پنل تست ساخته شد</b>' : '🛒 <b>پنل فروخته شد</b>') . "\n"
        . '👤 کاربر: ' . $who . ' <code>' . (int) $order['tg_id'] . "</code>\n"
        . '🆔 نام کاربری: <code>' . e($username) . "</code>\n"
        . '📦 محصول: ' . e((string) $product['name']) . "\n"
        . '🔌 پنل: ' . e((string) $panelRow['name']) . "\n"
        . '📊 حجم: ' . fa_digits($dataCapGb) . ' گیگ'
        . ($isTrial ? ' · ⏳ ' . fa_digits((int) (($expireAt - time()) / 3600)) . ' ساعت'
            : ' · ⏳ ' . fa_digits((int) $product['days']) . ' روز')
        . "\n" . '💵 مبلغ: ' . money((int) $order['payable']),
        $isTrial ? 'panel' : 'sales');
    } catch (Throwable $ex) {
        log_line('warning', 'sale report failed: ' . $ex->getMessage());
    }
    $dashboard = panel_dashboard_url($base);
    $nameNote = ($wantedName !== '' && $wantedName !== $username)
        ? '⚠️ نام دلخواه <code>' . e($wantedName) . "</code> روی پنل موجود بود؛ "
            . 'نام تازه صادر شد.' . "\n\n"
        : '';
    if ($isTrial) {
        return [true, "🧪 <b>پنل تست شما آماده است</b>\n\n" . $nameNote
            . '🌐 آدرس پنل: ' . e($dashboard) . "\n"
            . '👤 نام کاربری: <code>' . e($username) . "</code>\n"
            . '🔑 رمز: <code>' . e($password) . "</code>\n"
            . '📦 حجم: ' . fa_digits($dataCapGb) . " گیگ\n"
            . '⏳ مدت: ' . fa_digits((int) (($expireAt - time()) / 3600)) . " ساعت\n\n"
            . 'همین حالا در «📦 پنل‌های من» هم می‌بینی‌اش. برای پنل اصلی «🛒 خرید پنل» را بزنید.'];
    }
    return [true, "✅ <b>پنل شما آماده است</b>\n\n" . $nameNote
        . '🌐 آدرس پنل: ' . e(panel_dashboard_url($base)) . "\n"
        . '👤 نام کاربری: <code>' . e($username) . "</code>\n"
        . '🔑 رمز: <code>' . e($password) . "</code>\n"
        . '⏳ اعتبار: ' . fa_digits((int) $product['days']) . " روز\n"
        . '👥 سقف کاربر: ' . fa_digits($userCap) . "\n\n"
        . '🎓 از «📦 پنل‌های من» یا «🎓 راهنما» ادامه بدهید.'];
}

function order_product(array $order): ?array
{
    if (empty($order['product_id'])) {
        return null;
    }
    return product_get((int) $order['product_id']);
}

/**
 * تسویهٔ سفارش. خروجی: [موفق, متن برای کاربر]
 * انواع: panel | topup | slot
 */
function settle_payment(array $order, string $source = 'wallet', int $adminId = 0): array
{
    $kind = (string) $order['kind'];
    $tgId = (int) $order['tg_id'];
    /* یک سفارش فقط یک‌بار انجام می‌شود؛ دوبار زدن دکمه یعنی دوبار پنل ساختن */
    if ((string) $order['status'] === 'delivered') {
        return [true, '✅ این سفارش قبلاً انجام شده است.' . "\n"
            . 'کد سفارش: <code>' . e((string) $order['ref']) . '</code>' . "\n"
            . 'برای دیدن پنل‌ها «📦 پنل‌های من» را بزنید.'];
    }
    if ($kind === 'topup') {
        $payload = json_decode((string) $order['payload'], true) ?: [];
        $amount = (int) ($payload['topup'] ?? $order['payable']);
        $newBalance = add_balance($tgId, $amount, 'topup', (string) $order['id'],
            'شارژ کیف پول (' . pay_source_label($source) . ')');
        order_mark((int) $order['id'], 'delivered');
        /* شمارش واریزی + پورسانت معرف (فقط واریزی اول و دوم) */
        try {
            $depositNo = deposit_count_up($tgId);
            if (ref_mode() === 'cash' && ref_cash_when() === 'purchase') {
                referral_welcome_cash($tgId);   // پاداش نقدی معلق، با اولین شارژ
            }
            $commission = referral_deposit_payout($tgId, $amount);
            if ($commission > 0) {
                log_payment('referral commission', ['user' => $tgId, 'deposit' => $depositNo,
                    'amount' => $amount, 'reward' => $commission]);
            }
        } catch (Throwable $ex) {
            log_line('warning', 'referral deposit payout failed: ' . $ex->getMessage());
        }
        $user = user_get($tgId);
        post_report('💰 <b>شارژ کیف پول</b>' . "\n"
            . '👤 ' . e(mb_substr((string) ($user['name'] ?? $tgId), 0, 22))
            . ' <code>' . $tgId . "</code>\n"
            . '💵 مبلغ: <b>' . money($amount) . "</b>\n"
            . '🔀 روش: ' . e(pay_source_label($source)) . "\n"
            . '👛 موجودی جدید: ' . money($newBalance), 'topup');
        return [true, '✅ کیف پول شارژ شد: ' . money($amount) . "\nموجودی جدید: "
            . money($newBalance)];
    }
    if ($kind === 'users') {
        $payload = json_decode((string) $order['payload'], true) ?: [];
        $panelId = (int) ($payload['panel_id'] ?? 0);
        $block = max(1, (int) ($payload['block'] ?? 1000));
        $panel = DB::one('SELECT * FROM panels WHERE id=? AND tg_id=?', [$panelId, $tgId]);
        if ($panel === null) {
            order_mark((int) $order['id'], 'failed');
            return [false, 'این پنل پیدا نشد.'];
        }
        $cap = ((int) ($panel['user_cap'] ?? 0) ?: (int) $panel['max_users']) + $block;
        $panelRow = $panel['pg_panel_id']
            ? DB::one('SELECT * FROM pg_panels WHERE id=?', [(int) $panel['pg_panel_id']]) : null;
        if ($panelRow !== null) {
            try {
                (new PgPanel($panelRow))->update_admin((string) $panel['panel_username'],
                    ['users_limit' => $cap]);
            } catch (Throwable $ex) {
                order_mark((int) $order['id'], 'failed');
                return [false, 'افزایش سقف روی پنل انجام نشد: ' . $ex->getMessage()
                    . "\n(پرداخت انجام شده؛ با پشتیبانی تماس بگیرید)"];
            }
        }
        DB::exec('UPDATE panels SET user_cap=?, max_users=? WHERE id=?', [$cap, $cap, $panelId]);
        order_mark((int) $order['id'], 'delivered');
        post_report('➕ <b>افزایش سقف کاربر</b>' . "\n"
            . '👤 کاربر <code>' . $tgId . "</code>\n"
            . '📦 پنل <code>' . e((string) $panel['panel_username']) . "</code>\n"
            . '👥 سقف جدید: ' . fa_digits($cap) . "\n"
            . '💵 مبلغ: ' . money((int) $order['payable']), 'sales');
        return [true, '✅ سقف کاربر پنل <code>' . e((string) $panel['panel_username'])
            . '</code> شد <b>' . fa_digits($cap) . "</b> کاربر."];
    }
    if ($kind === 'slot') {
        DB::exec('INSERT INTO slots(tg_id, count, expires_at, created_at) VALUES(?,?,?,?)',
            [$tgId, 1, null, now_ts()]);
        order_mark((int) $order['id'], 'delivered');
        post_report('🧩 <b>خرید اسلات</b>' . "\n"
            . '👤 کاربر <code>' . $tgId . "</code>\n"
            . '💵 مبلغ: ' . money((int) $order['payable']), 'sales');
        return [true, '✅ یک اسلات اضافه شد.'];
    }
    try {
        [$ok, $text] = deliver_panel_order($order);
    } catch (Throwable $ex) {
        log_line('error', 'deliver failed: ' . $ex->getMessage());
        [$ok, $text] = [false, 'ساخت پنل با خطای غیرمنتظره متوقف شد: ' . $ex->getMessage()];
    }
    if ($ok) {
        order_mark((int) $order['id'], 'delivered');
        try {
            /* پاداش نقدی‌ای که مدیر روی «اولین خرید» گذاشته، همین‌جا آزاد می‌شود */
            if (ref_mode() === 'cash' && ref_cash_when() === 'purchase') {
                referral_welcome_cash($tgId);
            } else {
                referral_payout($order);
            }
        } catch (Throwable $ex) {
            log_line('warning', 'referral payout failed: ' . $ex->getMessage());
        }
    } else {
        order_mark((int) $order['id'], 'failed');
    }
    return [$ok, $text];
}

function pay_from_wallet(array $order): array
{
    $tgId = (int) $order['tg_id'];
    // کدی که تا لحظهٔ پرداخت منقضی/حذف شده، تخفیفش برداشته می‌شود
    $payload = json_decode((string) ($order['payload'] ?? ''), true) ?: [];
    $code = (string) ($payload['discount_code'] ?? '');
    if ($code !== '' && (int) $order['discount'] > 0) {
        [$stillOk] = discount_validate($code, $tgId);
        if (!$stillOk) {
            $payload['discount_code'] = '';
            DB::exec('UPDATE orders SET discount=0, payable=price, payload=? WHERE id=?',
                [json_encode($payload, JSON_UNESCAPED_UNICODE), (int) $order['id']]);
            $order = order_get((int) $order['id']) ?? $order;
            Tg::send($tgId, '⚠️ کد تخفیف این سفارش منقضی شده بود و حذف شد؛ '
                . 'مبلغ به قیمت اصلی برگشت.');
        }
    }
    if ((string) $order['status'] === 'delivered') {
        return settle_payment($order, 'wallet');
    }
    $payable = (int) $order['payable'];
    if (balance_of($tgId) < $payable) {
        return [false, 'موجودی کیف پول کافی نیست.'];
    }
    if ($payable > 0) {
        add_balance($tgId, -$payable, 'order', (string) $order['id'], 'پرداخت سفارش');
    }
    try {
        return settle_payment($order, 'wallet');
    } catch (Throwable $ex) {
        log_line('error', 'settle crashed: ' . $ex->getMessage());
        if ($payable > 0) {
            add_balance($tgId, $payable, 'refund', (string) $order['id'],
                'برگشت مبلغ به‌خاطر خطا در انجام سفارش');
        }
        return [false, 'انجام سفارش نیمه‌کاره ماند و مبلغ به کیف پولتان برگشت.' . "\n"
            . 'کد سفارش: <code>' . e((string) $order['ref']) . '</code>' . "\n"
            . '<i>دوباره تلاش کن؛ اگر تکرار شد با پشتیبانی تماس بگیرید.</i>'];
    }
}

/* 14) Review of card-to-card receipts */

/** مقصد کارت رسید: مالک و ادمین‌های ربات، در چت خصوصی */
function receipt_targets(): array
{
    $ids = [];
    $owner = owner_id();
    if ($owner > 0) {
        $ids[] = $owner;
    }
    foreach (admin_ids() as $adminId) {
        if (!in_array($adminId, $ids, true)) {
            $ids[] = $adminId;
        }
    }
    return $ids;
}

/** نام نمایشی کاربر برای کارت رسید */
function receipt_who(int $tgId): array
{
    $user = user_get($tgId);
    $name = trim((string) ($user['name'] ?? ''));
    if ($name === '') {
        $name = 'کاربر تلگرام';
    }
    $uname = trim((string) ($user['uname'] ?? ''));
    return [mb_substr($name, 0, 24), $uname !== '' ? '@' . $uname : '—'];
}

/** نام فارسی روش پرداخت — هیچ‌جا نام خام انگلیسی به کاربر نشان داده نمی‌شود */
function pay_source_label(string $source): string
{
    $source = trim($source);
    if ($source === '') {
        return 'نامشخص';
    }
    if (isset(PAY_GATEWAYS[$source])) {
        return (string) PAY_GATEWAYS[$source]['label'];
    }
    return match ($source) {
        'wallet'      => 'کیف پول',
        'receipt'     => 'کارت به کارت (رسید)',
        'admin'       => 'تأیید ادمین',
        'admin-late'  => 'تأیید ادمین (بعد از انقضا)',
        'stars'       => 'Telegram Stars',
        default       => $source,
    };
}

function receipt_kind_label(array $order): string
{
    return match ((string) ($order['kind'] ?? '')) {
        'topup'  => '💰 افزایش موجودی',
        'panel'  => '🛒 خرید پنل',
        'slot'   => '🧩 خرید اسلات',
        'trial'  => '🧪 پنل تست',
        'users'  => '➕ افزایش کاربر',
        'renew'  => '♻️ تمدید پنل',
        default  => '💳 پرداخت',
    };
}

function receipt_method_label(array $order): string
{
    return (string) ($order['channel'] ?? '') === 'gateway' ? '🌐 درگاه آنلاین' : '💳 کارت به کارت';
}

/**
 * متن کارت رسید.
 * $state: pending | approved | rejected
 */
function receipt_card_text(array $receipt, array $order, string $state = 'pending',
                           string $footer = ''): string
{
    [$name, $uname] = receipt_who((int) $receipt['tg_id']);
    $line = str_repeat('─', 14);
    $ref = trim((string) ($receipt['ref'] !== null && $receipt['ref'] !== ''
        ? $receipt['ref'] : ($order['ref'] ?? '')));
    $text = '🧾 <b>رسید پرداخت</b> · <code>#' . (int) $receipt['id'] . '</code>' . "\n"
        . $line . "\n"
        . '👤 کاربر: <b>' . e($name) . '</b> · <code>' . (int) $receipt['tg_id'] . '</code>' . "\n";
    if ($uname !== '' && $uname !== '—') {
        $text .= '🔗 نام کاربری: ' . e($uname) . "\n";
    }
    if ($ref !== '') {
        $text .= '🛒 کد سفارش: <code>' . e($ref) . '</code>' . "\n";
    }
    $text .= '📦 بابت: ' . receipt_kind_label($order) . "\n"
        . '💵 مبلغ: <b>' . money((int) $receipt['amount']) . '</b>' . "\n"
        . '💳 روش: ' . receipt_method_label($order) . "\n"
        . '🕒 ثبت: ' . fa_ts((int) $receipt['created_at']) . "\n"
        . $line . "\n";
    if ($state === 'approved') {
        $text .= '✅ <b>پرداخت تأیید شد</b>';
    } elseif ($state === 'rejected') {
        $text .= '❌ <b>پرداخت رد شد</b>';
    } else {
        $text .= '⏳ <b>در انتظار بررسی</b>';
    }
    if ($footer !== '') {
        $text .= "\n" . $footer;
    }
    return $text;
}

function receipt_card_kb(int $receiptId): array
{
    return [[
        btn('✅ تأیید پرداخت', 'ad:rc:' . $receiptId . ':ok', null, 'success'),
        btn('❌ رد پرداخت', 'ad:rc:' . $receiptId . ':no', null, 'danger'),
    ]];
}

/**
 * ارسال کارت رسید به «یک» مقصد:
 * تاپیک رسیدهای گروه گزارشات؛ اگر گروه تنظیم نشده باشد، به پیام خصوصی ادمین اصلی.
 * خروجی: [چت, شناسهٔ پیام]
 */
function receipt_post_card(int $receiptId): array
{
    $receipt = DB::one('SELECT * FROM receipts WHERE id=?', [$receiptId]);
    $order = $receipt !== null ? order_get((int) $receipt['order_id']) : null;
    if ($receipt === null || $order === null) {
        return ['', 0];
    }
    $caption = receipt_card_text($receipt, $order, 'pending');
    $kb = receipt_card_kb($receiptId);
    $photo = (string) ($receipt['photo_id'] ?? '');
    /* کارت (عکس + دکمه‌ها) فقط در چت خصوصی مدیر می‌آید؛ دکمه در گروه کار نمی‌کند */
    $sent = ['', 0];
    foreach (receipt_targets() as $adminId) {
        if ($photo !== '') {
            $msgId = Tg::photoThread($adminId, $photo, $caption, 0, kb_ensure_back(kb_clean($kb)));
        } else {
            $msgId = (int) Tg::send($adminId, $caption, $kb);
        }
        if ($msgId && $sent[1] === 0) {
            $sent = [(string) $adminId, (int) $msgId];
        }
    }
    if ($sent[1] > 0) {
        DB::exec('UPDATE receipts SET card_chat=?, card_msg=? WHERE id=?',
            [$sent[0], $sent[1], $receiptId]);
    }
    /* و فقط یک گزارش متنی، بدون دکمه، در تاپیک رسیدها */
    [$name, $uname] = receipt_who((int) $receipt['tg_id']);
    post_report('🧾 <b>رسید تازه #' . $receiptId . '</b>' . "\n"
        . '👤 ' . e($name) . ' · <code>' . (int) $receipt['tg_id'] . '</code>' . "\n"
        . '🔗 ' . e($uname) . "\n"
        . '📦 ' . receipt_kind_label($order) . ' · ' . money((int) $receipt['amount']) . "\n"
        . '🕒 ' . fa_ts((int) $receipt['created_at']) . "\n"
        . '<i>عکس رسید و دکمه‌های تأیید در چت خصوصی ربات آمده است.</i>', 'receipt');
    return $sent;
}

/** پایان کار رسید: کارت را همان‌جا به‌روز می‌کند (پیام تکراری ساخته نمی‌شود) */
function receipt_close_card(int $receiptId, bool $approve, int $adminId, string $footer = ''): void
{
    $receipt = DB::one('SELECT * FROM receipts WHERE id=?', [$receiptId]);
    $order = $receipt !== null ? order_get((int) $receipt['order_id']) : null;
    if ($receipt === null || $order === null) {
        return;
    }
    $caption = receipt_card_text($receipt, $order, $approve ? 'approved' : 'rejected', $footer);
    $chat = (string) ($receipt['card_chat'] ?? '');
    $msgId = (int) ($receipt['card_msg'] ?? 0);
    if ($chat === '' || $msgId <= 0) {
        return;
    }
    Tg::editCaption($chat, $msgId, $caption, null);
}

function review_receipt(int $receiptId, bool $approve, int $adminId): array
{
    $receipt = DB::one('SELECT * FROM receipts WHERE id=?', [$receiptId]);
    if ($receipt === null) {
        return [false, 'رسید پیدا نشد'];
    }
    if ($receipt['status'] !== 'pending') {
        return [false, 'این رسید قبلاً بررسی شده است'];
    }
    $order = order_get((int) $receipt['order_id']);
    if ($order === null) {
        return [false, 'سفارش پیدا نشد'];
    }
    DB::exec('UPDATE receipts SET status=?, reviewed_by=?, reviewed_at=? WHERE id=?',
        [$approve ? 'approved' : 'rejected', $adminId, now_ts(), $receiptId]);
    log_payment('card receipt reviewed', [
        'receipt' => $receiptId, 'approve' => $approve, 'admin' => $adminId,
        'tg' => (int) $receipt['tg_id'], 'amount' => (int) $receipt['amount'],
        'ref' => (string) $receipt['ref'],
    ]);
    $stamp = '🕒 ' . fa_ts(now_ts()) . ' · 👮 بررسی: <code>' . $adminId . '</code>';
    if (!$approve) {
        order_mark((int) $order['id'], 'rejected');
        receipt_close_card($receiptId, false, $adminId, $stamp);
        Tg::send((int) $order['tg_id'], '❌ <b>رسید تأیید نشد</b>' . "\n\n"
            . '🧾 سفارش: <code>' . e((string) $order['ref']) . '</code>' . "\n"
            . '💵 مبلغ: ' . money((int) $receipt['amount']) . "\n\n"
            . 'اگر مبلغ را واریز کرده‌ای، رسید را دوباره با پشتیبانی هماهنگ کنید.',
            [[btn('☎️ پشتیبانی', 'menu:support', null, 'primary')],
             [btn('« خانه', 'home', null, 'danger')]]);
        return [true, 'رسید رد شد'];
    }
    $balanceBefore = balance_of((int) $order['tg_id']);
    [$ok, $text] = settle_payment($order, 'card', $adminId);
    $balanceAfter = balance_of((int) $order['tg_id']);
    Tg::send((int) $order['tg_id'], $text, home_kb((int) $order['tg_id']));
    $footer = $stamp;
    if ($ok) {
        $footer .= "\n👛 موجودی کاربر: " . money($balanceAfter)
            . ($balanceBefore !== $balanceAfter ? ' <i>(+' . money($balanceAfter - $balanceBefore) . ')</i>' : '');
    } else {
        $footer .= "\n⚠️ ولی تحویل با خطا مواجه شد — گزارش خطا را ببینید.";
    }
    receipt_close_card($receiptId, $ok, $adminId, $footer);
    return [true, $ok ? 'تأیید و تحویل شد ✅' : 'تأیید شد ولی تحویل خطا داد ⚠️'];
}

function screen_receipts(int|string $chat, ?int $messageId): void
{
    $rows = DB::all("SELECT * FROM receipts WHERE status='pending' ORDER BY id LIMIT 10");
    if (!$rows) {
        Tg::show($chat, $messageId, '🧾 رسید در انتظاری نیست.',
            [[btn('🔎 جستجو با کد پیگیری', 'ad:rsearch', null, 'success')],
             [btn('« مالی', 'ad:finance', null, 'danger')]]);
        return;
    }
    Tg::send($chat, '🔎 اگر رسید مشخصی را می‌خواهی، با کد پیگیری جستجو کنید.',
        [[btn('🔎 جستجوی رسید', 'ad:rsearch', null, 'success')]]);
    foreach ($rows as $row) {
        $caption = '🧾 رسید #' . $row['id'] . ' — سفارش #' . $row['order_id'] . "\n"
            . 'کاربر <code>' . $row['tg_id'] . '</code> | ' . money((int) $row['amount']) . "\n"
            . 'کد: <code>' . e((string) $row['ref']) . '</code>';
        $markup = [[
            btn('✅ تأیید', 'ad:rc:' . $row['id'] . ':ok', null, 'success'),
            btn('❌ رد', 'ad:rc:' . $row['id'] . ':no', null, 'danger'),
        ]];
        if (!empty($row['photo_id'])) {
            Tg::photo($chat, (string) $row['photo_id'], $caption, $markup);
        } else {
            Tg::send($chat, $caption, $markup);
        }
    }
}

/* 15) Wizard engine — هر ورودی چندمرحله‌ای از همین‌جا رد می‌شود */

function wiz_start(int $uid, string $flow, array $steps, array $context = []): void
{
    $state = ['flow' => $flow, 'i' => 0, 'steps' => $steps, 'values' => [],
              'ctx' => $context];
    State::set($uid, 'wiz', $state);
    wiz_render($uid, $state, $uid, null);
}

function wiz_header(array $state): string
{
    $i = (int) $state['i'];
    $total = count($state['steps']);
    $title = $state['steps'][$i]['title'] ?? 'دریافت اطلاعات';
    return '<b>' . e($title) . '</b> · گام ' . fa_digits($i + 1) . ' از ' . fa_digits($total);
}

/**
 * تعریف یک گام ویزارد.
 * گزینه‌های دکمه‌ای باید قابل ذخیره در دیتابیس باشند (state به JSON می‌رود)،
 * پس یا «برچسب آماده» است («panels»، «roles») یا فهرستی از
 * ['label' => متن, 'value' => مقدار, 'style' => رنگ].
 */
function step_def(string $key, string $prompt, string $kind = 'text', mixed $default = null,
                  string $title = '', string|array|null $options = null): array
{
    return ['key' => $key, 'prompt' => $prompt, 'kind' => $kind,
            'default' => $default, 'title' => $title, 'options' => $options];
}

/** دکمه‌های یک گام را از روی برچسب/فهرست می‌سازد (همیشه از state خوانده می‌شود) */
function wiz_options(array $step, array $data): array
{
    $spec = $step['options'] ?? null;
    if (is_string($spec) && $spec === 'panels') {
        $rows = [];
        foreach (DB::all('SELECT * FROM pg_panels WHERE active=1 ORDER BY is_default DESC, id') as $row) {
            $rows[] = [btn('🔌 ' . (string) $row['name'], 'wiz:' . (int) $row['id'], null, 'success')];
        }
        if (!$rows) {
            $rows[] = [btn('➕ افزودن پنل پاسارگارد', 'ad:panel:new', null, 'danger')];
        }
        return $rows;
    }
    if (is_string($spec) && $spec === 'roles') {
        $panelId = (int) ($data['values']['panel_id'] ?? 0);
        if ($panelId <= 0) {
            $first = DB::one('SELECT id FROM pg_panels WHERE active=1 '
                . 'ORDER BY is_default DESC, id LIMIT 1');
            $panelId = $first === null ? 0 : (int) $first['id'];
        }
        if ($panelId <= 0) {
            return [[btn('➕ افزودن پنل پاسارگارد', 'ad:panel:new', null, 'danger')]];
        }
        $page = (int) ($data['ctx']['role_page'] ?? 1);
        $rows = role_buttons($panelId, 0, 'wizrole', $page);
        if (!$rows) {
            $rows = [[btn('🔄 خواندن نقش‌های این پنل', 'wizrole:' . $panelId . ':refresh:0',
                null, 'danger')]];
        } else {
            $rows[] = [btn('🔄 به‌روزرسانی نقش‌های این پنل', 'wizrole:' . $panelId . ':refresh:0')];
        }
        return $rows;
    }
    if (is_array($spec)) {
        $rows = [];
        foreach ($spec as $choice) {
            if (!is_array($choice)) {
                continue;
            }
            $style = (string) ($choice['style'] ?? 'auto');
            $rows[] = [btn((string) ($choice['label'] ?? ''),
                'wiz:' . (string) ($choice['value'] ?? ''), null, $style)];
        }
        return $rows;
    }
    return [];
}

/** نمایش گام فعلی ویزارد (با دکمه‌ها اگر گام گزینه‌ای باشد) */
function wiz_render(int $uid, array $data, int|string $chat, ?int $messageId): void
{
    $i = (int) $data['i'];
    $step = $data['steps'][$i];
    $text = wiz_header($data) . "\n\n" . $step['prompt'];
    $rows = wiz_options($step, $data);
    if (!$rows) {
        $text .= "\n\nبرای لغو: <code>لغو</code>";
    }
    $rows[] = [btn('« بازگشت', 'cancel', null, 'danger')];
    if ($messageId) {
        Tg::show($chat, $messageId, $text, $rows);
    } else {
        Tg::send($chat, $text, $rows);
    }
}

/** انتخاب دکمه‌ای در ویزارد */
function wiz_pick(int $uid, mixed $value, int|string $chat, ?int $messageId): void
{
    $state = State::get($uid);
    if ($state['state'] !== 'wiz') {
        Tg::send($chat, 'این انتخاب منقضی شده.', [[btn('« مدیریت', 'ad:home', null, 'danger')]]);
        return;
    }
    $data = $state['data'];
    $i = (int) $data['i'];
    $step = $data['steps'][$i] ?? null;
    if ($step === null) {
        return;
    }
    $data['values'][$step['key']] = $value;
    $data['i'] = $i + 1;
    if ($data['i'] < count($data['steps'])) {
        $next = $data['steps'][$data['i']];
        if (($next['options'] ?? null) === 'roles') {
            /* فقط نقش‌های همان پنلی که انتخاب شد، تازه از خودش خوانده می‌شود */
            $panelId = (int) ($data['values']['panel_id'] ?? 0);
            $data['ctx']['role_page'] = 1;
            if ($panelId > 0) {
                roles_cache($panelId, true);
            }
        }
        State::set($uid, 'wiz', $data);
        wiz_render($uid, $data, $chat, $messageId);
        return;
    }
    State::clear($uid);
    wiz_finish($uid, $data);
}

function parse_step_value(array $step, string $raw): array
{
    $raw = trim($raw);
    if ($raw === '-') {
        return [true, $step['default']];
    }
    return match ($step['kind']) {
        'int'   => to_int($raw) === null ? [false, null] : [true, to_int($raw)],
        'float' => to_float($raw) === null ? [false, null] : [true, to_float($raw)],
        default => $raw === '' ? [false, null] : [true, mb_substr($raw, 0, 80)],
    };
}

function wiz_advance(array $message): void
{
    $uid = (int) $message['from']['id'];
    $state = State::get($uid);
    $data = $state['data'];
    $raw = (string) ($message['text'] ?? '');
    if (in_array(trim($raw), ['لغو', 'cancel', '/cancel'], true)) {
        State::clear($uid);
        Tg::send($uid, 'لغو شد.', console_kb() ?? home_kb($uid));
        return;
    }
    $i = (int) $data['i'];
    $step = $data['steps'][$i];
    [$ok, $value] = parse_step_value($step, $raw);
    if (!$ok) {
        Tg::send($uid, 'مقدار نامعتبر. دوباره بفرستید:' . "\n" . $step['prompt']);
        return;
    }
    $data['values'][$step['key']] = $value;
    $data['i'] = $i + 1;
    if ($data['i'] < count($data['steps'])) {
        State::set($uid, 'wiz', $data);
        $next = $data['steps'][$data['i']];
        if (wiz_options($next, $data)) {
            wiz_render($uid, $data, $uid, null);
        } else {
            Tg::send($uid, 'دریافت شد ✅' . "\n\n" . $next['prompt']
                . "\n\nبرای لغو: <code>لغو</code>");
        }
        return;
    }
    State::clear($uid);
    wiz_finish($uid, $data);
}

function wiz_finish(int $uid, array $data): void
{
    $values = $data['values'];
    $ctx = $data['ctx'] ?? [];
    switch ($data['flow']) {
        case 'cat_new':
            $name = trim((string) ($values['name'] ?? ''));
            if ($name === '') {
                Tg::send($uid, 'نام خالی بود. دوباره از «دستهٔ جدید» شروع کنید.', console_kb());
                return;
            }
            $editId = (int) ($ctx['edit_id'] ?? 0);
            if ($editId) {
                DB::exec('UPDATE categories SET name=?, emoji=? WHERE id=?',
                    [$name, $values['emoji'] ?: '🗂', $editId]);
                Tg::send($uid, '✅ دسته به‌روز شد.', [[btn('« دسته', 'ad:cat:' . $editId, null, 'success')]]);
                return;
            }
            $catId = cat_create($name, (string) ($values['emoji'] ?: '🗂'));
            Tg::send($uid, '✅ دسته ساخته شد.' . "\n\n" . e($name)
                . "\n\nحالا داخل همین دسته محصول بساز.",
                [[btn('➕ محصول در این دسته', 'ad:cat:' . $catId . ':new', null, 'success')],
                 [btn('« دسته‌ها', 'ad:cats', null, 'danger')]]);
            return;

        case 'prod_new':
            $catId = (int) ($ctx['cat_id'] ?? 0);
            $panelId = (int) ($values['panel_id'] ?? 0);
            $panelRow = $panelId ? DB::one('SELECT * FROM pg_panels WHERE id=?', [$panelId]) : null;
            if ($panelRow === null) {
                $panelRow = DB::one('SELECT * FROM pg_panels WHERE active=1 '
                    . 'ORDER BY is_default DESC, id LIMIT 1');
            }
            if ($panelRow === null) {
                Tg::send($uid, '❌ هیچ پنل پاسارگارد فعالی نیست.',
                    [[btn('🔌 پنل‌ها', 'ad:panel', null, 'primary')]]);
                return;
            }
            $roleId = (int) ($values['role_id'] ?? 0);
            if ($roleId <= 0) {
                Tg::send($uid, '❌ نقشی انتخاب نشد؛ محصول ساخته نشد.' . "\n"
                    . 'دوباره از «➕ محصول» شروع کنید.',
                    [[btn('➕ محصول جدید', 'ad:cat:' . $catId . ':new', null, 'success')]]);
                return;
            }
            $roleName = '';
            foreach (roles_cache((int) $panelRow['id']) as $roleRow) {
                if ($roleRow['id'] === $roleId) {
                    $roleName = $roleRow['name'];
                }
            }
            $active = 1;
            $productId = DB::exec('INSERT INTO products(name, emoji, category, category_id, '
                . 'role_id, group_ids, max_users, device_limit, days, data_cap_gb, per_gb_price, '
                . 'hourly_price, min_balance, renew_price, slots_needed, panel_prefix, trial, '
                . 'active, created_at, panel_id) '
                . 'VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
                [trim((string) $values['name']), $values['emoji'] ?: '💎', 'v2ray', $catId,
                 $roleId, '[]', 10, 1, 30, 0, (int) ($values['per_gb_price'] ?? 0),
                 (int) ($values['hourly_price'] ?? 0), 0, 0, 1, '', 0, $active,
                 now_ts(), (int) $panelRow['id']]);
            $text = '✅ محصول #' . $productId . " ساخته شد.\n\n"
                . $values['emoji'] . ' <b>' . e((string) $values['name']) . "</b>\n"
                . '🔌 پنل: ' . e((string) $panelRow['name']) . "\n"
                . '🎭 نقش: ' . e($roleName !== '' ? $roleName : (string) $roleId) . "\n"
                . '⏱ ' . money((int) ($values['hourly_price'] ?? 0)) . ' /ساعت · 💵 '
                . money((int) ($values['per_gb_price'] ?? 0)) . ' /گیگ';
            $buttons = [[btn('👁 پیش‌نمایش محصول', 'ad:prod:' . $productId)]];
            $buttons[] = [btn('➕ محصول بعدی', 'ad:cat:' . $catId . ':new', null, 'success')];
            $buttons[] = [btn('« بازگشت به دسته', 'ad:cat:' . $catId, null, 'danger')];
            Tg::send($uid, $text, $buttons);
            return;

        case 'panel_pass':
            $panelId = (int) ($ctx['panel_id'] ?? 0);
            $password = trim((string) ($values['password'] ?? ''));
            [$okPass, $notePass] = panel_change_password($panelId, $password);
            Tg::send($uid, ($okPass ? '' : '⚠️ ') . $notePass,
                [[btn('« پنل', 'pn:' . $panelId, null, 'danger')]]);
            return;

        case 'prod_field':
            $productId = (int) ($ctx['product_id'] ?? 0);
            $field = (string) ($ctx['field'] ?? '');
            $meta = PRODUCT_FIELDS[$field] ?? null;
            if ($meta === null) {
                Tg::send($uid, 'این گزینه پیدا نشد.', console_kb());
                return;
            }
            product_update($productId, $meta[2], $values['value']);
            if ($field === 'role') {
                DB::exec('UPDATE products SET active=1 WHERE id=? AND role_id>0', [$productId]);
            }
            Tg::send($uid, '✅ ذخیره شد: <b>' . e((string) $values['value']) . '</b>',
                [[btn('« محصول', 'ad:prod:' . $productId, null, 'success')]]);
            return;

        case 'gwfield':
            $gw = (string) ($ctx['gw'] ?? '');
            $field = (string) ($ctx['field'] ?? '');
            if (!isset(PAY_GATEWAYS[$gw])) {
                Tg::send($uid, 'درگاه پیدا نشد.', console_kb());
                return;
            }
            $value = $values['value'];
            $settingKey = 'pay_' . $gw . ($field === 'minfiat' ? '_min_fiat' : '_' . $field);
            set_put($settingKey, (string) $value);
            if ($field === 'minfiat') {
                set_put('pay_' . $gw . '_min_cache', '0');
                set_put('pay_' . $gw . '_min_at', '0');
            }
            if (in_array($field, ['key', 'key2'], true) && (string) $value !== ''
                && set_get('pay_' . $gw . '_on') !== '1' && $gw !== 'card') {
                set_put('pay_' . $gw . '_on', '1');
            }
            Tg::send($uid, '✅ ذخیره شد: <b>'
                . e((string) $value) . '</b>',
                [[btn('« درگاه', 'ad:pay:' . $gw, null, 'success')]]);
            return;

        case 'swapkey':
            $value = trim((string) $values['value']);
            if ($value === '') {
                Tg::send($uid, '❌ کلید خالی است. دوباره از «💎 سواپ‌ولت» شروع کنید.',
                    [[btn('« سواپ‌ولت', 'ad:pay:swap', null, 'danger')]]);
                return;
            }
            set_put('swap_api_key', $value);
            set_put('swap_rates_at', '0');
            set_put('swap_star_at', '0');
            set_put('swap_rates_cache', '');
            $check = swap_get(SWAP_PATH_CHECK);
            if (!swap_ok($check)) {
                Tg::send($uid, '⚠️ کلید ذخیره شد ولی سواپ‌ولت تأییدش نکرد:'
                    . "\n" . '<code>' . e((string) ($check['_error']
                        ?? ($check['message'] ?? 'پاسخ نامعتبر'))) . '</code>'
                    . "\n" . 'کلید را دوباره بررسی کنید.',
                    [[btn('🔑 کلید دوباره', 'ad:pay:swap:key', null, 'primary')],
                     [btn('« سواپ‌ولت', 'ad:pay:swap', null, 'danger')]]);
                return;
            }
            swap_rates(true);
            swap_star_usdt(true);
            screen_swap($uid, null, true);
            return;

        case 'setting':
            $key = (string) ($ctx['key'] ?? '');
            /* شماره کارت و نام صاحب کارت را می‌شود با هم فرستاد؛ خودمان تفکیک می‌کنیم */
            if ($key === 'card_number') {
                [$cardNo, $holder] = parse_card_input((string) $values['value']);
                if ($cardNo === '') {
                    Tg::send($uid, "❌ در متن ارسالی شمارهٔ کارت پیدا نشد.\n\n"
                        . 'مثال درست:' . "\n"
                        . '<code>6104331002032630 سید ابوالفضل موسوی</code>',
                        [[btn('🔢 دوباره', 'ad:set:card_number', null, 'primary')],
                         [btn('« مالی', 'ad:finance', null, 'danger')]]);
                    return;
                }
                set_put('card_number', $cardNo);
                if ($holder !== '') {
                    set_put('card_holder', $holder);
                }
                Tg::send($uid, "✅ کارت به کارت تنظیم شد\n\n"
                    . 'شماره کارت: <code>' . e($cardNo) . '</code>' . "\n"
                    . 'صاحب کارت: ' . e(set_get('card_holder', '—')) . "\n\n"
                    . '<i>کاربر این شماره را با یک ضربه کپی می‌کند.</i>',
                    [[btn('💳 کارت به کارت', 'ad:pay:card', null, 'success')],
                     [btn('« مالی', 'ad:finance', null, 'danger')]]);
                return;
            }
            /* آیدی پشتیبانی: @name و لینک t.me هر دو پذیرفته و یکسان ذخیره می‌شوند */
            if ($key === 'support_link') {
                $rawSupport = trim((string) $values['value']);
                $supportHandle = '';
                if (preg_match('~t\.me/([A-Za-z0-9_]{3,32})~i', $rawSupport, $sm)) {
                    $supportHandle = $sm[1];
                } elseif (preg_match('~^@?([A-Za-z0-9_]{3,32})$~', $rawSupport, $sm)) {
                    $supportHandle = $sm[1];
                }
                if ($supportHandle === '' && $rawSupport !== '') {
                    Tg::send($uid, "❌ این آیدی معتبر نیست.\n\n"
                        . 'یکی از این دو شکل را بفرستید:' . "\n"
                        . '· <code>@my_support</code>' . "\n"
                        . '· <code>https://t.me/my_support</code>',
                        [[btn('📞 دوباره', 'ad:set:support_link', null, 'primary')],
                         [btn('« تنظیمات', 'ad:setg:report', null, 'danger')]]);
                    return;
                }
                set_put('support_link', $supportHandle !== '' ? '@' . $supportHandle : '');
                Tg::send($uid, "✅ «آیدی پشتیبانی» ذخیره شد: <b>"
                    . e($supportHandle !== '' ? '@' . $supportHandle : '—') . "</b>\n\n"
                    . '<i>دکمهٔ شیشه‌ای «☎️ پشتیبانی» همین حالا به '
                    . '<code>https://t.me/' . e($supportHandle) . '</code> وصل شد.</i>',
                    [[btn('« تنظیمات', 'ad:setg:report', null, 'danger')]]);
                return;
            }
            set_put($key, (string) $values['value']);
            $label = SETTING_LABELS[$key] ?? 'مقدار';
            $backTo = match (setting_group_of($key)) {
                'finset' => 'ad:finset',
                'card' => 'ad:pay:card',
                'kyc' => 'ad:setg:kyc',
                default => 'ad:setg:home',
            };
            Tg::send($uid, '✅ «' . $label . '» ذخیره شد: <b>' . e((string) $values['value'])
                . '</b>', [[btn('« بازگشت', $backTo, null, 'danger')]]);
            return;

        case 'disc_new':
            $code = strtoupper(preg_replace('/\s+/', '', (string) $values['code']) ?? '');
            if (strlen($code) < 3) {
                Tg::send($uid, '❌ کد باید حداقل ۳ حرف باشد. دوباره از «➕ ساخت کد تخفیف» شروع کنید.',
                    [[btn('🏷 کدها', 'ad:fin:disc', null, 'danger')]]);
                return;
            }
            if (discount_row($code) !== null) {
                Tg::send($uid, '❌ این کد قبلاً ساخته شده. یک نام دیگر بفرستید.',
                    [[btn('🏷 کدها', 'ad:fin:disc', null, 'danger')]]);
                return;
            }
            $percent = max(0, min(100, (int) ($values['percent'] ?? 0)));
            if ($percent <= 0) {
                Tg::send($uid, '❌ درصد تخفیف باید بیشتر از صفر باشد.',
                    [[btn('🏷 کدها', 'ad:fin:disc', null, 'danger')]]);
                return;
            }
            $maxUsers = max(0, (int) ($values['max_users'] ?? 0));
            $perUser = max(0, (int) ($values['per_user'] ?? 1));
            if ($maxUsers > 0 && $perUser > $maxUsers) {
                $perUser = $maxUsers;
            }
            $hours = max(0, (int) ($values['hours'] ?? 0));
            $days = max(0, (int) ($values['days'] ?? 30));
            DB::exec('INSERT INTO discounts(code, percent, amount, max_uses, max_users, uses, '
                . 'per_user, first_only, hours, days, expires_at, active, created_at) '
                . 'VALUES(?,?,0,?,?,0,?,?,?,?,?,1,?)',
                [$code, $percent, $maxUsers, $maxUsers, $perUser,
                 (int) ($values['first_only'] ?? 0), $hours, $days,
                 $hours > 0 ? now_ts() + $hours * 3600 : null, now_ts()]);
            Tg::send($uid, '✅ کد تخفیف ساخته شد.' . "\n\n"
                . '🏷 کد: <code>' . e($code) . "</code>\n"
                . '💯 تخفیف: <b>' . fa_digits($percent) . "</b>٪ (روی خرید و مصرف هر گیگ)\n"
                . '👥 سقف: ' . ($maxUsers > 0 ? fa_digits($maxUsers) . ' کاربر'
                    : 'نامحدود') . "\n"
                . '🔁 هر کاربر: ' . ($perUser > 0 ? fa_digits($perUser) . ' بار' : 'نامحدود')
                . "\n"
                . '🛒 نوع: ' . ((int) ($values['first_only'] ?? 0) === 1 ? 'فقط خرید اول'
                    : 'همهٔ خریدها') . "\n"
                . '⏳ مهلت کد: ' . ($hours > 0 ? fa_digits($hours) . ' ساعت' : 'نامحدود') . "\n"
                . '🏷 مدت تخفیف مصرف: ' . fa_digits($days) . ' روز',
                [[btn('🏷 فهرست کدها', 'ad:fin:disc', null, 'success')]]);
            return;

        case 'refund':
            $raw = trim((string) $values['ref']);
            $order = DB::one('SELECT * FROM orders WHERE ref=? OR id=?',
                [strtoupper($raw), to_int($raw) ?? 0]);
            if ($order === null) {
                Tg::send($uid, 'سفارشی با این کد پیدا نشد.',
                    [[btn('« مالی', 'ad:finance', null, 'danger')]]);
                return;
            }
            if ($order['status'] === 'refunded' || (int) $order['payable'] === 0) {
                Tg::send($uid, 'این سفارش قابل برگشت نیست.',
                    [[btn('« مالی', 'ad:finance', null, 'danger')]]);
                return;
            }
            $amount = (int) $order['payable'];
            add_balance((int) $order['tg_id'], $amount, 'refund', (string) $order['id'],
                'بازگشت وجه سفارش #' . $order['id']);
            DB::exec("UPDATE orders SET status='refunded' WHERE id=?", [(int) $order['id']]);
            Tg::send((int) $order['tg_id'], '↩️ مبلغ ' . money($amount) . ' بابت سفارش #'
                . $order['id'] . ' به کیف پولتان برگشت.');
            Tg::send($uid, '✅ بازگشت وجه انجام شد.' . "\n" . 'سفارش #' . $order['id']
                . ' · ' . money($amount) . "\n" . 'موجودی جدید کاربر: '
                . money(balance_of((int) $order['tg_id'])),
                [[btn('« مالی', 'ad:finance', null, 'danger')]]);
            return;

        case 'user_balance':
            $tgId = (int) ($ctx['tg_id'] ?? 0);
            $amount = (int) ($values['amount'] ?? 0);
            if ((int) ($ctx['sign'] ?? 1) < 0) {
                $amount = -abs($amount);
            }
            if ($amount === 0) {
                Tg::send($uid, 'مبلغ صفر است؛ تغییری ندادم.', console_kb());
                return;
            }
            $newBalance = add_balance($tgId, $amount, 'admin', (string) $uid, 'تغییر دستی ادمین');
            post_report('💰 <b>تغییر موجودی توسط ادمین</b>' . "\n" . 'کاربر <code>' . $tgId
                . '</code> · ' . money($amount) . "\n" . 'موجودی جدید: ' . money($newBalance));
            Tg::send($tgId, '💰 موجودی کیف پولتان تغییر کرد: <b>' . money($amount) . '</b>' . "\n"
                . 'موجودی جدید: <b>' . money($newBalance) . '</b>');
            Tg::send($uid, '✅ انجام شد.' . "\n" . 'موجودی جدید: <b>' . money($newBalance) . '</b>',
                [[btn('« کاربر', 'ad:u:' . $tgId, null, 'success')]]);
            return;

        case 'find_panel':
            $q = trim((string) ($values['value'] ?? ''));
            $digits = preg_replace('/\D/', '', $q) ?? '';
            $row = null;
            if ($digits !== '' && $digits === $q) {
                $row = DB::one('SELECT * FROM panels WHERE id=?', [(int) $digits]);
            }
            if ($row === null) {
                $row = DB::one('SELECT * FROM panels WHERE panel_username=?', [$q]);
            }
            if ($row === null) {
                $row = DB::one('SELECT * FROM panels WHERE panel_username LIKE ? '
                    . 'ORDER BY id DESC LIMIT 1', ['%' . $q . '%']);
            }
            if ($row === null) {
                Tg::send($uid, '🔎 پنلی با «' . e($q) . '» پیدا نشد.' . "\n"
                    . '<i>نام کاربری پنل یا شناسهٔ عددی آن را دقیق بفرستید.</i>',
                    [[btn('🔍 جستجوی دوباره', 'ad:find:panel', null, 'success')],
                     [btn('« جستجوی سفارشات', 'ad:find', null, 'danger')]]);
                return;
            }
            screen_find_panel($uid, null, (int) $row['id']);
            return;

        case 'find_inv':
            screen_find_invoice($uid, null, (string) ($values['value'] ?? ''));
            return;

        case 'find_extend':
            $panelId = (int) ($ctx['panel_id'] ?? 0);
            $gigs = max(0, (int) ($values['gigs'] ?? 0));
            $days = max(0, (int) ($values['days'] ?? 0));
            [$okE, $msgE] = admin_panel_extend($panelId, $gigs, $days);
            Tg::send($uid, $msgE);
            screen_find_panel($uid, null, $panelId);
            return;

        case 'usermsg':
            $tgId = (int) ($ctx['tg_id'] ?? 0);
            $okSend = Tg::send($tgId, (string) $values['text']);
            Tg::send($uid, $okSend ? '✅ پیام رسید.' : '❌ پیام نرسید (کاربر ربات را بلاک کرده).',
                [[btn('« کاربر', 'ad:u:' . $tgId, null, 'success')]]);
            return;

        case 'user_gift':
            $tgId = (int) ($ctx['tg_id'] ?? 0);
            $percent = max(0, min(100, (int) ($values['percent'] ?? 0)));
            $days = max(0, (int) ($values['days'] ?? 0));
            [$okGift, $msgGift] = user_discount_grant($tgId, $percent, $days);
            if ($okGift && $percent > 0) {
                Tg::send($tgId, '🎁 یک تخفیف اختصاصی <b>' . fa_digits($percent) . '</b>٪'
                    . ($days > 0 ? ' برای ' . fa_digits($days) . ' روز' : ' بی‌پایان')
                    . ' روی خریدهایت فعال شد.');
                post_report('🎁 <b>تخفیف اختصاصی</b>' . "\n" . 'کاربر: <code>' . $tgId
                    . '</code>' . "\n" . 'درصد: ' . fa_digits($percent) . '٪', 'sales');
            }
            Tg::send($uid, $msgGift, [[btn('« کاربر', 'ad:u:' . $tgId, null, 'danger')]]);
            return;

        case 'trackcode':
            $code = trim((string) $values['value']);
            $found = order_by_code($code, $uid);
            if ($found === null) {
                Tg::send($uid, '🔎 سفارشی با کد <code>' . e($code) . "</code> برای شما پیدا نشد.\n"
                    . '<i>کد پیگیری را دقیق بفرست؛ همان کدی که بعد از پرداخت گرفتی.</i>',
                    [[btn('🔎 دوباره', 'menu:track', null, 'success')],
                     [btn('« خانه', 'home', null, 'danger')]]);
                return;
            }
            order_track_card($uid, null, $found);
            return;

        case 'rsearch':
            receipt_find_card($uid, null, (string) $values['value'], $uid);
            return;

        case 'psearch':
            panel_find_card($uid, null, (string) $values['value']);
            return;

        case 'usersearch':
            $query = trim((string) $values['value']);
            $tgId = preg_replace('/\D/', '', $query) ?? '';
            if ($tgId !== '' && user_get((int) $tgId) !== null) {
                /* شناسه دقیق ⇒ مستقیم کارت کاربر */
                screen_user_card($uid, null, (int) $tgId);
                return;
            }
            if ($tgId !== '' && $tgId === $query && user_get((int) $tgId) === null) {
                /* شناسهٔ ناشناس: هیچ ردیفی ساخته نمی‌شود */
                Tg::send($uid, '🔎 کاربری با شناسهٔ <code>' . e($tgId) . "</code> در ربات نیست.\n"
                    . '<i>هیچ ردیفی هم برای این شماره ثبت نشد.</i>',
                    [[btn('🔎 جستجوی دیگر', 'ad:usearch', null, 'success')],
                     [btn('« کاربران', 'ad:users', null, 'danger')]]);
                return;
            }
            if (str_starts_with($query, '@')) {
                $query = substr($query, 1);
            }
            screen_users($uid, null, 1, $query);
            return;

        case 'reffield':
            $field = (string) ($ctx['field'] ?? '');
            $value = (int) ($values['value'] ?? 0);
            if ($field === 'percent') {
                $value = max(0, min(100, $value));
                set_put('ref_percent', (string) $value);
            } elseif ($field === 'min') {
                $value = max(0, $value);
                set_put('ref_min', (string) $value);
            } elseif ($field === 'cash') {
                $value = max(0, $value);
                set_put('ref_cash', (string) $value);
            } elseif ($field === 'maxdep') {
                /* قانون طلایی: ۱ یا ۲ واریزی؛ بیش از آن پذیرفته نمی‌شود */
                $value = max(1, min(2, $value));
                set_put('ref_max_deposits', (string) $value);
            }
            screen_referral_settings($uid, null);
            return;

        case 'panel_api':
            $name = trim((string) ($values['name'] ?? ''));
            $url = normalize_panel_url(trim((string) ($values['url'] ?? '')));
            $apiKey = trim((string) ($values['api_key'] ?? ''));
            if ($url === '' || $apiKey === '') {
                Tg::send($uid, '❌ اطلاعات ناقص است. دوباره «➕ افزودن پنل» را بزنید و کامل کنید.',
                    [[btn('➕ افزودن پنل', 'ad:pg:new', null, 'success')]]);
                return;
            }
            if (!str_contains($apiKey, 'pg_key_')) {
                State::set($uid, 'panel_key_confirm',
                    ['name' => $name, 'url' => $url, 'api_key' => $apiKey]);
                Tg::send($uid, "⚠️ این کلید شبیه کلید API پاسارگارد نیست (باید با "
                    . '<code>pg_key_</code> شروع شود).' . "\n\n"
                    . 'اگر همین را از پنل گرفته‌ای، تأیید کنید:',
                    [[btn('✅ همین کلید درست است', 'ad:pg:savekey', null, 'success')],
                     [btn('🔁 کلید را دوباره بفرستید', 'ad:pg:newapi'),
                      btn('« لغو', 'ad:panel', null, 'danger')]]);
                return;
            }
            panel_save_api($uid, $name, $url, $apiKey);
            return;

        case 'panel_key':
            $panelId = (int) ($ctx['panel_id'] ?? 0);
            $apiKey = trim((string) ($values['api_key'] ?? ''));
            if ($panelId <= 0 || $apiKey === '') {
                Tg::send($uid, 'کلید خالی بود؛ تغییری ندادم.',
                    [[btn('« پنل‌ها', 'ad:panel', null, 'danger')]]);
                return;
            }
            DB::exec('UPDATE pg_panels SET api_key=?, last_ok_at=0, last_error=NULL WHERE id=?',
                [$apiKey, $panelId]);
            $row = DB::one('SELECT * FROM pg_panels WHERE id=?', [$panelId]);
            [$okTest, $note] = $row ? panel_test($row) : [false, 'پنل پیدا نشد'];
            Tg::send($uid, ($okTest ? '✅ ' : '⚠️ ') . 'کلید API ذخیره شد.' . "\n\n" . e($note),
                [[btn('🎭 نقش‌های این پنل', 'ad:role:' . $panelId . ':0:0', null, 'success')],
                 [btn('« پنل', 'ad:pg:' . $panelId, null, 'danger')]]);
            return;

        case 'pg_edit':
            $panelId = (int) ($ctx['panel_id'] ?? 0);
            $panelRow = DB::one('SELECT * FROM pg_panels WHERE id=?', [$panelId]);
            if ($panelId <= 0 || $panelRow === null) {
                Tg::send($uid, 'این پنل پیدا نشد.', [[btn('« پنل‌ها', 'ad:panel', null, 'danger')]]);
                return;
            }
            $newName = trim((string) ($values['name'] ?? ''));
            $newUrl = trim((string) ($values['url'] ?? ''));
            /* «-» یعنی همین مقدار بماند */
            if (in_array($newName, ['-', '—', 'skip'], true)) {
                $newName = '';
            }
            if (in_array($newUrl, ['-', '—', 'skip'], true)) {
                $newUrl = '';
            }
            $changed = [];
            if ($newName !== '' && $newName !== (string) $panelRow['name']) {
                DB::exec('UPDATE pg_panels SET name=? WHERE id=?', [$newName, $panelId]);
                $changed[] = 'نام';
            }
            if ($newUrl !== '') {
                $clean = normalize_panel_url($newUrl);
                if ($clean !== '' && $clean !== (string) $panelRow['url']) {
                    DB::exec('UPDATE pg_panels SET url=?, last_ok_at=0 WHERE id=?',
                        [$clean, $panelId]);
                    $changed[] = 'آدرس';
                }
            }
            Tg::send($uid, $changed
                ? '✅ ' . implode(' و ', $changed) . ' به‌روزرسانی شد.'
                : 'چیزی تغییر نکرد.',
                [[btn('« داشبورد پنل', 'ad:pg:' . $panelId, null, 'success')]]);
            screen_pg_panel($uid, null, $panelId);
            return;

        case 'report_chat':
            $raw = trim((string) ($values['chat'] ?? ''));
            [$reportOk, $reportNote] = report_group_setup($raw);
            Tg::send($uid, ($reportOk ? '' : '⚠️ ') . $reportNote,
                [[btn('📢 گروه گزارشات', 'ad:report', null, 'success')],
                 [btn('« مدیریت', 'ad:home', null, 'danger')]]);
            return;

        case 'bc_text':
            $text = trim((string) $values['text']);
            if ($text === '') {
                Tg::send($uid, 'متن خالی بود؛ چیزی ارسال نشد.', [[btn('« پیام همگانی', 'ad:bc')]]);
                return;
            }
            $targets = bc_targets(bc_segment());
            if (!$targets) {
                Tg::send($uid, 'برای این مخاطب کاربری پیدا نشد.',
                    [[btn('🎯 تغییر مخاطب', 'ad:bc:seg', null, 'success')]]);
                return;
            }
            /* ارسال همگانی در پس‌زمینه: ربات هیچ‌وقت قفل نمی‌کند و تایم‌اوت نمی‌دهد */
            bc_job_start($targets, 'text', $text, 0, 0, set_bool('bc_pin', false),
                $uid, '📣 ارسال همگانی تمام شد', BC_SEGMENTS[bc_segment()]);
            Tg::send($uid, '🚀 <b>ارسال همگانی در پس‌زمینه آغاز شد</b>' . "\n" . SEP . "\n"
                . '🎯 مخاطب: ' . BC_SEGMENTS[bc_segment()] . "\n"
                . '👥 تعداد کل: ' . fa_digits(count($targets)) . "\n\n"
                . '<i>پیام‌ها یکی‌یکی و با فاصله ارسال می‌شوند؛ گزارش کامل '
                . '(تعداد کل / موفق / مسدود شده توسط کاربر) همین‌جا برایت می‌آید. '
                . 'می‌توانی ربات را عادی استفاده کنی.</i>',
                [[btn('« پیام همگانی', 'ad:bc', null, 'success')]]);
            bc_job_dispatch();
            return;
    }
    Tg::send($uid, 'ویزارد نامعتبر.', console_kb());
}

/** اولین نقش غیرمالک پنل را برمی‌گرداند تا محصول بدون پرسش اضافه ساخته شود. */
function auto_role_id(array $panelRow): int
{
    try {
        $client = new PgPanel($panelRow);
        foreach ($client->roles() as $role) {
            if (empty($role['is_owner'])) {
                return (int) ($role['id'] ?? 0);
            }
        }
    } catch (Throwable $ex) {
        log_line('warning', 'auto_role_id failed: ' . $ex->getMessage());
    }
    return 0;
}

/* 16) Router — callbacks */

function report_exception(Throwable $ex, int $uid, string $where): void
{
    $message = $ex->getMessage() . ' @ ' . basename($ex->getFile()) . ':' . $ex->getLine();
    log_line('error', $where . ': ' . $message);
    try {
        post_report('⚠️ <b>خطای داخلی</b>' . "\n" . 'جا: <code>' . e($where) . "</code>\n"
            . 'پیام: <code>' . e(mb_substr($message, 0, 300)) . '</code>', 'error');
    } catch (Throwable $ignored) {
    }
    if (is_admin($uid)) {
        Tg::send($uid, "❌ <b>خطای داخلی</b>\n\n" . e(mb_substr($message, 0, 300))
            . "\n\n<i>این متن را برای پشتیبانی بفرستید.</i>",
            [[btn('« مدیریت', 'ad:home', null, 'danger')]]);
        return;
    }
    Tg::send($uid, '❌ یک خطای موقت پیش آمد. یک‌بار دیگر تلاش کنید.',
        [[btn('« منو', 'home', null, 'danger')]]);
}

function handle_callback(array $cb): void
{
    Tg::$answered = [];   // هر آپدیت، پاسخ‌های خودش را دارد
    try {
        handle_callback_inner($cb);
    } catch (Throwable $ex) {
        report_exception($ex, (int) ($cb['from']['id'] ?? 0), 'callback:'
            . (string) ($cb['data'] ?? ''));
    } finally {
        /* اگر هیچ دکمه‌ای جواب نداد، همان‌جا یک پاسخ بی‌صدا بفرستید تا دکمه معلق نماند */
        if (Tg::$pendingAnswer !== null) {
            $pending = Tg::$pendingAnswer;
            Tg::$pendingAnswer = null;
            Tg::answer($pending);
        }
    }
}

function handle_callback_inner(array $cb): void
{
    $uid = (int) ($cb['from']['id'] ?? 0);
    $GLOBALS['panel_act_uid'] = $uid;
    $chatId = (int) ($cb['message']['chat']['id'] ?? $uid);
    $chatType = (string) ($cb['message']['chat']['type'] ?? 'private');
    $messageId = (int) ($cb['message']['message_id'] ?? 0);
    $data = (string) ($cb['data'] ?? '');
    $cbId = (string) ($cb['id'] ?? '');
    if ($uid === 0 || $data === '') {
        return;
    }
    if ($data === 'nav:back' || str_starts_with($data, 'nav:back:')) {
        Tg::answer($cbId);
        State::clear($uid);   // «بازگشت» هیچ نیمه‌کاره‌ای باقی نمی‌گذارد
        /* بخش هر دکمه جداست: بازگشت در پنل مدیریت همان‌جا یک قدم عقب می‌رود،
           و اگر عقب‌تر نبود به صفحهٔ اصلی خرید برمی‌گردد */
        $scope = str_ends_with($data, ':ad') ? 'ad' : 'user';
        $prev = nav_back($uid, $scope);
        if ($prev === '') {
            show_home($chatId, $messageId, $uid);
            return;
        }
        $GLOBALS['panel_nav_skip'] = true;
        try {
            handle_callback_inner(['id' => $cbId, 'from' => $cb['from'] ?? ['id' => $uid],
                'message' => $cb['message'] ?? ['message_id' => $messageId,
                    'chat' => ['id' => $chatId, 'type' => 'private']], 'data' => $prev]);
        } finally {
            $GLOBALS['panel_nav_skip'] = false;
        }
        return;
    }
    if (empty($GLOBALS['panel_nav_skip'])) {
        nav_push($uid, $data);
    }
    if (in_array($chatType, ['group', 'supergroup', 'channel'], true)) {
        // دکمه‌های داخل گروه کار نمی‌کنند؛ پنل مدیریت هم داخل گروه اجرا نمی‌شود
        Tg::answer($cbId, 'این دکمه‌ها فقط در چت خصوصی ربات کار می‌کنند.', true);
        return;
    }
    $userRow = user_ensure($uid, trim((string) ($cb['from']['first_name'] ?? '') . ' '
        . (string) ($cb['from']['last_name'] ?? '')), (string) ($cb['from']['username'] ?? ''));
    if ((int) ($userRow['is_blocked'] ?? 0) === 1 && !is_admin($uid)) {
        Tg::answer($cbId, '⛔️ دسترسی حسابتان بسته شده است.', true);
        return;
    }
    $parts = explode(':', $data);
    $head = $parts[0];
    /* دامنهٔ صفحهٔ جاری برای دکمهٔ بازگشت */
    $GLOBALS['panel_nav_scope'] = str_starts_with($data, 'ad:') ? 'ad' : 'user';

    /* ── ماژول احراز هویت (KYC) ─────────────────────────────────────── */
    /* ── قفل عضویت اجباری کانال ─────────────────────────────────────── */
    if ($data === 'fj:check') {
        /* دکمهٔ تایید عضویت: فقط همین یک دکمه همیشه باز است */
        if (force_join_blocked($uid)) {
            Tg::answer($cbId, '⚠️ عضویت شما تایید نشد. اول در کانال عضو شوید.', true);
            force_join_show($chatId, $messageId);
            return;
        }
        Tg::answer($cbId, '✅ عضویت تایید شد.');
        State::clear($uid);
        show_home($chatId, $messageId, $uid);
        return;
    }
    if (force_join_blocked($uid)) {
        Tg::answer($cbId, '⚠️ اول در کانال عضو شوید', true);
        force_join_show($chatId, $messageId);
        return;
    }

    if ($head === 'kyc') {
        Tg::answer($cbId);
        kyc_callback($uid, $chatId, $messageId, $parts);
        return;
    }


    /* ── انتخاب دکمه‌ای داخل ویزارد ──────────────────────────────────── */
    if ($head === 'wiz') {
        wiz_pick($uid, (int) ($parts[1] ?? 0), $chatId, $messageId);
        return;
    }
    if ($head === 'wizrole') {
        $op = (string) ($parts[2] ?? '');
        if ($op === 'page' || $op === 'refresh') {
            // پیمایش نقش‌ها بدون از دست رفتن ویزارد
            $state = State::get($uid);
            if ($state['state'] !== 'wiz') {
                Tg::send($chatId, 'این انتخاب منقضی شده.',
                    [[btn('« مدیریت', 'ad:home', null, 'danger')]]);
                return;
            }
            $data = $state['data'];
            $panelId = (int) ($parts[1] ?? 0);
            $page = $op === 'page' ? max(1, (int) ($parts[3] ?? 1)) : 1;
            if ($op === 'refresh' && $panelId > 0) {
                roles_cache($panelId, true);
            }
            $data['ctx']['role_page'] = $page;
            State::set($uid, 'wiz', $data);
            wiz_render($uid, $data, $chatId, $messageId);
            return;
        }
        wiz_pick($uid, (int) ($parts[2] ?? 0), $chatId, $messageId);
        return;
    }

    Tg::answer_later($cbId);

    /* ── منوی کاربر ───────────────────────────────────────────────────── */
    if ($data === 'home') {
        State::clear($uid);
        show_home($chatId, $messageId, $uid);
        return;
    }
    if ($head === 'menu') {
        $what = $parts[1] ?? '';
        switch ($what) {
            case 'buy':
                screen_buy($chatId, $messageId, $uid);
                return;
            case 'panels':
                screen_panels($chatId, $messageId, $uid);
                return;
            case 'wallet':
                screen_wallet($chatId, $messageId, $uid);
                return;
            case 'slots':
                screen_slots($chatId, $messageId, $uid);
                return;
            case 'support':
                show_support($chatId, $messageId, $uid);
                return;
            case 'track':
                /* فهرست سفارش‌ها حذف شد؛ فقط جستجو با کد پیگیری */
                wiz_start($uid, 'trackcode', [
                    step_def('value', 'کد پیگیری (همان کدی که بعد از پرداخت گرفتی) یا شمارهٔ سفارش را بفرستید.',
                        'text', null, '🔎 پیگیری با کد'),
                ]);
                return;
            case 'orders':
                /* مسیر قدیمی: حالا مستقیم به جستجوی کد می‌رود */
                wiz_start($uid, 'trackcode', [
                    step_def('value', 'کد پیگیری سفارش را بفرستید.', 'text', null, '🔎 پیگیری با کد'),
                ]);
                return;
            case 'trial':
                screen_trial($chatId, $messageId, $uid);
                return;
            case 'ref':
                /* لینک از یوزرنیم رسمی ربات ساخته می‌شود (تنظیمات → .env → getMe) */
                $link = ref_link($uid);
                $percent = set_int('ref_percent', 10);
                $minBuy = set_int('ref_min', 0);
                $invited = (int) DB::val('SELECT COUNT(*) FROM users WHERE referred_by=?',
                    [$uid], 0);
                $paidRef = (int) DB::val('SELECT COUNT(*) FROM users WHERE referred_by=? '
                    . 'AND ref_paid=1', [$uid], 0);
                $earned = (int) DB::val('SELECT COALESCE(SUM(amount),0) FROM wallet_tx '
                    . "WHERE tg_id=? AND kind='ref'", [$uid], 0);
                [$freeSlots, $boughtSlots, $usedSlots] = slots_total($uid);
                $text = "🎁 <b>دعوت دوستان</b>\n\n"
                    . '🧩 اسلات: ' . fa_digits($freeSlots + $boughtSlots)
                    . ' · مصرف‌شده: ' . fa_digits($usedSlots) . "\n"
                    . '💰 موجودی: <b>' . money(balance_of($uid)) . "</b>\n\n"
                    . '👥 دعوت‌شده: <b>' . fa_digits($invited) . '</b> · خرید کرده: '
                    . fa_digits($paidRef) . "\n"
                    . '🎉 درآمد از دعوت: <b>' . money($earned) . "</b>\n\n"
                    . (ref_mode() === 'cash'
                        ? 'به‌ازای هر نفری که با لینک شما وارد ربات شود، '
                            . money(set_int('ref_cash', 10000)) . ' به کیف پولتان اضافه می‌شود.'
                        : 'به‌ازای واریزی اول و دوم هر نفر، ' . fa_digits($percent)
                            . '٪ به کیف پولتان اضافه می‌شود'
                            . ($minBuy > 0 ? ' (واریز بالای ' . money($minBuy) . ')' : ''))
                    . "\n\n"
                    . ($link !== ''
                        ? 'لینک اختصاصی شما:' . "\n<code>" . e($link) . '</code>'
                        : '⚠️ لینک دعوت ساخته نشد: یوزرنیم ربات تنظیم نشده است.');
                if (!set_bool('ref_enabled', true)) {
                    $text .= "\n\n🔴 برنامهٔ دعوت فعلاً خاموش است.";
                }
                $refRows = [];
                if ($link !== '') {
                    $refRows[] = [btn('📤 اشتراک‌گذاری لینک', null,
                        ref_share_url($link, '🎁 با لینک من در ' . bot_name() . ' عضو شو'),
                        'success')];
                    $refRows[] = [btn('⚡️ ارسال سریع در تلگرام', null,
                        ref_share_deeplink($link, '🎁 با لینک من در ' . bot_name() . ' عضو شو'),
                        'primary')];
                    $refRows[] = [btn('📋 فرستادن لینک به دوست', 'ref:share', null, 'primary')];
                }
                $refRows[] = [btn('« بازگشت', 'home', null, 'danger')];
                Tg::show($chatId, $messageId, $text, $refRows);
                return;
        }
    }
    if ($data === 'menu:admin') {
        if (!is_staff($uid)) {
            Tg::answer($cbId, '⛔️ فقط برای مدیر', true);
            return;
        }
        screen_console($chatId, $messageId);
        return;
    }
    if ($head === 'ref') {
        $link = ref_link($uid);
        if ($link === '') {
            Tg::answer($cbId, '⚠️ یوزرنیم ربات تنظیم نشده است.', true);
            $fetched = bot_username_fetch();      // یک‌بار دیگر از خود تلگرام
            $link = $fetched !== '' ? ref_link($uid) : '';
            if ($link === '') {
                Tg::show($chatId, $messageId,
                    "⚠️ <b>تلگرام یوزرنیم ربات را برنگرداند</b>\n\n"
                    . 'ربات خودکار با <code>getMe</code> یوزرنیمش را می‌خواند؛ این بار '
                    . 'پاسخ نداد (قطعی موقت شبکه یا توکن نامعتبر).' . "\n\n"
                    . 'چند لحظه بعد دوباره بزنید. اگر تکرار شد:'
                    . "\n" . '<code>sibil doctor</code>',
                    [[btn('🔄 تلاش دوباره', 'ref:share', null, 'primary')],
                     [btn('« دعوت دوستان', 'menu:ref', null, 'danger')]]);
                return;
            }
        }
        Tg::answer($cbId, '📤 لینک آمادهٔ ارسال است', false);
        Tg::send($chatId, '📤 <b>لینک اختصاصی شما</b>' . "\n" . SEP . "\n"
            . '<code>' . e($link) . '</code>' . "\n\n"
            . 'با یک ضربه روی لینک کپی می‌شود؛ با دکمهٔ زیر مستقیم در تلگرام '
            . 'برای دوستتان بفرستید.' . "\n\n"
            . '🎁 پاداش شما: ' . (ref_mode() === 'cash'
                ? money(set_int('ref_cash', 10000)) . ' نقدی برای هر عضو جدید'
                : fa_digits(set_int('ref_percent', 10)) . '٪ از واریزی اول و دوم'),
            [[btn('📲 ارسال به مخاطب تلگرام', null,
                ref_share_url($link, '🎁 با لینک من در ' . bot_name() . ' عضو شو'),
                'success')],
             [btn('⚡️ ارسال سریع (tg)', null,
                ref_share_deeplink($link, '🎁 با لینک من در ' . bot_name() . ' عضو شو'),
                'primary')],
             [btn('« دعوت دوستان', 'menu:ref', null, 'danger')]]);
        return;
    }
    if ($head === 'help') {
        $admin = is_owner($uid);
        if ($data === 'help:home') {
            Tg::show($chatId, $messageId,
                "🎓 <b>راهنما</b>\n\nیک بخش را انتخاب کنید یا جستجو کنید.",
                help_home_kb($admin));
            return;
        }
        if ($data === 'help:search') {
            State::set($uid, 'help_search');
            Tg::show($chatId, $messageId,
                "🔎 <b>جستجوی راهنما</b>\n\nبنویسید دنبال چه چیزی هستی؛ "
                . 'مثلاً: <code>شارژ</code>، <code>تعلیق</code>، <code>کد تخفیف</code>.',
                [[btn('« لغو', 'help:home', null, 'danger')]]);
            return;
        }
        if (str_starts_with($data, 'help:s:')) {
            $key = $parts[2] ?? '';
            $pool = help_pool($admin);
            if (!isset($pool[$key])) {
                Tg::show($chatId, $messageId, 'این بخش پیدا نشد.', help_home_kb($admin));
                return;
            }
            Tg::show($chatId, $messageId,
                '<b>' . e($pool[$key]['title']) . "</b>\n\n" . help_body($key, $pool[$key]),
                [[btn('« راهنما', 'help:home', null, 'danger')]]);
            return;
        }
    }
    if ($head === 'buy') {
        $what = $parts[1] ?? '';
        if ($what === 'cat') {
            screen_buy_category($chatId, $messageId, (int) ($parts[2] ?? 0));
            return;
        }
        if ($what === 'p') {
            screen_product($chatId, $messageId, (int) ($parts[2] ?? 0));
            return;
        }
        if ($what === 'confirm') {
            $product = product_get((int) ($parts[2] ?? 0));
            if ($product === null) {
                Tg::show($chatId, $messageId, 'محصول پیدا نشد.', home_kb($uid));
                return;
            }
            if (slots_available($uid) < (int) $product['slots_needed']) {
                Tg::show($chatId, $messageId,
                    '🧩 اسلات آزاد کافی ندارید.' . "\n" . 'از «🧩 اسلات‌ها» اسلات بخر.',
                    [[btn('🧩 اسلات‌ها', 'menu:slots', null, 'success')],
                     [btn('« بازگشت', 'home', null, 'danger')]]);
                return;
            }
            $minBalance = (int) $product['min_balance'];
            if ($minBalance > 0 && balance_of($uid) < $minBalance) {
                Tg::show($chatId, $messageId,
                    '💰 <b>حداقل موجودی لازم</b>' . "\n\n"
                    . 'برای این محصول باید حداقل <b>' . money($minBalance) . '</b> موجودی داشته باشید.'
                    . "\n" . 'موجودی فعلی: ' . money(balance_of($uid)) . "\n\n"
                    . 'کیف پولتان را شارژ کنید و دوباره بیا.',
                    [[btn('💳 شارژ کیف پول', 'menu:wallet', null, 'success')],
                     [btn('« بازگشت', 'menu:buy', null, 'danger')]]);
                return;
            }
            screen_username_choice($chatId, $messageId, (int) $product['id'], 'buy');
            return;
        }
        if ($what === 'exact') {
            $product = product_get((int) ($parts[2] ?? 0));
            if ($product === null) {
                return;
            }
            $perGb = (int) $product['per_gb_price'];
            $hourly = (int) $product['hourly_price'];
            $text = "🔢 <b>قیمت دقیق بر اساس مصرف</b>\n\n"
                . 'قیمت هر گیگ: ' . money($perGb) . "\n"
                . 'اجارهٔ ساعتی: ' . money($hourly) . "\n\n";
            foreach ([1, 5, 10, 50, 100] as $gb) {
                $text .= '· ' . fa_digits($gb) . ' گیگ → ' . money($gb * $perGb) . "\n";
            }
            $hours = prepaid_hours();
            $text .= "\n" . 'اجارهٔ روزانه (۲۴ ساعت): ' . money($hourly * 24) . "\n"
                . 'پیش‌پرداخت ' . fa_digits($hours) . ' ساعت اول: <b>'
                . money(panel_prepaid_amount($product)) . '</b>' . "\n\n"
                . '🧮 فرمول: پیش‌پرداخت ساعت‌های اول + (گیگ مصرف‌شده × قیمت هر گیگ) + '
                . '(ساعت فعال × اجارهٔ ساعتی)';
            Tg::show($chatId, $messageId, $text,
                [[btn('« بازگشت', 'buy:p:' . $product['id'], null, 'danger')]]);
            return;
        }
    }
    if ($head === 'wallet') {
        $what = $parts[1] ?? '';
        if ($what === 'amt') {
            $amount = (int) ($parts[2] ?? 0);
            $min = set_int('min_topup', 50000);
            $max = set_int('max_topup', 20000000);
            if ($amount < $min || $amount > $max) {
                Tg::send($chatId, 'مبلغ باید بین ' . money($min) . ' و ' . money($max) . ' باشد.');
                return;
            }
            $order = create_order($uid, 'topup', $amount, null, ['topup' => $amount]);
            Tg::show($chatId, $messageId,
                invoice_text($order, 'شارژ کیف پول', 'مبلغ شارژ: ' . money($amount)),
                invoice_kb($order, $uid));
            return;
        }
        if ($what === 'charge') {
            State::set($uid, 'topup_amount');
            Tg::show($chatId, $messageId,
                '💰 مبلغ شارژ را به تومان بفرستید.' . "\n" . 'حداقل '
                . money(set_int('min_topup', 50000)),
                [[btn('« لغو', 'menu:wallet', null, 'danger')]]);
            return;
        }
    }
    if ($head === 'inv') {
        $what = $parts[1] ?? '';
        $orderId = (int) ($parts[2] ?? 0);
        $order = order_get($orderId);
        if ($order === null || (int) $order['tg_id'] !== $uid) {
            Tg::show($chatId, $messageId, 'این سفارش معتبر نیست.', home_kb($uid));
            return;
        }
        if ($what === 'wallet') {
            [$ok, $text] = pay_from_wallet($order);
            if ($ok) {
                Tg::show($chatId, $messageId, $text, home_kb($uid));
            } else {
                /* شکست باید با دلیل و پیام دیده شود، نه یک تولتیپ گذرا */
                Tg::answer($cbId, 'پرداخت انجام نشد', true);
                Tg::send($chatId, '❌ ' . $text,
                    [[btn('🔁 تلاش دوباره', 'inv:back:' . (int) $order['id'], null, 'success')],
                     [btn('« خانه', 'home', null, 'danger')]]);
            }
            return;
        }
        if ($what === 'zero') {
            [$ok, $text] = settle_payment($order, 'free');
            Tg::show($chatId, $messageId, $text, home_kb($uid));
            return;
        }
        if ($what === 'gw') {
            screen_gateways($chatId, $messageId, $order);
            return;
        }
        if ($what === 'code') {
            if (!discount_allowed_for((string) $order['kind'])) {
                Tg::answer($cbId, 'کد تخفیف فقط برای خرید پنل و محصول است، نه شارژ کیف پول.', true);
                return;
            }
            State::set($uid, 'discount_order', ['order_id' => (int) $order['id']]);
            Tg::show($chatId, $messageId,
                "🏷 <b>ثبت کد تخفیف</b>\n\n"
                . 'کد تخفیفت را بفرستید تا روی همین سفارش اعمال شود.' . "\n"
                . 'برای لغو: <code>لغو</code>',
                [[btn('« بازگشت به سفارش', 'inv:back:' . $order['id'], null, 'danger')]]);
            return;
        }
        if ($what === 'back') {
            State::clear($uid);
            Tg::show($chatId, $messageId,
                invoice_text($order, 'پرداخت سفارش'), invoice_kb($order, $uid));
            return;
        }
        if ($what === 'pay') {
            $gw = (string) ($parts[3] ?? '');
            /* مهلت پرداخت واقعاً اعمال می‌شود: اگر فاکتور از حد گذشته باشد هیچ
               درگاهی باز نمی‌شود و سفارش بسته می‌شود — نه فقط یک نوشته. */
            payments_expire(set_int('pay_expire_minutes', 30));
            $fresh = order_get((int) $order['id']);
            if ($fresh === null || $fresh['status'] !== 'pending') {
                $minutes = max(1, set_int('pay_expire_minutes', 30));
                Tg::show($chatId, $messageId,
                    '⌛️ <b>مهلت پرداخت تمام شد</b>' . "\n\n"
                    . 'این فاکتور ' . fa_digits($minutes) . ' دقیقه اعتبار داشت و اکنون بسته شد.'
                    . "\n" . 'هیچ مبلغی از کیف پولتان کم نشد.' . "\n\n"
                    . 'یک سفارش تازه بساز تا فاکتور جدید بگیرید.',
                    [[btn('🔁 سفارش تازه', 'home', null, 'success')],
                     [btn('📦 پنل‌های من', 'menu:panels', null, 'primary')]]);
                return;
            }
            if ($gw === 'wallet') {
                [$ok, $text] = pay_from_wallet($order);
                if ($ok) {
                    Tg::show($chatId, $messageId, $text, home_kb($uid));
                } else {
                    Tg::answer($cbId, 'پرداخت انجام نشد', true);
                    Tg::send($chatId, '❌ ' . $text,
                        [[btn('🔁 تلاش دوباره', 'inv:back:' . (int) $order['id'], null, 'success')],
                         [btn('« بازگشت', 'home', null, 'danger')]]);
                }
                return;
            }
            if ($gw === 'card') {
                /* سقف ریالی فقط همین‌جا و فقط برای کارت‌به‌کارت اعمال می‌شود؛
                   کریپتو و استارز هیچ سقفی ندارند. */
                if (kyc_guard_gateway($chatId, $messageId, $uid, $fresh)) {
                    return;
                }
                screen_card_payment($chatId, $messageId, $uid, $order);
                return;
            } else {
                $result = pay_start($order, $gw);
                if (!$result['ok']) {
                    Tg::answer($cbId, $result['text'], true);
                    screen_gateways($chatId, $messageId, $order, $result['text']);
                    return;
                }
                if (($result['url'] ?? '') !== '') {
                    $gwType = PAY_GATEWAYS[$gw]['type'] ?? 'online';
                    $paymentRow = DB::one('SELECT * FROM payments WHERE order_id=? AND method=? '
                        . "AND status='unpaid' ORDER BY id DESC LIMIT 1", [(int) $order['id'], $gw]);
                    $invoiceNo = (string) ($paymentRow['authority'] ?? '');
                    pay_note_message((int) $order['id'], $gw, (int) $messageId);
                    if ($gwType === 'crypto') {
                        /* قالب پیام تأیید */
                        $meta = $paymentRow ? pay_meta($paymentRow) : [];
                        Tg::show($chatId, $messageId,
                            crypto_invoice_header($order, (string) ($result['text'] ?: $gw))
                            . "\n\n" . crypto_invoice_text($order, (string) $gw, $invoiceNo,
                                (float) ($meta['fiat_amount'] ?? 0)),
                            [[btn('💳 پرداخت', null, (string) $result['url'], 'success')],
                             [btn('« بازگشت', 'inv:gw:' . $order['id'], null, 'danger')]]);
                        return;
                    }
                    pay_note_message((int) $order['id'], $gw, (int) $messageId);
                    Tg::show($chatId, $messageId,
                        '🌐 <b>پرداخت ' . e($result['text']) . "</b>\n\n"
                        . 'مبلغ: <b>' . money((int) $order['payable']) . "</b>\n"
                        . 'کد سفارش: <code>' . e((string) $order['ref']) . "</code>\n\n"
                        . 'روی دکمهٔ زیر بزنید و پرداخت را کامل کنید. ' .
                        'بعد از پرداخت خودکار به همین‌جا برمی‌گردی.',
                        [[btn('💳 پرداخت ' . money((int) $order['payable']),
                            null, $result['url'], 'success')],
                         [btn('« بازگشت', 'inv:gw:' . $order['id'], null, 'danger')]]);
                    return;
                }
            }
        }
        if ($what === 'card') {
            screen_card_payment($chatId, $messageId, $uid, $order);
            return;
        }
    }
    if ($head === 'pay' && ($parts[1] ?? '') === 'receipt') {
        /* دکمهٔ «واریز کردم، ارسال رسید» — کاربر را در حالت انتظار عکس می‌گذارد */
        $orderId = (int) ($parts[2] ?? 0);
        $order = $orderId > 0 ? order_get($orderId) : null;
        if ($order === null || (int) $order['tg_id'] !== $uid) {
            Tg::show($chatId, $messageId, 'این سفارش معتبر نیست.', home_kb($uid));
            return;
        }
        if ((string) $order['status'] !== 'pending' && (string) $order['status'] !== 'review') {
            Tg::show($chatId, $messageId,
                '⌛️ این سفارش دیگر باز نیست.' . "\n" . 'یک سفارش تازه بساز.',
                [[btn('💳 شارژ کیف پول', 'menu:wallet', null, 'success')],
                 [btn('« خانه', 'home', null, 'danger')]]);
            return;
        }
        State::set($uid, 'receipt', ['order_id' => $orderId]);
        Tg::show($chatId, $messageId,
            '📷 <b>عکس رسید را همین‌جا بفرستید</b>' . "\n\n"
            . 'کد سفارش: <code>' . e((string) $order['ref']) . '</code>' . "\n"
            . 'مبلغ: <b>' . money((int) $order['payable']) . '</b>' . "\n\n"
            . '<i>عکس واریزی یا فایل تصویری — هر کدام راحت‌تر است.</i>',
            [[btn('« لغو', 'home', null, 'danger')]]);
        return;
    }
    if ($head === 'pn') {
        $panel = DB::one('SELECT * FROM panels WHERE id=? AND tg_id=?',
            [(int) ($parts[1] ?? 0), $uid]);
        if ($panel === null) {
            Tg::show($chatId, $messageId, 'پنل پیدا نشد.', home_kb($uid));
            return;
        }
        $panelId = (int) $panel['id'];
        $op = (string) ($parts[2] ?? '');
        $product = $panel['product_id'] ? product_get((int) $panel['product_id']) : null;
        $blockSize = (int) ($product['extra_block_size'] ?? 1000) ?: 1000;
        $blockPrice = (int) ($product['extra_block_price'] ?? 0);
        if ($op === 'extra') {
            if ($blockPrice <= 0) {
                Tg::answer($cbId, 'برای این محصول بلاک اضافه تعریف نشده.', true);
                return;
            }
            $order = create_order($uid, 'users', $blockPrice, (int) $panel['product_id'],
                ['panel_id' => $panelId, 'block' => $blockSize]);
            Tg::show($chatId, $messageId,
                invoice_text($order, 'افزودن ' . fa_digits($blockSize) . ' کاربر',
                    '📦 پنل <code>' . e((string) $panel['panel_username']) . '</code>'),
                invoice_kb($order, $uid));
            return;
        }
        if ($op === 'disc') {
            if ((int) ($panel['discount_until'] ?? 0) > now_ts()) {
                Tg::answer($cbId, 'روی این پنل تخفیف فعال داری؛ بعد از پایانش کد جدید بزنید.', true);
                return;
            }
            State::set($uid, 'discount_panel', ['panel_id' => $panelId]);
            Tg::send($chatId,
                "🏷 <b>ثبت کد تخفیف روی این پنل</b>\n"
                . SEP . "\n"
                . 'کد تخفیف خود را ارسال کنید.' . "\n\n"
                . '💡 تخفیف به صورت خودکار روی تعرفهٔ مصرف هر گیگابایت این پنل اعمال می‌شود.',
                [[btn('❌ لغو', 'pn:' . $panelId . ':disccancel', null, 'danger')],
                 [btn('« پنل', 'pn:' . $panelId, null, 'primary')]]);
            return;
        }
        if ($op === 'disccancel') {
            State::clear($uid);
            Tg::answer($cbId, 'لغو شد', false);
            screen_panel_detail($chatId, $messageId, $panelId);
            return;
        }
        if ($op === 'sync') {
            panel_sync_now($panel);
            Tg::answer($cbId, 'اطلاعات از پنل خوانده شد', false);
            screen_panel_detail($chatId, $messageId, (int) $panel['id']);
            return;
        }
        if ($op === 'del') {
            if ((int) ($panel['is_trial'] ?? 0) === 1) {
                Tg::show($chatId, $messageId,
                    '🧪 پنل تست دستی حذف نمی‌شود.' . "\n\n"
                    . 'همین‌که زمان تستش تمام شود خودکار پاک می‌شود.',
                    [[btn('« پنل', 'pn:' . $panelId, null, 'danger')]]);
                return;
            }
            $blockPrice = (int) ($product['extra_block_price'] ?? 0);
            unset($blockPrice);
            /* هشدار: پیش‌پرداخت ساعت‌های اول غیرقابل استرداد است */
            $prepaid = (int) ($panel['prepaid_amount'] ?? 0);
            $warn = '';
            if ($prepaid > 0 && panel_prepaid_remaining($panel) > 0) {
                $warn = "\n" . '⚠️ <b>توجه:</b> پیش‌پرداخت ' . fa_digits(prepaid_hours())
                    . ' ساعت اول این پنل (<b>' . money($prepaid) . '</b>) '
                    . 'در صورت حذف <b>بازگردانده نمی‌شود</b>.';
            }
            Tg::show($chatId, $messageId,
                "🗑 <b>حذف پنل</b>\n\n"
                . 'پنل <code>' . e((string) $panel['panel_username']) . "</code> از روی پنل و از "
                . "ربات حذف می‌شود.\n"
                . '<i>این کار برگشت‌پذیر نیست.</i>'
                . $warn,
                [[btn('✅ بله، حذف کنید', 'pn:' . $panelId . ':delok', null, 'danger')],
                 [btn('« انصراف', 'pn:' . $panelId, null, 'primary')]]);
            return;
        }
        if ($op === 'delok') {
            [$okDel, $noteDel] = panel_delete_own($panel);
            Tg::answer($cbId, $okDel ? 'حذف شد' : 'حذف روی پنل انجام نشد', !$okDel);
            Tg::send($chatId, ($okDel ? '' : '⚠️ ') . $noteDel,
                [[btn('« پنل‌های من', 'menu:panels', null, 'primary')]]);
            return;
        }
        if ($op === 'pass') {
            screen_panel_password($chatId, $messageId, (int) $panel['id']);
            return;
        }
        if ($op === 'passnew') {
            [$okPass, $notePass] = panel_change_password((int) $panel['id'], '');
            Tg::send($chatId, ($okPass ? '' : '⚠️ ') . $notePass,
                [[btn('« پنل', 'pn:' . $panelId, null, 'danger')]]);
            return;
        }
        if ($op === 'passset') {
            wiz_start($uid, 'panel_pass', [
                step_def('password', 'رمز تازه را بفرستید — حداقل ۸ کاراکتر، با حرف بزرگ، رقم و نماد '
                    . '(مثل <code>7P20g8Z!ot%k</code>)', 'text', null, '🔑 رمز دلخواه'),
            ], ['panel_id' => $panelId]);
            return;
        }
        if ($op === 'sec') {
            screen_panel_security($chatId, $messageId, (int) $panel['id']);
            return;
        }
        if ($op === 'hwreset') {
            [$okHw, $noteHw] = panel_reset_devices((int) $panel['id']);
            Tg::send($chatId, ($okHw ? '' : '⚠️ ') . $noteHw,
                [[btn('« امنیت پنل', 'pn:' . $panelId . ':sec', null, 'primary')]]);
            return;
        }
        screen_panel_detail($chatId, $messageId, $panelId);
        return;
    }
    if ($head === 'slot' && ($parts[1] ?? '') === 'buy') {
        $price = set_int('slot_price', 150000);
        $order = create_order($uid, 'slot', $price, null, ['count' => 1]);
        Tg::show($chatId, $messageId,
            invoice_text($order, 'خرید اسلات', '🧩 یک اسلات اضافه'),
            invoice_kb($order, $uid));
        return;
    }
    if (str_starts_with($data, 'trial:p:')) {
        screen_trial_product($chatId, $messageId, $uid, (int) substr($data, 8));
        return;
    }
    if (str_starts_with($data, 'trial:go:')) {
        $productId = (int) substr($data, 9);
        $product = product_get($productId);
        if ($product === null || (int) $product['active'] !== 1) {
            Tg::answer($cbId, 'این محصول فعال نیست.', true);
            screen_trial($chatId, $messageId, $uid);
            return;
        }
        $isManager = admin_trial_unlimited($uid);
        if (!$isManager && trial_used($uid) >= max(1, set_int('trial_per_user', 1))) {
            Tg::answer($cbId, 'سهمیهٔ تستت تمام شده.', true);
            screen_trial($chatId, $messageId, $uid);
            return;
        }
        screen_username_choice($chatId, $messageId, $productId, 'trial');
        return;
    }
    if ($head === 'uname') {
        $mode = (string) ($parts[1] ?? '');
        $productId = (int) ($parts[2] ?? 0);
        $how = (string) ($parts[3] ?? '');
        $product = product_get($productId);
        if ($product === null || (int) $product['active'] !== 1) {
            Tg::answer($cbId, 'این محصول فعال نیست.', true);
            show_home($chatId, $messageId, $uid);
            return;
        }
        if ($how === 'rand') {
            $name = random_panel_username();
            if ($mode === 'trial') {
                start_trial_order($uid, $chatId, $messageId, $productId, $name);
            } else {
                start_panel_order($uid, $chatId, $messageId, $productId, $name);
            }
            return;
        }
        if ($how === 'custom') {
            State::set($uid, 'panel_username', ['mode' => $mode, 'product' => $productId]);
            Tg::show($chatId, $messageId,
                '✍️ <b>نام کاربری دلخواه</b>' . "\n\n"
                . 'نام کاربری پنل را بفرستید.' . "\n"
                . 'فقط حروف انگلیسی، عدد و _ · بین ۳ تا ۳۲ حرف.' . "\n\n"
                . '<i>اگر تکراری باشد، همین‌جا می‌گویم و می‌توانید نام دیگری بفرستید.</i>' . "\n"
                . 'برای لغو: <code>لغو</code>',
                [[btn('« بازگشت', 'nav:back', null, 'danger')]]);
            return;
        }
        screen_username_choice($chatId, $messageId, $productId, $mode === 'trial' ? 'trial' : 'buy');
        return;
    }
    if ($data === 'cancel') {
        /* لغو ویزارد هم فقط یک قدم عقب می‌رود، نه پرش به صفحهٔ اول */
        State::clear($uid);
        $prevCancel = nav_back($uid, 'user');
        if ($prevCancel === '') {
            show_home($chatId, $messageId, $uid);
            return;
        }
        $GLOBALS['panel_nav_skip'] = true;
        try {
            handle_callback_inner(['id' => $cbId, 'from' => $cb['from'] ?? ['id' => $uid],
                'message' => $cb['message'] ?? ['message_id' => $messageId,
                    'chat' => ['id' => $chatId, 'type' => 'private']],
                'data' => $prevCancel]);
        } finally {
            $GLOBALS['panel_nav_skip'] = false;
        }
        return;
    }

    /* ── دکمه‌های کپی (کارت به کارت) ──────────────────────────────────── */
    if ($head === 'pay' && ($parts[1] ?? '') === 'copy') {
        Tg::answer($cbId, '📋 آمادهٔ کپی');
        $orderId = (int) ($parts[2] ?? 0);
        $what = (string) ($parts[3] ?? '');
        $order = $orderId > 0 ? order_get($orderId) : null;
        if ($order === null || (int) $order['tg_id'] !== $uid) {
            Tg::send($chatId, 'این سفارش پیدا نشد.',
                [[btn('« منوی اصلی', 'home', null, 'danger')]]);
            return;
        }
        /* دکمه‌های کپی حالا با copy_text کار می‌کنند؛ این مسیر فقط برای
           پیام‌های قدیمی مانده و همان کارت را با یک دکمهٔ کپی واقعی می‌فرستد */
        $card = preg_replace('/[^0-9]/', '', set_get('card_number')) ?? '';
        if ($what === 'card') {
            if ($card === '') {
                Tg::send($chatId, 'شمارهٔ کارت تنظیم نشده؛ با پشتیبانی تماس بگیرید.',
                    [[btn('« منوی اصلی', 'home', null, 'danger')]]);
                return;
            }
            Tg::send($chatId, '📋 <b>شماره کارت</b>' . "\n" . 'صاحب کارت: '
                . e(set_get('card_holder')),
                [[copy_btn('📋 کپی شماره کارت', $card)],
                 [btn('« خانه', 'home', null, 'danger')]]);
            return;
        }
        $toman = (int) $order['payable'];
        Tg::send($chatId, '📋 <b>مبلغ به ریال</b>' . "\n" . '(' . rial_text($toman) . ')',
            [[copy_btn('📋 کپی مبلغ', rial_digits($toman))],
             [btn('« خانه', 'home', null, 'danger')]]);
        return;
    }

    /* ── مدیریت ───────────────────────────────────────────────────────── */
    /* ── 📢 قفل کانال اجباری (مسیر مستقیم پنل مدیریت) ─────────────────── */
    if ($head === 'fj') {
        if (!is_owner($uid)) {
            Tg::answer($cbId, '⛔️ این بخش فقط برای مالک ربات است.', true);
            return;
        }
        $op = (string) ($parts[1] ?? '');
        if ($op === 'on') {
            if (force_channel_raw() === '') {
                Tg::answer($cbId, '🔗 اول آیدی کانال را تنظیم کنید.', true);
                Tg::show($chatId, $messageId,
                    "⚠️ هنوز کانالی تنظیم نشده است.\n\n" . force_channel_admin_text(),
                    force_channel_admin_kb());
                return;
            }
            $new = !set_bool('force_channel_on', false);
            set_put('force_channel_on', $new ? '1' : '0');
            Tg::answer($cbId, $new ? '🟢 قفل روشن شد.' : '🔴 قفل خاموش شد.');
        } elseif ($op === 'set') {
            State::set($uid, 'fj_channel');
            Tg::show($chatId, $messageId,
                "🔗 <b>تنظیم کانال اجباری</b>\n" . SEP . "\n"
                . 'آیدی یا لینک کانال را بفرستید:' . "\n"
                . '· <code>@my_channel</code>' . "\n"
                . '· <code>https://t.me/my_channel</code>' . "\n"
                . '· یا شناسهٔ عددی <code>-1001234567890</code>' . "\n\n"
                . '<i>ربات باید در آن کانال «مدیر» باشد؛ وگرنه ذخیره نمی‌شود.</i>',
                [[btn('🔙 انصراف / بازگشت', 'ad:fj', null, 'danger')]]);
            return;
        } elseif ($op === 'del') {
            set_put('force_channel_id', '');
            set_put('force_channel_on', '0');
            Tg::answer($cbId, '🗑 کانال اجباری حذف شد.');
        }
        State::clear($uid);
        Tg::show($chatId, $messageId, force_channel_admin_text(), force_channel_admin_kb());
        return;
    }

    if ($head !== 'ad') {
        Tg::send($chatId, 'این دکمه دیگر معتبر نیست.', home_kb($uid));
        return;
    }
    if (!is_owner($uid)) {
        Tg::answer($cbId, '⛔️ پنل مدیریت فقط برای مالک ربات باز است.', true);
        Tg::send($chatId, '⛔️ این بخش فقط برای مالک ربات است.', home_kb($uid));
        return;
    }
    /* ⛔️ قفل اجباری: تا ثبت گروه گزارشات، فقط همان یک دکمه کار می‌کند */
    if (report_required() && $data !== 'ad:home' && !str_starts_with($data, 'ad:report')) {
        Tg::answer($cbId, '📢 اول گروه گزارشات را تنظیم کنید', true);
        screen_console($chatId, $messageId);
        screen_report_setup($chatId, null,
            '⚠️ برای دسترسی به این بخش، ابتدا گروه گزارشات را تنظیم کنید.');
        return;
    }
    $action = $parts[1] ?? '';
    switch ($action) {
        case 'fj':
            Tg::show($chatId, $messageId, force_channel_admin_text(),
                force_channel_admin_kb());
            return;
        case 'home':
            screen_console($chatId, $messageId);
            return;
        case 'g':
            $map = ['sales' => 'ad:finance', 'shop' => 'ad:cats', 'panels' => 'ad:panel',
                    'tools' => 'ad:tools'];
            $target = $map[$parts[2] ?? ''] ?? 'ad:home';
            handle_callback(['id' => $cbId, 'from' => ['id' => $uid],
                'message' => ['chat' => ['id' => $chatId], 'message_id' => $messageId],
                'data' => $target]);
            return;
        case 'help':
            Tg::show($chatId, $messageId,
                "❓ <b>راهنمای بخش مدیریت</b>\n\n"
                . 'همه‌چیز از دکمه‌ها انجام می‌شود؛ هیچ دستور ترمینالی لازم نیست.',
                [[btn('🔌 افزودن پنل پاسارگارد', 'help:s:adpanel', null, 'success')],
                 [btn('🗂 دسته و محصول', 'help:s:adcat'), btn('💳 مالی', 'help:s:adfin')],
                 [btn('📢 گروه گزارشات و بکاپ', 'help:s:adreport')],
                 [btn('« مدیریت', 'ad:home', null, 'danger')]]);
            return;
        case 'rolep':
            // گام ۱: کدام پنل؟ گام ۲: نقش‌های همان پنل
            $productId = (int) ($parts[2] ?? 0);
            $product = $productId > 0 ? product_get($productId) : null;
            $panels = DB::all('SELECT * FROM pg_panels WHERE active=1 ORDER BY is_default DESC, id');
            if (!$panels) {
                Tg::show($chatId, $messageId,
                    "🔌 هیچ پنلی وصل نیست، پس نقشی هم برای انتخاب نیست.\n"
                    . 'اول پنل را با کلید API وصل کنید.',
                    [[btn('➕ افزودن پنل', 'ad:pg:new', null, 'success')],
                     [btn('« محصول', 'ad:prod:' . $productId, null, 'danger')]]);
                return;
            }
            $current = $product['panel_id'] ?? null;
            $rows = [];
            foreach ($panels as $panelRow) {
                $mark = ((int) $current === (int) $panelRow['id']) ? '✅ ' : '🔌 ';
                $rows[] = [btn($mark . e((string) $panelRow['name']),
                    'ad:role:' . $panelRow['id'] . ':0:' . $productId, null,
                    ((int) $current === (int) $panelRow['id']) ? 'success' : 'primary')];
            }
            $rows[] = [btn('« محصول', 'ad:prod:' . $productId, null, 'danger')];
            Tg::show($chatId, $messageId,
                "🎭 <b>نقش این محصول از کدام پنل؟</b>\n\n"
                . 'اول پنل را انتخاب کن؛ بعد ربات نقش‌های همان پنل را از خودش می‌خواند.',
                $rows);
            return;
        case 'role':
            $panelId = (int) ($parts[2] ?? 0);
            $roleId = (int) ($parts[3] ?? 0);
            $productId = (int) ($parts[4] ?? 0);
            if (($parts[3] ?? '') === 'refresh') {
                roles_cache($panelId, true);
                screen_roles($chatId, $messageId, $panelId, (int) ($parts[4] ?? 0));
                return;
            }
            if (($parts[3] ?? '') === 'page') {
                $page = (int) ($parts[4] ?? 1);
                screen_roles($chatId, $messageId, $panelId, (int) ($parts[5] ?? 0), $page);
                return;
            }
            if ($roleId <= 0) {
                screen_roles($chatId, $messageId, $panelId, $productId);
                return;
            }
            if ($productId > 0) {
                product_set_role($productId, $roleId, $panelId);
                Tg::answer($cbId, '✅ نقش تنظیم شد', false);
                screen_product_admin($chatId, $messageId, $productId);
                return;
            }
            // انتخاب نقش داخل ویزارد ساخت محصول
            $state = State::get($uid);
            if ($state['state'] === 'wiz') {
                wiz_pick($uid, $roleId, $chatId, $messageId);
                return;
            }
            Tg::show($chatId, $messageId, 'این انتخاب منقضی شده.',
                [[btn('« مدیریت', 'ad:home', null, 'danger')]]);
            return;
        case 'ref':
            $op = (string) ($parts[2] ?? '');
            if ($op === 'toggle') {
                set_put('ref_enabled', set_bool('ref_enabled', true) ? '0' : '1');
                screen_referral_settings($chatId, $messageId);
                return;
            }
            if ($op === 'mode') {
                $mode = (string) ($parts[3] ?? 'percent');
                set_put('ref_mode', $mode === 'cash' ? 'cash' : 'percent');
                Tg::answer($cbId, $mode === 'cash' ? 'پاداش نقدی ثابت فعال شد'
                    : 'پاداش درصدی فعال شد', false);
                screen_referral_settings($chatId, $messageId);
                return;
            }
            if ($op === 'when') {
                set_put('ref_cash_when', ref_cash_when() === 'join' ? 'purchase' : 'join');
                Tg::answer($cbId, ref_cash_when() === 'join'
                    ? '💵 پاداش نقدی: لحظهٔ عضویت' : '🛒 پاداش نقدی: اولین خرید', false);
                screen_referral_settings($chatId, $messageId);
                return;
            }
            if (in_array($op, ['percent', 'min', 'cash', 'maxdep'], true)) {
                $current = [
                    'percent' => set_int('ref_percent', 10),
                    'min'     => set_int('ref_min', 0),
                    'cash'    => set_int('ref_cash', 10000),
                    'maxdep'  => ref_max_deposits(),
                ][$op];
                $labels = [
                    'percent' => 'درصد پورسانت از هر واریز (0 تا 100)',
                    'min'     => 'حداقل مبلغ واریز برای پرداخت پورسانت (تومان)',
                    'cash'    => 'مبلغ پاداش نقدی هر دعوت (تومان)',
                    'maxdep'  => 'تعداد واریزی‌های اول که پورسانت دارند (پیش‌فرض 2)',
                ];
                wiz_start($uid, 'reffield', [
                    step_def('value', $labels[$op] . "\n" . 'مقدار فعلی: ' . $current,
                        'int', null, '🎁 دعوت دوستان'),
                ], ['field' => $op]);
                return;
            }
            screen_referral_settings($chatId, $messageId);
            return;
        case 'usearch':
            wiz_start($uid, 'usersearch', [
                step_def('value', 'بخشی از نام، یوزرنیم یا شناسهٔ عددی کاربر را بفرستید',
                    'text', null, '🔎 جستجوی کاربر'),
            ]);
            return;
        case 'stats':
            screen_stats($chatId, $messageId);
            return;
        case 'receipts':
            screen_receipts($chatId, $messageId);
            return;
        case 'rsearch':
            wiz_start($uid, 'rsearch', [
                step_def('value', 'کد پیگیری سفارش (یا شمارهٔ رسید) را بفرستید.', 'text', null,
                    '🔎 جستجوی رسید'),
            ]);
            return;
        case 'psearch':
            wiz_start($uid, 'psearch', [
                step_def('value', 'نام کاربری پنل را بفرستید (همان نامی که موقع ساخت ساخته شد).',
                    'text', null, '🔎 جستجوی پنل'),
            ]);
            return;
        case 'rc':
            [$ok, $note] = review_receipt((int) ($parts[2] ?? 0), ($parts[3] ?? '') === 'ok', $uid);
            Tg::answer($cbId, $note, !$ok);
            Tg::send($chatId, ($ok ? '✅ ' : '⚠️ ') . $note, console_kb());
            return;
        case 'finance':
            screen_finance($chatId, $messageId);
            return;
        case 'paygrp':
            screen_pay_group($chatId, $messageId, (string) ($parts[2] ?? 'fiat'));
            return;
        case 'late':
            /* تصمیم مدیر دربارهٔ واریزی بعد از انقضا */
            $reject = (string) ($parts[2] ?? '') === 'no';
            $payId = (int) ($parts[$reject ? 3 : 2] ?? 0);
            $payment = $payId > 0 ? pay_get($payId) : null;
            if ($payment === null) {
                Tg::answer($cbId, 'این پرداخت پیدا نشد.', true);
                return;
            }
            if ($reject) {
                DB::exec("UPDATE payments SET status='rejected' WHERE id=? AND status='expire'",
                    [$payId]);
                Tg::answer($cbId, 'رد شد.');
                Tg::show($chatId, $messageId, '❌ پرداخت <code>' . $payId
                    . '</code> رد شد و شارژ نشد.');
                return;
            }
            $result = pay_settle($payId, 'admin-late', ['by' => $uid], true);
            Tg::answer($cbId, ($result['ok'] ?? false) ? 'شارژ شد.' : 'انجام نشد.', true);
            Tg::show($chatId, $messageId, ($result['ok'] ?? false)
                ? '✅ پرداخت <code>' . $payId . '</code> تأیید و کیف پول کاربر شارژ شد.'
                : '❌ ' . e((string) ($result['text'] ?? 'انجام نشد')));
            return;
        case 'pay':
            $gw = (string) ($parts[2] ?? '');
            if ($gw === '') {
                screen_pay_gateways($chatId, $messageId);
                return;
            }
            if ($gw === 'swap') {
                $op = (string) ($parts[3] ?? '');
                if ($op === 'key') {
                    wiz_start($uid, 'swapkey', [
                        step_def('value', "کلید API سواپ‌ولت را بفرستید.\n"
                            . 'قالب: <code>apikey-...</code>' . "\n"
                            . 'مسیر دریافت: پروفایل ← کلید API ← ایجاد کلید جدید',
                            'text', null, '💎 سواپ‌ولت'),
                    ], []);
                    return;
                }
                if ($op === 'test') {
                    $test = swap_selftest();
                    $text = "🧪 <b>تست زندهٔ سواپ‌ولت</b>\n\n"
                        . 'آدرس: <code>' . e($test['url']) . "</code>\n"
                        . 'کد HTTP: <b>' . ($test['http'] > 0 ? (string) $test['http'] : 'بدون پاسخ')
                        . "</b>\n"
                        . 'زمان پاسخ: ' . $test['ms'] . " میلی‌ثانیه\n"
                        . 'وضعیت: ' . ($test['ok'] ? '🟢 سالم' : '🔴 خطا') . "\n\n";
                    if ($test['ok']) {
                        $text .= 'دلار (USDT/IRT): <b>' . money($test['usdt']) . "</b>\n"
                            . 'ترون (TRX/IRT): <b>' . money($test['trx']) . "</b>\n\n";
                    } elseif ($test['error'] !== '') {
                        $text .= 'خطا: <code>' . e($test['error']) . "</code>\n\n";
                    }
                    $text .= '<b>پاسخ خام</b>' . "\n<code>" . e($test['body']) . '</code>';
                    Tg::show($chatId, null, $text,
                        [[btn('🔄 دوباره تست', 'ad:pay:swap:test', null, 'primary')],
                         [btn('« سواپ‌ولت', 'ad:pay:swap', null, 'danger')]]);
                    return;
                }
                if ($op === 'refresh') {
                    swap_rates(true);
                    swap_star_usdt(true);
                    screen_swap($chatId, $messageId, true);
                    return;
                }
                screen_swap($chatId, $messageId);
                return;
            }
            $op = (string) ($parts[3] ?? '');
            if ($op === 'toggle' && isset(PAY_GATEWAYS[$gw])) {
                set_put('pay_' . $gw . '_on', set_get('pay_' . $gw . '_on', '1') === '1' ? '0' : '1');
                screen_pay_gateway($chatId, $messageId, $gw);
                return;
            }
            if ($op === 'test') {
                $test = gw_live_test($gw);
                $text = '🧪 <b>تست زندهٔ ' . e(PAY_GATEWAYS[$gw]['label']) . "</b>\n\n"
                    . 'آدرس: <code>' . e((string) ($test['endpoint'] ?? '—')) . "</code>\n"
                    . 'مبلغ تست: ' . money((int) ($test['amount'] ?? 0)) . "\n"
                    . 'نتیجه: ' . ($test['ok'] ? '🟢 ' : '🔴 ') . e((string) $test['title']) . "\n\n"
                    . '<b>پاسخ درگاه:</b>' . "\n<code>"
                    . e(mb_substr((string) $test['body'], 0, 400)) . '</code>';
                if (!empty($test['url'])) {
                    $text .= "\n\nلینک پرداخت تست:" . "\n" . e((string) $test['url']);
                }
                Tg::show($chatId, null, $text,
                    [[btn('🔄 دوباره تست', 'ad:pay:' . $gw . ':test', null, 'success')],
                     [btn('« ' . PAY_GATEWAYS[$gw]['label'], 'ad:pay:' . $gw, null, 'danger')]]);
                return;
            }
            if (in_array($op, ['key', 'key2', 'min', 'max', 'cashback', 'minfiat', 'endpoint'], true)) {
                $labels = ['key' => 'کلید درگاه (API key / merchant / pin)',
                           'key2' => 'کلید دوم (secret / endpoint / آدرس کیف پول / IPN)',
                           'min' => 'حداقل مبلغ برای این درگاه (تومان)',
                           'max' => 'حداکثر مبلغ برای این درگاه (تومان)',
                           'minfiat' => 'حداقل تراکنش این درگاه (دلار، 0 = خودکار از خود درگاه)',
                           'endpoint' => 'آدرس سرویس درگاه (با https؛ خالی = پیش‌فرض رسمی)',
                           'cashback' => 'درصد کش‌بک این درگاه (0 = بدون کش‌بک)'];
                $current = match ($op) {
                    'key' => set_get('pay_' . $gw . '_key'),
